import "dotenv/config";
import * as Sentry from "@sentry/node";

if (process.env.SENTRY_DSN) {
  Sentry.init({
    dsn: process.env.SENTRY_DSN,
    environment: process.env.NODE_ENV || "development",
    tracesSampleRate: 0.1,
  });
}

// Setup process.env compat parameters for bundled client config references
if (process.env.NODE_ENV !== "production") {
  process.env.DEV = "true";
  process.env.PROD = "";
} else {
  process.env.DEV = "";
  process.env.PROD = "true";
}

import http from "http";
import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";
import cors from "cors";
import helmet from "helmet";
import compression from "compression";
import { promises as fsPromises } from "fs";
import { doc, getDoc } from "firebase/firestore";

import { startProductPublisherWorker } from "./src/workers/productPublisher";

// Cache in-memory HTML for production
let cachedHtmlTemplate = "";

// Simple in-memory product cache with TTL and LRU eviction policy to prevent memory leaks
class EvictingMap<K, V> extends Map<K, V> {
  constructor(private maxKeys = 1000) {
    super();
  }
  set(key: K, value: V): this {
    if (this.size >= this.maxKeys && !this.has(key)) {
      const firstKey = this.keys().next().value;
      if (firstKey !== undefined) {
        this.delete(firstKey);
      }
    }
    return super.set(key, value);
  }
}

const productCache = new EvictingMap<string, { data: any, timestamp: number }>(1000);
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

// Periodically clean up expired entries to prevent memory leaks
setInterval(() => {
  const now = Date.now();
  for (const [key, value] of productCache.entries()) {
    if (now - value.timestamp > CACHE_TTL) {
      productCache.delete(key);
    }
  }
}, 10 * 60 * 1000);

// Imports extracted into modules
import { admin, db, clientDb, verifyAndFixDb } from "./src/config/firebase-admin";

