const app = express();
const PORT = 3000;
const httpServer = http.createServer(app);

// Tell Express to trust reverse proxy headers securely by whitelisting trusted local and internal subnets
app.set('trust proxy', 1);

import rateLimit from "express-rate-limit";

const apiLimiter = rateLimit({
  windowMs: 1 * 60 * 1000, // 1 minute
  max: 2000, // Augmenté de 100 à 2000 pour éviter les faux-positifs dans l'iframe/proxy Cloud Run
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.setHeader("Content-Type", "application/json; charset=utf-8");
    res.status(429).json({ error: "Trop de requêtes, veuillez réessayer dans une minute." });
  }
});

const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 30, // Augmenté de 5 à 30 pour la fluidité des tests
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.setHeader("Content-Type", "application/json; charset=utf-8");
    res.status(429).json({ error: "Trop de tentatives de connexion, veuillez réessayer dans 15 minutes." });
  }
});

const pinLimiter = rateLimit({
  windowMs: 5 * 60 * 1000, // 5 minutes
  max: 15, // Augmenté de 3 à 15 pour la fluidité des tests
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.setHeader("Content-Type", "application/json; charset=utf-8");
    res.status(429).json({ error: "Trop de tentatives de vérification, veuillez réessayer dans 5 minutes." });
  }
});

const strictLimiter = rateLimit({
  windowMs: 1 * 60 * 1000,
  max: 300, // Augmenté de 10 à 300 pour éviter les limitations intempestives
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.setHeader("Content-Type", "application/json; charset=utf-8");
    res.status(429).json({ error: "Trop de requêtes, veuillez réessayer dans une minute." });
  }
});

app.use("/api/auth/login", loginLimiter);
app.use("/api/auth/verify", pinLimiter);
app.use("/api/chat", strictLimiter);
app.use("/api/place-order", strictLimiter);
app.use("/api/v1", apiLimiter);
app.use("/api", apiLimiter);

app.use(helmet({
  contentSecurityPolicy: {
    useDefaults: false,
    reportOnly: true, // Deployer en mode report-only pendant 1 semaine
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'", "'unsafe-eval'", "https://apis.google.com", "https://www.gstatic.com", "https://www.googletagmanager.com", "https://*.googletagmanager.com", "https://cdn.jsdelivr.net"],
      styleSrc: ["'self'", "'unsafe-inline'", "https://fonts.googleapis.com", "https://cdn.jsdelivr.net"],
      fontSrc: ["'self'", "https://fonts.gstatic.com", "data:", "https://cdn.jsdelivr.net"],
      imgSrc: ["'self'", "data:", "blob:", "https://firebasestorage.googleapis.com", "https://lh3.googleusercontent.com", "https://images.unsplash.com", "https://api.qrserver.com", "https://*.transparenttextures.com", "https://www.transparenttextures.com"],
      connectSrc: ["'self'", "https://*.googleapis.com", "wss:", "ws:"],
      frameSrc: ["'self'", "https://*.firebaseapp.com", "https://*.google.com", "https://apis.google.com"],
      frameAncestors: ["'self'", "https://aistudio.google.com", "https://*.google.com", "https://ai.studio", "https://*.ai.studio"],
      objectSrc: ["'none'"],
      upgradeInsecureRequests: [],
      reportUri: '/api/v1/csp-report',
    },
  },
  crossOriginEmbedderPolicy: false,
  crossOriginResourcePolicy: false,
  crossOriginOpenerPolicy: false,
  xFrameOptions: false,
}));

// CSP Report endpoint
app.post('/api/v1/csp-report', express.json({type: 'application/csp-report'}), (req, res) => {
  console.warn('CSP Violation: ', req.body);
  res.status(204).end();
});
app.use(compression());

const allowedOrigins = [
  "https://aistudio.google.com",
];

const corsOptions = {
  origin: (origin: string | undefined, callback: (err: Error | null, allow?: boolean) => void) => {
    if (!origin) return callback(null, true);

    const isAllowed = allowedOrigins.includes(origin) || 
                      /^https:\/\/ais-.*\.europe-west2\.run\.app$/.test(origin) || 
                      /^http:\/\/localhost:\d+$/.test(origin);

    if (isAllowed) {
      callback(null, true);
    } else {
      callback(new Error("Accès refusé par la politique de CORS OLMART"));
    }
  },
  credentials: true,
  methods: ["GET", "POST", "PUT", "DELETE", "PATCH", "OPTIONS"],
  allowedHeaders: ["Content-Type", "Authorization", "X-Requested-With"]
};

app.use(cors(corsOptions));
app.use(express.json({ limit: "2mb" }));
app.use(express.urlencoded({ limit: "2mb", extended: true }));

// Health Check Endpoint (supports both legacy and new /api/v1/health version)
app.get(["/api/health", "/api/v1/health"], async (req, res) => {
  const checks = {
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    memory: process.memoryUsage(),
    firebase: "unknown",
  };

  try {
    await admin.firestore().collection("_health").doc("ping").get();
    checks.firebase = "ok";
  } catch (e) {
    checks.firebase = "error";
  }

  const allOk = checks.firebase === "ok";
  res.status(allOk ? 200 : 503).json({
    status: allOk ? "healthy" : "unhealthy",
    ...checks,
  });
});

import swaggerUi from 'swagger-ui-express';
import swaggerJsdoc from 'swagger-jsdoc';
import { OpenAPIRegistry, OpenApiGeneratorV3, extendZodWithOpenApi } from '@asteasolutions/zod-to-openapi';
import { z } from 'zod';

extendZodWithOpenApi(z);

const registry = new OpenAPIRegistry();

// Example registration (to be expanded in individual routes)
registry.registerPath({
  method: 'get',
  path: '/api/v1/health',
  summary: 'Health check',
  responses: {
    200: {
      description: 'System is healthy',
      content: {
        'application/json': {
          schema: z.object({ status: z.string() }).openapi('HealthResponse')
        }
      }
    }
  }
});

const generator = new OpenApiGeneratorV3(registry.definitions);
const openApiDocument = generator.generateDocument({
  openapi: '3.0.0',
  info: {
    version: '1.0.0',
    title: 'Olma API v1',
    description: 'API for Olma Marketplace. Deprecation strategies are enforced for /api endpoints, please use /api/v1.',
  },
  servers: [{ url: '/api/v1' }],
});

const swaggerOptions = {
  definition: openApiDocument,
  apis: ['./src/routes/*.ts'], // Fallback for jsdoc
};
const swaggerSpec = swaggerJsdoc(swaggerOptions);
app.use('/api-docs', swaggerUi.serve, swaggerUi.setup(swaggerSpec));

const debugLimiter = rateLimit({
  windowMs: 5 * 60 * 1000,
  max: 20,
  handler: (req, res) => {
    res.setHeader("Content-Type", "application/json; charset=utf-8");
    res.status(429).json({ error: "Trop de requêtes debug." });
  }
});
app.use("/api/debug", debugLimiter);

// Versioning deprecation middleware
const loggedDeprecations = new Set<string>();
const deprecationMiddleware = (req: Request, res: Response, next: NextFunction) => {
  const url = req.originalUrl || "";
  if (
    url.includes("/v1/") ||
    url.includes("/api/public/") ||
    url.includes("/api/products") ||
    url.includes("/api/search") ||
    url.includes("/api/auth/2fa/") ||
    url.includes("/api/messages/") ||
    url.includes("/api/proxy-video")
  ) {
    return next();
  }
  res.setHeader("X-API-Version", "v1");

  // Clean up dynamic IDs in the URL for deduplication (e.g. replace numbers or Firestore-like IDs)
  const normalizedUrl = url.replace(/\/[a-zA-Z0-9_-]{15,}/g, "/:id").split("?")[0];

  if (!loggedDeprecations.has(normalizedUrl)) {
    loggedDeprecations.add(normalizedUrl);
    console.warn(`[Deprecation Warning] ⚠️ Legacy endpoint accessed: "${normalizedUrl}". Please migrate the client-side call to the secure "/api/v1" prefix. (Warning logged once)`);
  }
  next();
};

