async function setupVite(server: any) {
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({ 
      server: { 
        middlewareMode: true,
        hmr: {
          server: server,
          path: '/vite-hmr'
        }
      }, 
      appType: "spa" 
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use('/locales', express.static(path.join(distPath, 'locales'), { maxAge: '1y' }));
    app.use(express.static(distPath, { index: false }));

    // PERFORMANCE : Lecture du fichier index.html UNE SEULE FOIS au démarrage
    try {
      cachedHtmlTemplate = await fsPromises.readFile(path.join(distPath, 'index.html'), 'utf-8');
    } catch (e) {
      console.error("Erreur de chargement du template HTML:", e);
    }

    app.get('/', (req, res) => {
      res.send(cachedHtmlTemplate);
    });

    app.get('/product/:id', async (req, res) => {
      try {
        const productId = req.params.id;
        let product: any = null;

        // Check cache first
        const cached = productCache.get(productId);
        if (cached && (Date.now() - cached.timestamp < CACHE_TTL)) {
          product = cached.data;
        } else {
          // Fetch from Firestore using optimized Admin SDK (db) or fallback to clientDb
          if (db) {
            const productSnap = await db.collection('products').doc(productId).get();
            if (productSnap.exists) {
              product = productSnap.data();
              productCache.set(productId, { data: product, timestamp: Date.now() });
            }
          } else if (clientDb) {
            const productSnap = await getDoc(doc(clientDb, 'products', productId));
            if (productSnap.exists()) {
              product = productSnap.data();
              productCache.set(productId, { data: product, timestamp: Date.now() });
            }
          }
        }

        let html = cachedHtmlTemplate || "";

        if (product) {
          const title = product.name || 'Olma Marketplace';
          const description = (product.description || 'Découvrez ce produit sur Olma Marketplace.').substring(0, 160).replace(/"/g, '&quot;');
          const images = product.images || [];
          const image = images.length > 0 ? images[0] : (product.image || '');

          // Extraire la date de dernière modification de manière sécurisée (R50)
          let lastmod = "";
          const rawDate = product.updatedAt || product.updated_at || product.created_at;
          if (rawDate) {
            try {
              if (typeof rawDate.toDate === "function") {
                lastmod = rawDate.toDate().toISOString();
              } else if (rawDate instanceof Date) {
                lastmod = rawDate.toISOString();
              } else if (typeof rawDate === "string" || typeof rawDate === "number") {
                const d = new Date(rawDate);
                if (!isNaN(d.getTime())) {
                  lastmod = d.toISOString();
                }
              }
            } catch (err) {
              // ignore safe
            }
          }

          html = html.replace(/<title>.*?<\/title>/i, `<title>${title} | Olma</title>`);
          let metaTags = `
    <meta property="og:title" content="${title}" />
    <meta property="og:description" content="${description}" />
    <meta property="og:image" content="${image}" />
    <meta name="twitter:card" content="summary_large_image" />
    <meta name="twitter:title" content="${title}" />
    <meta name="twitter:description" content="${description}" />
    <meta name="twitter:image" content="${image}" />`;

          if (lastmod) {
            metaTags += `
    <meta name="last-modified" content="${lastmod}" />
    <meta property="og:updated_time" content="${lastmod}" />
    <meta property="product:modified_time" content="${lastmod}" />`;
          }

          metaTags += `\n</head>`;
          html = html.replace('</head>', metaTags);

          // CDN CLOUDFLARE : Permet de cacher la page du produit pendant 1h sur le CDN
          res.setHeader('Cache-Control', 'public, max-age=3600, s-maxage=3600');
        }
        res.send(html);
      } catch (err) {
        console.error('Erreur SSR Produit:', err);
        res.send(cachedHtmlTemplate);
      }
    });

    app.get('*', (req, res) => res.send(cachedHtmlTemplate));
  }
}

setupVite(httpServer).then(async () => {
  const logDev = (process.env.NODE_ENV === "development" ? console.log : function () {});

  if (process.env.RUN_MIGRATIONS === "true") {
    logDev("[Database] 🔄 Running startup database checks and migrations...");
    try {
      await verifyAndFixDb();
      logDev("[Database] ✅ Startup database checks and migrations completed successfully.");
    } catch (err: any) {
      console.error("[Database] ❌ Firestore Admin verification/migration failed:", err.message || err);
    }
  } else {
    logDev("[Database] ℹ️ Startup database migration skipped. (Set RUN_MIGRATIONS=true to trigger)");
  }

  startProductPublisherWorker();

  logDev("[Olmart Gateway] 🚀 Booting Express HTTP Server...");
  const server = httpServer.listen(PORT, "0.0.0.0", () => {
    logDev(`[Olmart Gateway] 🟢 Server started successfully on port ${PORT}.`);
    logDev(`[Olmart Gateway] 🔗 URL: http://localhost:${PORT}`);
    logDev("================================================================================");
  });

  // Graceful shutdown handling
  const shutdown = (signal: string) => {
    logDev(`\n[Olmart Gateway] 🛑 Received ${signal}. Shutting down gracefully...`);
    server.close(() => {
      logDev("[Olmart Gateway] 💤 Closed out remaining active connections.");
      process.exit(0);
    });

    // Force close after 10s if connections are hanging
    setTimeout(() => {
      console.error("[Olmart Gateway] ❌ Could not close connections in time, forcefully shutting down.");
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));
});

