  const [categorySearch, setCategorySearch] = useState("");
  const [sellerSearch, setSellerSearch] = useState("");

  // Listen / Fetch Categories and Sellers
  useEffect(() => {
    if (!isOpen) return;

    // Load Categories Hierarchy
    const unsubCat = onSnapshot(doc(db, "settings", "categories"), (snap) => {
      if (snap.exists() && snap.data().hierarchy) {
        const hierarchy = snap.data().hierarchy;
        const catList: string[] = [];
        Object.keys(hierarchy).forEach((cat) => {
          if (!catList.includes(cat)) catList.push(cat);
          Object.keys(hierarchy[cat] || {}).forEach((sub) => {
            if (!catList.includes(sub)) catList.push(sub);
            (hierarchy[cat][sub] || []).forEach((subsub: string) => {
              if (!catList.includes(subsub)) catList.push(subsub);
            });
          });
        });
        setCategoriesList(catList);
      }
    });

    // Load Sellers
    const sellersQuery = query(collection(db, "users"), where("role", "==", "seller"));
    const unsubSellers = onSnapshot(
      sellersQuery,
      (snapshot) => {
        const list: { id: string; name: string; email?: string }[] = [];
        snapshot.forEach((doc) => {
          const data = doc.data();
          list.push({
            id: doc.id,
            name: data.storeName || data.displayName || data.email || doc.id,
            email: data.email,
          });
        });
        setSellersList(list);
      },
      (err) => {
        console.error("Error loading sellers for promo modal:", err);
      }
    );

    return () => {
      unsubCat();
      unsubSellers();
    };
  }, [isOpen]);

  // Filter Categories & Sellers based on search query
  const filteredCategories = useMemo(() => {
    const q = categorySearch.toLowerCase().trim();
    if (!q) return categoriesList;
    return categoriesList.filter((cat) => t(cat).toLowerCase().includes(q) || cat.toLowerCase().includes(q));
  }, [categorySearch, categoriesList, t]);

  const filteredSellers = useMemo(() => {
    const q = sellerSearch.toLowerCase().trim();
    if (!q) return sellersList;
    return sellersList.filter(
      (s) =>
        s.name.toLowerCase().includes(q) ||
        (s.email && s.email.toLowerCase().includes(q)) ||
        s.id.toLowerCase().includes(q)
    );
  }, [sellerSearch, sellersList]);

  const handleToggleCategory = (cat: string) => {
    setSelectedCategories((prev) =>
      prev.includes(cat) ? prev.filter((c) => c !== cat) : [...prev, cat]
    );
  };

  const handleToggleSeller = (sellerId: string) => {
    setSelectedSellers((prev) =>
      prev.includes(sellerId) ? prev.filter((id) => id !== sellerId) : [...prev, sellerId]
    );
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubmitting(true);
    setError("");

    const uppercaseCode = code.trim().toUpperCase();

    try {
      // 1. Validate Uniqueness client-side
      const exists = existingCoupons.some((c) => c.code === uppercaseCode);
      if (exists) {
        throw new Error(
          t("Ce code promo existe déjà ({{code}}). Veuillez utiliser un code unique.", {
            code: uppercaseCode,
          })
        );
      }

      const parsedValue = parseFloat(discountValue);
      const parsedMinPurchase = parseFloat(minOrderValue);
      const parsedUsageLimit = usageLimit ? parseInt(usageLimit, 10) : null;
      const parsedExpiry = new Date(expiresAt);

      if (!uppercaseCode || isNaN(parsedValue) || isNaN(parsedMinPurchase) || isNaN(parsedExpiry.getTime())) {
        throw new Error(t("Veuillez remplir tous les champs obligatoires correctement."));
      }

      // 2. Validate percentage logic
      if (discountType === "percentage" && (parsedValue <= 0 || parsedValue > 100)) {
        throw new Error(t("Le pourcentage de remise doit être compris entre 1% et 100%."));
      }

      if (discountType === "fixed" && parsedValue <= 0) {
        throw new Error(t("La valeur de remise fixe doit être supérieure à 0."));
      }

      if (parsedMinPurchase < 0) {
        throw new Error(t("Le minimum d'achat ne peut pas être négatif."));
      }

      if (parsedExpiry <= new Date()) {
        throw new Error(t("La date d'expiration doit être dans le futur."));
      }

      // 3. Save to Firestore
      await addDoc(collection(db, "coupons"), {
        code: uppercaseCode,
        discountType,
        discountValue: parsedValue,
        minOrderValue: parsedMinPurchase,
        expiresAt: Timestamp.fromDate(parsedExpiry),
        isActive: true,
        usedCount: 0,
        clickCount: 0,
        createdAt: Timestamp.now(),
        limitedToCategories: selectedCategories,
        limitedToSellers: selectedSellers,
        singleUsePerClient,
        ...(parsedUsageLimit !== null ? { usageLimit: parsedUsageLimit } : {}),
      });

      onClose();
      resetForm();
    } catch (err: any) {
      setError(err.message || t("Erreur lors de la création du coupon."));
    } finally {
      setSubmitting(false);
    }
  };

  const resetForm = () => {
    setCode("");
    setDiscountType("percentage");
    setDiscountValue("");
    setMinOrderValue("");
    setExpiresAt("");
    setUsageLimit("");
    setSelectedCategories([]);
    setSelectedSellers([]);
    setSingleUsePerClient(false);
    setCategorySearch("");
    setSellerSearch("");
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-zinc-950/80 z-[110] flex items-center justify-center p-4">
      <div className="bg-white rounded-[2rem] w-full max-w-2xl max-h-[90vh] overflow-hidden shadow-2xl flex flex-col border border-zinc-200">
        <div className="p-6 border-b border-zinc-100 flex justify-between items-center bg-zinc-50/50">
          <div>
            <h3 className="font-sans font-bold text-xl text-zinc-950 uppercase">{t("Créer un Code Promo")}</h3>
            <p className="text-xs text-zinc-500 font-sans mt-0.5">
              {t("Définissez des coupons avec restrictions par catégorie, vendeur, et usage unique.")}
            </p>
          </div>
          <button
            onClick={() => {
              onClose();
              resetForm();
            }}
            className="p-2.5 text-zinc-400 hover:bg-zinc-100 rounded-full transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-6 space-y-6">
          {error && (
            <div className="bg-red-50 text-red-600 p-4 rounded-2xl flex items-center gap-3 text-sm font-medium border border-red-100">
              <AlertCircle className="w-5 h-5 shrink-0" />
              <p className="font-sans leading-relaxed">{error}</p>
            </div>
          )}

          <div className="space-y-4 font-sans">
            {/* Promo Code & Usage Limit */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-bold text-zinc-700 uppercase tracking-wider mb-2">
                  {t("Code Promo")} <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  required
                  maxLength={20}
                  value={code}
                  onChange={(e) => setCode(e.target.value.toUpperCase())}
                  placeholder={t("EX: RAMADAN26")}
                  className="w-full px-4 py-3 bg-zinc-50 border border-zinc-200 focus:border-zinc-950 rounded-xl font-mono uppercase focus:ring-1 focus:ring-zinc-950 outline-none transition-all"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-zinc-700 uppercase tracking-wider mb-2">
                  {t("Limite d'utilisation")}
                </label>
                <input
                  type="number"
                  min={1}
                  value={usageLimit}
                  onChange={(e) => setUsageLimit(e.target.value)}
                  placeholder={t("Optionnel (Ex: 100)")}
                  className="w-full px-4 py-3 bg-zinc-50 border border-zinc-200 focus:border-zinc-950 rounded-xl focus:ring-1 focus:ring-zinc-950 outline-none transition-all"
                />
              </div>
            </div>

            {/* Discount Type & Value */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-bold text-zinc-700 uppercase tracking-wider mb-2">
                  {t("Type de remise")} <span className="text-red-500">*</span>
                </label>
                <select
                  value={discountType}
                  onChange={(e) => {
                    setDiscountType(e.target.value as any);
                    setDiscountValue("");
                  }}
                  className="w-full px-4 py-3 bg-zinc-50 border border-zinc-200 focus:border-zinc-950 rounded-xl focus:ring-1 focus:ring-zinc-950 outline-none transition-all font-semibold"
                >
                  <option value="percentage">{t("Pourcentage (%)")}</option>
                  <option value="fixed">{t("Montant Fixe (DA)")}</option>
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold text-zinc-700 uppercase tracking-wider mb-2">
                  {t("Valeur")} <span className="text-red-500">*</span>
                </label>
                <input
                  type="number"
                  required
                  min={1}
                  max={discountType === "percentage" ? 100 : undefined}
                  value={discountValue}
                  onChange={(e) => setDiscountValue(e.target.value)}
                  placeholder={discountType === "percentage" ? t("Ex: 15") : t("Ex: 1000")}
                  className="w-full px-4 py-3 bg-zinc-50 border border-zinc-200 focus:border-zinc-950 rounded-xl focus:ring-1 focus:ring-zinc-950 outline-none transition-all"
                />
              </div>
            </div>

            {/* Min Purchase & Expiration */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-bold text-zinc-700 uppercase tracking-wider mb-2">
                  {t("Min. d'achat")} ({t("DA")}) <span className="text-red-500">*</span>
                </label>
                <input
                  type="number"
                  required
                  min={0}
                  value={minOrderValue}
                  onChange={(e) => setMinOrderValue(e.target.value)}
                  placeholder={t("Ex: 5000")}
                  className="w-full px-4 py-3 bg-zinc-50 border border-zinc-200 focus:border-zinc-950 rounded-xl focus:ring-1 focus:ring-zinc-950 outline-none transition-all"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-zinc-700 uppercase tracking-wider mb-2">
                  {t("Date d'expiration")} <span className="text-red-500">*</span>
                </label>
                <input
                  type="datetime-local"
                  required
                  value={expiresAt}
                  onChange={(e) => setExpiresAt(e.target.value)}
                  min={new Date().toISOString().slice(0, 16)}
                  className="w-full px-4 py-3 bg-zinc-50 border border-zinc-200 focus:border-zinc-950 rounded-xl focus:ring-1 focus:ring-zinc-950 outline-none transition-all"
                />
              </div>
            </div>

            {/* Single Use Switch */}
            <div className="flex items-center gap-3 p-4 bg-amber-50/40 border border-amber-100/60 rounded-2xl">
              <button
                type="button"
                onClick={() => setSingleUsePerClient(!singleUsePerClient)}
                className="text-amber-700 transition-colors"
              >
                {singleUsePerClient ? (
                  <CheckSquare className="w-5 h-5" />
                ) : (
                  <Square className="w-5 h-5 text-zinc-400" />
                )}
              </button>
              <div className="space-y-0.5">
                <p className="text-xs font-bold text-zinc-800 uppercase tracking-wide">
                  {t("Limiter à un usage unique par client")}
                </p>
                <p className="text-[10px] text-zinc-500">
                  {t("Si activé, chaque client d'OLMART ne pourra utiliser ce code qu'une seule fois.")}
                </p>
              </div>
            </div>

            {/* Limitation Category Scrollbox */}
            <div className="space-y-2 border-t border-zinc-100 pt-4">
              <div className="flex items-center justify-between">
                <label className="block text-xs font-bold text-zinc-700 uppercase tracking-wider flex items-center gap-1.5">
                  <Layers className="w-4 h-4 text-zinc-500" />
                  {t("Limitation par Catégorie")}
                </label>
                <span className="text-[10px] bg-zinc-100 text-zinc-600 px-2 py-0.5 rounded-md font-mono font-bold">
                  {selectedCategories.length} {t("Sélectionnées")}
                </span>
              </div>
              <p className="text-[10px] text-zinc-500 mb-2">
                {t("Laissez vide pour autoriser toutes les catégories d'OLMART.")}
              </p>

              <div className="relative mb-2">
                <Search className="w-4 h-4 text-zinc-400 absolute left-3 top-3" />
                <input
                  type="text"
                  placeholder={t("Filtrer les catégories...")}
                  value={categorySearch}
                  onChange={(e) => setCategorySearch(e.target.value)}
                  className="w-full ps-9 pe-4 py-2 bg-zinc-50 border border-zinc-200 focus:border-zinc-950 rounded-xl text-xs outline-none transition-all"
                />
              </div>

              <div className="border border-zinc-100 rounded-2xl max-h-[140px] overflow-y-auto p-3 space-y-2.5 bg-zinc-50/30">
                {filteredCategories.length === 0 ? (
                  <p className="text-[11px] text-zinc-400 text-center py-4">{t("Aucune catégorie trouvée")}</p>
                ) : (
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                    {filteredCategories.map((cat) => {
                      const isSelected = selectedCategories.includes(cat);
                      return (
                        <button
                          key={cat}
                          type="button"
                          onClick={() => handleToggleCategory(cat)}
                          className={`flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-bold transition-all text-left ${
                            isSelected
                              ? "bg-zinc-950 text-white shadow-sm"
                              : "bg-white text-zinc-700 border border-zinc-200 hover:border-zinc-300"
                          }`}
                        >
                          <span className="truncate">{t(cat)}</span>
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>
            </div>

            {/* Limitation Seller Scrollbox */}
            <div className="space-y-2 border-t border-zinc-100 pt-4">
              <div className="flex items-center justify-between">
                <label className="block text-xs font-bold text-zinc-700 uppercase tracking-wider flex items-center gap-1.5">
                  <User className="w-4 h-4 text-zinc-500" />
                  {t("Limitation par Vendeur")}
                </label>
                <span className="text-[10px] bg-zinc-100 text-zinc-600 px-2 py-0.5 rounded-md font-mono font-bold">
                  {selectedSellers.length} {t("Sélectionnés")}
                </span>
              </div>
              <p className="text-[10px] text-zinc-500 mb-2">
                {t("Laissez vide pour autoriser tous les vendeurs d'OLMART.")}
              </p>

              <div className="relative mb-2">
                <Search className="w-4 h-4 text-zinc-400 absolute left-3 top-3" />
                <input
                  type="text"
                  placeholder={t("Filtrer les vendeurs par boutique ou email...")}
                  value={sellerSearch}
                  onChange={(e) => setSellerSearch(e.target.value)}
                  className="w-full ps-9 pe-4 py-2 bg-zinc-50 border border-zinc-200 focus:border-zinc-950 rounded-xl text-xs outline-none transition-all"
                />
              </div>

              <div className="border border-zinc-100 rounded-2xl max-h-[140px] overflow-y-auto p-3 space-y-2.5 bg-zinc-50/30">
                {filteredSellers.length === 0 ? (
                  <p className="text-[11px] text-zinc-400 text-center py-4">{t("Aucun vendeur trouvé")}</p>
                ) : (
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                    {filteredSellers.map((seller) => {
                      const isSelected = selectedSellers.includes(seller.id);
                      return (
                        <button
                          key={seller.id}
                          type="button"
                          onClick={() => handleToggleSeller(seller.id)}
                          className={`flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-bold transition-all text-left ${
                            isSelected
                              ? "bg-zinc-950 text-white shadow-sm"
                              : "bg-white text-zinc-700 border border-zinc-200 hover:border-zinc-300"
                          }`}
                        >
                          <span className="truncate">{seller.name}</span>
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>
            </div>
          </div>
        </form>

        <div className="p-6 border-t border-zinc-100 bg-zinc-50/50 flex justify-end gap-3">
          <button
            type="button"
            disabled={submitting}
            onClick={() => {
              onClose();
              resetForm();
            }}
            className="px-6 py-3 font-sans font-bold text-zinc-600 hover:bg-zinc-100 rounded-xl transition-colors text-xs uppercase tracking-wider"
          >
            {t("Annuler")}
          </button>
          <button
            type="button"
            onClick={handleSubmit}
            disabled={submitting}
            className="px-8 py-3 bg-zinc-950 text-white font-sans font-bold text-xs uppercase tracking-widest rounded-xl hover:bg-zinc-800 transition-colors shadow-lg flex items-center gap-2 disabled:opacity-50"
          >
            {submitting ? (
              <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
            ) : (
              <>
                <Check className="w-4 h-4" /> {t("Créer le Coupon")}
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { X, Send, Paperclip, Loader2, FileText, User, Store } from 'lucide-react';
import { db, storage } from '../../lib/firebase';
import { collection, query, where, getDocs, addDoc, orderBy, onSnapshot, serverTimestamp } from 'firebase/firestore';
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';
import { useAuth } from '../../context/AuthContext';
import { useTranslation } from 'react-i18next';
import toast from 'react-hot-toast';

interface DisputeChatModalProps {
  dispute: any;
  onClose: () => void;
}

export const DisputeChatModal: React.FC<DisputeChatModalProps> = ({ dispute, onClose }) => {
  const { t } = useTranslation();
  const { currentUser } = useAuth();
  const [messages, setMessages] = useState<any[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [uploading, setUploading] = useState(false);
  const [loading, setLoading] = useState(true);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!dispute?.id) return;

    const q = query(
      collection(db, "disputeMessages"), 
      where("disputeId", "==", dispute.id),
      orderBy("createdAt", "asc")
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
       const msgs = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
       setMessages(msgs);
       setLoading(false);
       setTimeout(() => {
          scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
       }, 100);
    }, (err) => {
       console.error("Error fetching dispute messages:", err);
       setLoading(false);
    });

    return () => unsubscribe();
  }, [dispute?.id]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim() || !currentUser) return;

    try {
      await addDoc(collection(db, "disputeMessages"), {
         disputeId: dispute.id,
         text: newMessage.trim(),
         senderId: currentUser.uid,
         senderRole: 'admin',
         senderName: 'Support OLMART',
         createdAt: serverTimestamp()
      });
      setNewMessage('');
    } catch (err) {
       toast.error("Erreur d'envoi");
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !currentUser) return;

    setUploading(true);
    try {
      const storageRef = ref(storage, `disputes/${dispute.id}/${Date.now()}_${file.name}`);
      await uploadBytes(storageRef, file);
      const url = await getDownloadURL(storageRef);

      await addDoc(collection(db, "disputeMessages"), {
         disputeId: dispute.id,
         text: `Preuve documentaire : ${file.name}`,
         fileUrl: url,
         fileName: file.name,
         fileType: file.type,
         senderId: currentUser.uid,
         senderRole: 'admin',
         senderName: 'Support OLMART',
         createdAt: serverTimestamp()
      });
    } catch (err) {
       toast.error("Erreur lors de l'upload");
    } finally {
       setUploading(false);
       if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-zinc-950/40 backdrop-blur-sm">
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.95 }}
        className="w-full max-w-2xl bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[85vh]"
      >
        <div className="p-6 border-b border-zinc-100 flex items-center justify-between">
          <div>
            <h3 className="font-sans font-bold text-lg text-zinc-900">{t("Chat du litige")}</h3>
            <p className="text-xs font-bold text-zinc-500 uppercase tracking-widest">{t("Commande #")}{dispute.id.substring(0,8)}</p>
          </div>
          <button onClick={onClose} className="p-2 bg-zinc-50 hover:bg-zinc-100 text-zinc-500 rounded-xl transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-zinc-50/50" ref={scrollRef}>
          {loading ? (
             <div className="flex justify-center py-8"><Loader2 className="w-6 h-6 animate-spin text-zinc-400" /></div>
          ) : messages.length === 0 ? (
             <div className="text-center text-zinc-400 font-medium py-8">{t("Aucun message.")}</div>
          ) : (
             messages.map((m) => {
               const isAdmin = m.senderRole === 'admin';
               const isSeller = m.senderRole === 'seller';

               return (
                 <div key={m.id} className={`flex ${isAdmin ? 'justify-end' : 'justify-start'}`}>
                   <div className={`max-w-[80%] rounded-2xl p-4 ${isAdmin ? 'bg-zinc-900 text-white rounded-tr-sm' : isSeller ? 'bg-blue-50 text-blue-900 border border-blue-100 rounded-tl-sm' : 'bg-white border border-zinc-200 text-zinc-800 rounded-tl-sm shadow-sm'}`}>
                     <div className="flex items-center gap-2 mb-2">
                        {isAdmin ? <User className="w-3 h-3 text-zinc-400" /> : isSeller ? <Store className="w-3 h-3 text-blue-500" /> : <User className="w-3 h-3 text-zinc-400" />}
                        <span className={`text-[10px] font-bold uppercase tracking-widest ${isAdmin ? 'text-zinc-400' : isSeller ? 'text-blue-600' : 'text-zinc-500'}`}>
                           {m.senderName || (isAdmin ? "Admin" : isSeller ? "Vendeur" : "Client")}
                        </span>
                     </div>

                     {m.fileUrl && (
                        m.fileType?.startsWith('image/') ? (
                           <a href={m.fileUrl} target="_blank" rel="noopener noreferrer" className="block mb-2 rounded-xl overflow-hidden border border-zinc-200/20">
                             <img src={m.fileUrl} alt="attachment" className="max-w-full max-h-48 object-cover hover:opacity-90 transition-opacity" />
                           </a>
                        ) : (
                           <a href={m.fileUrl} target="_blank" rel="noopener noreferrer" className="flex items-center gap-2 p-3 bg-white/10 rounded-xl mb-2 hover:bg-white/20 transition-colors">
                              <FileText className="w-5 h-5" />
                              <span className="text-xs font-medium truncate max-w-[200px]">{m.fileName}</span>
                           </a>
                        )
                     )}

                     <p className="text-sm font-medium whitespace-pre-wrap">{m.text}</p>

                     {m.createdAt && (
                        <div className={`mt-2 text-[9px] font-bold text-end ${isAdmin ? 'text-zinc-500' : 'text-zinc-400'}`}>
                           {m.createdAt?.toDate?.()?.toLocaleTimeString()}
                        </div>
                     )}
                   </div>
                 </div>
               )
             })
          )}
        </div>

        <div className="p-4 bg-white border-t border-zinc-100">
           <form onSubmit={handleSend} className="flex gap-3 items-end">
              <div className="flex-1 bg-zinc-50 border border-zinc-200 rounded-2xl flex items-end overflow-hidden focus-within:ring-2 ring-indigo-500/20 transition-all">
                 <textarea
                   value={newMessage}
                   onChange={(e) => setNewMessage(e.target.value)}
                   placeholder={t("Envoyer un message...")}
                   className="flex-1 max-h-32 min-h-[56px] bg-transparent p-4 outline-none text-sm font-medium resize-none"
                   rows={1}
                   onKeyDown={(e) => {
                      if (e.key === 'Enter' && !e.shiftKey) {
                         e.preventDefault();
                         handleSend(e);
                      }
                   }}
                 />
                 <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileUpload} />
                 <button 
                   type="button" 
                   onClick={() => fileInputRef.current?.click()}
                   disabled={uploading}
                   className="p-4 text-zinc-400 hover:text-zinc-600 transition-colors disabled:opacity-50"
                 >
                    {uploading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Paperclip className="w-5 h-5" />}
                 </button>
              </div>
              <button
                type="submit"
                disabled={!newMessage.trim() && !uploading}
                className="w-14 h-14 bg-zinc-950 text-white rounded-2xl flex items-center justify-center hover:bg-zinc-800 disabled:opacity-50 transition-colors shadow-lg shadow-zinc-950/20 shrink-0"
              >
                <Send className="w-5 h-5" />
              </button>
           </form>
        </div>
      </motion.div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { X, MapPin, Monitor, Clock, Loader2 } from 'lucide-react';
import { db } from '../../lib/firebase';
import { collection, query, where, getDocs, orderBy, limit } from 'firebase/firestore';
import { useTranslation } from 'react-i18next';

interface IpLogsModalProps {
  user: any;
  onClose: () => void;
}

export const IpLogsModal: React.FC<IpLogsModalProps> = ({ user, onClose }) => {
  const { t } = useTranslation();
  const [logs, setLogs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!user?.id) return;
    const fetchLogs = async () => {
       try {
          const q = query(collection(db, "login_history"), where("userId", "==", user.id), orderBy("timestamp", "desc"), limit(50));
          const snap = await getDocs(q);
          setLogs(snap.docs.map(doc => ({ id: doc.id, ...doc.data() })));
       } catch (err) {
          console.error("Error fetching IP logs", err);
       } finally {
          setLoading(false);
       }
    };
    fetchLogs();
  }, [user?.id]);

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-zinc-950/40 backdrop-blur-sm">
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.95 }}
        className="w-full max-w-2xl bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[85vh]"
      >
        <div className="p-6 border-b border-zinc-100 flex items-center justify-between">
          <div>
            <h3 className="font-sans font-bold text-lg text-zinc-900">{t("Historique de connexions")}</h3>
            <p className="text-xs font-bold text-zinc-500 uppercase tracking-widest">{user.email}</p>
          </div>
          <button onClick={onClose} className="p-2 bg-zinc-50 hover:bg-zinc-100 text-zinc-500 rounded-xl transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-zinc-50/50">
          {loading ? (
             <div className="flex justify-center py-8"><Loader2 className="w-6 h-6 animate-spin text-zinc-400" /></div>
          ) : logs.length === 0 ? (
             <div className="text-center text-zinc-400 font-medium py-8">{t("Aucun log de connexion trouvé pour cet utilisateur.")}</div>
          ) : (
             <div className="space-y-3">
               {logs.map(log => (
                 <div key={log.id} className="bg-white p-4 rounded-2xl border border-zinc-100 shadow-sm flex items-center justify-between">
                    <div className="flex items-center gap-4">
                       <div className="w-10 h-10 bg-indigo-50 rounded-full flex items-center justify-center text-indigo-500">
                          <Monitor className="w-5 h-5" />
                       </div>
                       <div>
                          <p className="font-bold text-sm text-zinc-900">{log.ipAddress || "IP Inconnue"}</p>
                          <div className="flex items-center gap-2 mt-1">
                             <MapPin className="w-3 h-3 text-zinc-400" />
                             <span className="text-[10px] uppercase font-bold text-zinc-500 tracking-widest">{log.location || log.userAgent || "Appareil Inconnu"}</span>
                          </div>
                       </div>
                    </div>
                    <div className="text-right">
                       <div className="flex items-center gap-1.5 justify-end mb-1">
                          <Clock className="w-3 h-3 text-zinc-400" />
                          <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest">
                             {log.timestamp?.toDate?.()?.toLocaleString('fr-FR') || "Date Inconnue"}
                          </span>
                       </div>
                       {log.success === false && (
                          <span className="text-[9px] bg-red-100 text-red-600 px-2 py-0.5 rounded-full font-bold uppercase tracking-widest">
                            Échec ({log.reason || "Mot de passe incorrect"})
                          </span>
                       )}
                    </div>
                 </div>
               ))}
             </div>
          )}
        </div>
      </motion.div>
    </div>
  );
};

