export const CustomerPreferences: React.FC<CustomerPreferencesProps> = ({ currentUser, userProfile }) => {
  const { t, i18n } = useTranslation();
  const isArabic = i18n.language === "ar" || i18n.language?.startsWith("ar");

  // Load existing preferences safely
  const [selectedInterests, setSelectedInterests] = useState<string[]>(() => {
    return userProfile?.preferences?.interests || [];
  });

  // Track which parent category has its accordion tray expanded
  const [expandedCategories, setExpandedCategories] = useState<Record<string, boolean>>({});
  const [saving, setSaving] = useState(false);

  // Local Arabic/French translator
  const translateKey = (key: string) => {
    const translation = TRANS_DICT[key];
    if (translation) {
      return isArabic ? translation.ar : translation.fr;
    }
    return t(key);
  };

  // Compile map of parent categories and their direct subcategories (no sub-sub-categories!)
  const categoryStructure = useMemo<Record<string, string[]>>(() => {
    const data: Record<string, string[]> = {};
    Object.entries(PRODUCT_HIERARCHY).forEach(([parentCat, subObj]) => {
      data[parentCat] = Object.keys(subObj);
    });
    return data;
  }, []);

  const handleToggleSubcategory = (subName: string) => {
    setSelectedInterests((prev) =>
      prev.includes(subName) ? prev.filter((item) => item !== subName) : [...prev, subName]
    );
  };

  // Click on parent category card:
  // 1. Toggles expansion of its child subcategories tray list
  // 2. Selects / Deselects all subcategories of this parent simultaneously!
  const handleToggleParentBlock = (parentCat: string) => {
    const childrenList = categoryStructure[parentCat] || [];
    const allChildrenSelected = childrenList.every((sub) => selectedInterests.includes(sub));

    if (allChildrenSelected) {
      // De-select all subcategories under this parent
      setSelectedInterests((prev) => prev.filter((sub) => !childrenList.includes(sub)));
      toast.success(
        isArabic
          ? `تم إلغاء اختيار جميع الفئات الفرعية لـ ${translateKey(parentCat)}`
          : `Toutes les sous-catégories de ${translateKey(parentCat)} ont été retirées`
      );
    } else {
      // Select all subcategories under this parent
      setSelectedInterests((prev) => {
        const updated = new Set([...prev, ...childrenList]);
        return Array.from(updated);
      });
      toast.success(
        isArabic
          ? `تم اختيار كل الفئات الفرعية لـ ${translateKey(parentCat)}`
          : `Sélection complète activée pour ${translateKey(parentCat)}`
      );
    }

    // Always automatically open the tray to show details cleanly!
    setExpandedCategories((prev) => ({
      ...prev,
      [parentCat]: true, // Keep open so they see the subcategories immediately
    }));
  };

  // Simple expand/collapse toggle without touching selection
  const handleToggleAccordion = (parentCat: string, e: React.MouseEvent) => {
    e.stopPropagation(); // prevent triggering parent block toggle selection
    setExpandedCategories((prev) => ({
      ...prev,
      [parentCat]: !prev[parentCat],
    }));
  };

  const clearAllSelected = () => {
    setSelectedInterests([]);
    toast.success(isArabic ? "تم تفريغ قائمة الاهتمامات !" : "Toutes les préférences ont été réinitialisées.");
  };

  const handleSavePreferences = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser?.uid) {
      toast.error(isArabic ? "يرجى تسجيل الدخول أولاً." : "Veuillez vous authentifier.");
      return;
    }

    setSaving(true);
    try {
      await apiPost("/api/v1/auth/profile", {
        preferences: {
          interests: selectedInterests,
          updatedAt: new Date().toISOString(),
        },
      });
      toast.success(
        isArabic
          ? "🎯 تم تحديث تفضيلاتك الذكية على أولمارت بنجاح !"
          : "🎯 Vos préférences d'intérêts intuitives ont été synchronisées avec succès !"
      );
    } catch (err: any) {
      console.error(err);
      toast.error(isArabic ? "حدث خطأ أثناء الحفظ." : "Erreur d'enregistrement.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="space-y-8" id="progressive-disclosure-preferences">
      {/* Immersive Dark Spotify Premium Banner */}
      <div className="relative overflow-hidden bg-slate-950 text-white rounded-[2rem] p-8 md:p-10 shadow-2xl">
        <div className="absolute top-0 right-0 w-80 h-80 bg-gradient-to-br from-amber-500/20 to-orange-600/10 rounded-full blur-[80px] pointer-events-none" />
        <div className="absolute bottom-0 left-12 w-60 h-60 bg-gradient-to-tr from-rose-500/15 to-purple-600/10 rounded-full blur-[60px] pointer-events-none" />

        <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div className="max-w-xl space-y-2">
            <div className="inline-flex items-center gap-1.5 px-3 py-1 bg-amber-500/15 border border-amber-500/35 rounded-full text-amber-400 text-[10px] font-sans font-bold tracking-widest uppercase mb-1">
              <Sparkles className="w-3 h-3 animate-pulse" />
              <span>{isArabic ? "إعدادات الأسلوب المخصص" : "ENGAGEMENT PERSONNALISÉ"}</span>
            </div>

            <h3 className="font-extrabold text-3xl sm:text-4.5xl tracking-tight text-white leading-tight">
              {isArabic ? "اختر اهتماماتك المفضلة" : "Mes Thèmes & Préférences"}
            </h3>
            <p className="text-slate-350 text-xs sm:text-sm font-medium leading-relaxed">
              {isArabic
                ? "انقر على الفئة الكبرى لاختيارها كلها، ستفتح لك قائمة فريدة لتعديل واختيار عناصر فرعية معينة بكل مرونة وبطريقة مسلية !"
                : "Sélectionnez directement une thématique majeure pour l'activer, puis affinez vos réglages en cochant les sous-catégories de votre choix."}
            </p>
          </div>

          {/* Real-time stats pill */}
          <div className="flex items-center md:flex-col gap-3 justify-end flex-shrink-0 bg-slate-900/70 backdrop-blur border border-slate-850 px-5 py-4 rounded-2xl">
            <div className="text-start md:text-center">
              <span className="block text-[10px] font-sans font-bold text-slate-400 tracking-wider">
                {isArabic ? "الفئات الفرعية النشطة" : "SÉLECTIONNÉES"}
              </span>
              <span className="block text-2xl font-sans font-bold text-amber-400 mt-0.5">{selectedInterests.length}</span>
            </div>
            {selectedInterests.length > 0 && (
              <button
                type="button"
                onClick={clearAllSelected}
                className="text-xs font-bold text-red-400 hover:text-red-500 hover:bg-red-500/10 px-3 py-1.5 rounded-xl transition-all"
              >
                {isArabic ? "مسح الكل" : "Tout effacer"}
              </button>
            )}
          </div>
        </div>
      </div>

      <form onSubmit={handleSavePreferences} className="space-y-6">
        {/* Accordions Matrix Container */}
        <div className="space-y-4" id="spotify-accordion-parent-grid">
          {Object.keys(categoryStructure).map((parentCat) => {
            const subcategories = categoryStructure[parentCat] || [];
            const style = THEME_COORDS[parentCat] || {
              icon: "📦",
              from: "from-slate-400",
              to: "to-slate-500",
              text: "text-slate-600",
              glow: "rgba(0,0,0,0.02)",
              badge: "bg-transparent border-slate-100",
            };
            const isExpanded = !!expandedCategories[parentCat];

            // Count active subcategories in this parent block
            const selectedChildrenCount = subcategories.filter((sub) => selectedInterests.includes(sub)).length;
            const allChildrenSelected = selectedChildrenCount === subcategories.length && subcategories.length > 0;
            const hasDraftSelections = selectedChildrenCount > 0;

            return (
              <div
                key={parentCat}
                className={`bg-white border rounded-3xl overflow-hidden shadow-sm hover:shadow-md transition-all duration-350 ${
                  hasDraftSelections ? "border-slate-900 ring-1 ring-slate-900/5" : "border-slate-100"
                }`}
                id={`pref-accordion-[${parentCat}]`}
              >
                {/* Accordion Trigger Hero Card Bar */}
                <div
                  onClick={() => handleToggleParentBlock(parentCat)}
                  className="flex items-center justify-between p-5 md:p-6 cursor-pointer select-none relative"
                >
                  {/* Dynamic subtle accent background if elements inside are selected */}
                  {hasDraftSelections && <div className="absolute inset-0 bg-transparent/40 pointer-events-none" />}

                  <div className="relative z-10 flex items-center gap-4 flex-1 min-w-0">
                    {/* Multi-layered custom visual badge */}
                    <div
                      className={`w-14 h-14 rounded-2xl flex items-center justify-center text-2xl flex-shrink-0 shadow-sm bg-gradient-to-tr ${
                        allChildrenSelected
                          ? `${style.from} ${style.to} text-white`
                          : "bg-transparent border border-slate-150/60"
                      }`}
                    >
                      {style.icon}
                    </div>

                    <div className="min-w-0 pr-2 rtl:pr-0 rtl:pl-2 space-y-0.5">
                      <div className="flex items-center gap-2 flex-wrap">
                        <span className="font-extrabold text-base md:text-lg text-slate-950 tracking-tight">
                          {translateKey(parentCat)}
                        </span>

                        {/* Selections indicators badge */}
                        {hasDraftSelections && (
                          <span
                            className={`text-[10px] sm:text-xs font-black px-2.5 py-0.5 rounded-full border ${
                              allChildrenSelected
                                ? "bg-amber-100/70 text-amber-900 border-amber-200"
                                : "bg-slate-100 text-slate-700 border-slate-200/50"
                            }`}
                          >
                            {allChildrenSelected
                              ? isArabic
                                ? "الكل مفعّل"
                                : "Tous activés"
                              : isArabic
                                ? `${selectedChildrenCount} من ${subcategories.length}`
                                : `${selectedChildrenCount} sélectionnés`}
                          </span>
                        )}
                      </div>

                      <span className="block text-xs font-bold text-slate-400">
                        {subcategories.length} {isArabic ? "خيارات فرعية مدرجة" : "choix de thématiques disponibles"}
                      </span>
                    </div>
                  </div>

                  {/* Right Tools Controls Panel */}
                  <div className="relative z-10 flex items-center gap-3">
                    {/* Instant Choice status check box */}
                    <div
                      className={`w-6 h-6 rounded-lg flex items-center justify-center transition-all ${
                        hasDraftSelections
                          ? allChildrenSelected
                            ? "bg-slate-950 text-white"
                            : "bg-slate-200 text-slate-800"
                          : "border-2 border-slate-200 text-transparent hover:border-slate-400"
                      }`}
                    >
                      <Check className="w-4 h-4 stroke-[3px]" />
                    </div>

                    <div className="w-px h-6 bg-slate-150" />

                    {/* Expand accordion toggler */}
                    <button
                      type="button"
                      onClick={(e) => handleToggleAccordion(parentCat, e)}
                      className="p-2 bg-transparent hover:bg-slate-100 text-slate-500 hover:text-slate-800 rounded-xl transition-colors"
                      title={isArabic ? "توسيع / إغلاق" : "Voir les détails"}
                    >
                      {isExpanded ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
                    </button>
                  </div>
                </div>

                {/* Smooth Animated Tray for Subcategory Pills Grid (Spotify selector!) */}
                <AnimatePresence initial={false}>
                  {isExpanded && (
                    <motion.div
                      initial={{ height: 0, opacity: 0 }}
                      animate={{ height: "auto", opacity: 1 }}
                      exit={{ height: 0, opacity: 0 }}
                      transition={{ duration: 0.3, ease: "easeInOut" }}
                      className="border-t border-slate-100"
                    >
                      <div className="bg-transparent/70 p-5 md:p-6 space-y-4">
                        <div className="flex items-center justify-between">
                          <p className="text-[10px] font-sans font-bold uppercase text-slate-400 tracking-wider">
                            {isArabic
                              ? `تخصيص الفئات الفرعية لـ ${translateKey(parentCat)} :`
                              : `Affiner les rubriques de ${translateKey(parentCat)} :`}
                          </p>

                          {/* Inner switch buttons */}
                          <div className="flex items-center gap-2">
                            <button
                              type="button"
                              onClick={(e) => {
                                e.stopPropagation();
                                const updated = new Set([...selectedInterests, ...subcategories]);
                                setSelectedInterests(Array.from(updated));
                              }}
                              className="text-[10px] font-bold text-slate-600 hover:text-slate-950 flex items-center gap-1"
                            >
                              <CheckSquare className="w-3 h-3 text-emerald-600" />
                              {isArabic ? "تفعيل الكل" : "Activer tout"}
                            </button>
                            <span className="text-slate-300 text-xs">|</span>
                            <button
                              type="button"
                              onClick={(e) => {
                                e.stopPropagation();
                                setSelectedInterests((prev) => prev.filter((sub) => !subcategories.includes(sub)));
                              }}
                              className="text-[10px] font-bold text-slate-600 hover:text-red-600 flex items-center gap-1"
                            >
                              <Square className="w-3 h-3 text-red-500" />
                              {isArabic ? "تعطيل الكل" : "Désactiver tout"}
                            </button>
                          </div>
                        </div>

                        {/* Staggered Spotify Round Circular Pills Grid */}
                        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3">
                          {subcategories.map((subName) => {
                            const isSubSelected = selectedInterests.includes(subName);
                            return (
                              <motion.button
                                key={subName}
                                type="button"
                                whileHover={{ scale: 1.025 }}
                                whileTap={{ scale: 0.975 }}
                                onClick={(e) => {
                                  e.stopPropagation(); // prevent collapsing or parent trigger
                                  handleToggleSubcategory(subName);
                                }}
                                className={`flex items-center justify-between px-4 py-3 rounded-2xl border text-start transition-all duration-200 ${
                                  isSubSelected
                                    ? `bg-gradient-to-br ${style.from} ${style.to} border-transparent text-white shadow-sm shadow-orange-100`
                                    : "bg-white border-slate-150 text-slate-700 hover:border-slate-300 hover:bg-transparent"
                                }`}
                                id={`pref-pill-[${subName}]`}
                              >
                                <span className="font-extrabold text-xs sm:text-sm truncate mr-2 rtl:mr-0 rtl:ml-2">
                                  {translateKey(subName)}
                                </span>

                                <div
                                  className={`w-4 h-4 rounded-full flex items-center justify-center flex-shrink-0 ${
                                    isSubSelected ? "bg-white text-slate-950" : "border border-slate-300 bg-transparent"
                                  }`}
                                >
                                  {isSubSelected && <Check className="w-3 h-3 stroke-[3px]" />}
                                </div>
                              </motion.button>
                            );
                          })}
                        </div>
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            );
          })}
        </div>

        {/* Dynamic Sticky Bottom Options Board */}
        <div className="bg-white border border-slate-150 shadow-xl rounded-2xl p-5 flex flex-col sm:flex-row items-center justify-between gap-4 sticky bottom-4 z-40">
          <div className="text-start">
            <span className="block text-[10px] font-sans font-bold text-slate-400 tracking-wider">
              {isArabic ? "تقييم التخصيص التلقائي :" : "MOTEUR D'AFFINITÉ"}
            </span>
            <span className="text-xs font-extrabold text-slate-700">
              {selectedInterests.length > 0
                ? isArabic
                  ? `لقد قمت بتخصيص ${selectedInterests.length} فئة فرعية مفضلة.`
                  : `Personnalisation ajustée avec ${selectedInterests.length} préférences.`
                : isArabic
                  ? "لم تقم بتحديد أي فئات بعد، سيتم عرض المحتوى العام."
                  : "Sélectionnez au moins une rubrique pour booster l'algorithme."}
            </span>
          </div>

          <div className="flex items-center gap-3 w-full sm:w-auto">
            <button
              type="submit"
              disabled={saving}
              className="flex-1 sm:flex-initial flex items-center justify-center gap-2.5 px-8 py-3.5 bg-slate-950 hover:bg-slate-900 text-white font-extrabold text-xs tracking-widest uppercase rounded-full transition-all disabled:opacity-50 min-h-[48px]"
            >
              {saving ? (
                <RefreshCw className="w-4 h-4 animate-spin text-white" />
              ) : (
                <Check className="w-4 h-4 text-amber-400 stroke-[3px]" />
              )}
              <span>
                {saving
                  ? isArabic
                    ? "جاري التحديث..."
                    : "Mise à jour..."
                  : isArabic
                    ? "حفظ التفضيلات"
                    : "Enregistrer"}
              </span>
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

import React, { useState, useEffect } from "react";
import {
  Store,
  UserCheck,
  Search,
  ArrowRight,
  UserMinus,
  Sparkles,
  MapPin,
  Package,
  Heart,
  RefreshCw,
  Star,
  ArrowUpRight,
} from "lucide-react";
import { useNavigate } from "react-router-dom";
import { apiGet, apiPost } from "../../lib/api";
import { toast } from "react-hot-toast";
import { ConfirmModal } from "../ui/ConfirmModal";
import { motion, AnimatePresence } from "motion/react";
import { ALGERIA_WILAYAS } from "../../constants";
import { useTranslation } from "react-i18next";
import { getOptimizedImageUrl } from "../../utils/imageUtils";

// Aesthetic pastel gradients for Gen-Z empty banners
const PRESET_GRADIENTS = [
  "from-amber-100 to-orange-50",
  "from-violet-100 to-indigo-50",
  "from-teal-100 to-emerald-50",
  "from-rose-100 to-pink-50",
  "from-sky-100 to-blue-50",
];

export const FollowedStores: React.FC<{ currentUser: any }> = ({ currentUser }) => {
  const { t } = useTranslation();
  const [stores, setStores] = useState<any[]>([]);
  const [allSellers, setAllSellers] = useState<any[]>([]);
  const [productsMap, setProductsMap] = useState<Record<string, any[]>>({});

  const [loading, setLoading] = useState(true);
  const [exploreLoading, setExploreLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<"followed" | "explore">("followed");

  // Search & Filter
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedWilaya, setSelectedWilaya] = useState("Tous");
  const [showAllWilayas, setShowAllWilayas] = useState(false);

  // Unfollow confirmation modal
  const [showConfirm, setShowConfirm] = useState(false);
  const [storeToUnfollow, setStoreToUnfollow] = useState<any | null>(null);

  // Follow/Unfollow request debounce per store
  const [actionLoadingId, setActionLoadingId] = useState<string | null>(null);

  const navigate = useNavigate();

  // Popular Wilayas for quick pill selection
  const HOT_WILAYAS = [
    "Tous",
    "16 Alger",
    "31 Oran",
    "25 Constantine",
    "09 Blida",
    "15 Tizi Ouzou",
    "35 Boumerdès",
    "19 Sétif",
  ];

  // 1. Fetch followed stores (subscriptions)
  useEffect(() => {
    const fetchStores = async () => {
      if (!currentUser) return;
      try {
        const data = await apiGet<{ stores: any[] }>("/api/v1/buyer/followed-stores");
        if (data && data.stores) {
          setStores(data.stores);

          // If user follows nothing, automatically open 'explore' tab to keep them engaged
          if (data.stores.length === 0) {
            setActiveTab("explore");
          }
        }
      } catch (err) {
        console.error("Error fetching followed stores", err);
      } finally {
        setLoading(false);
      }
    };
    fetchStores();
  }, [currentUser]);

  // 2. Fetch public sellers & recent active products concurrently for visual product previews
  useEffect(() => {
    const fetchExploreData = async () => {
      setExploreLoading(true);
      try {
        // Fetch top public profiles for explore feed
        const sellersData = await apiGet<{ sellers: any[] }>("/api/v1/explore/sellers");
        if (sellersData && sellersData.sellers) {
          setAllSellers(sellersData.sellers);
        }

        // Fetch active products to group under their respective seller's preview slider
        const productsData = await apiGet<{ products: any[] }>("/api/v1/explore/products");
        if (productsData && productsData.products) {
          const tempMap: Record<string, any[]> = {};
          productsData.products.forEach((data: any) => {
            if (data.sellerId) {
              if (!tempMap[data.sellerId]) {
                tempMap[data.sellerId] = [];
              }
              if (tempMap[data.sellerId].length < 3) {
                tempMap[data.sellerId].push(data);
              }
            }
          });
          setProductsMap(tempMap);
        }
      } catch (err) {
        console.error("Error fetching discovery profiles:", err);
      } finally {
        setExploreLoading(false);
      }
    };
    fetchExploreData();
  }, []);

  const triggerUnfollow = (store: any) => {
    setStoreToUnfollow(store);
    setShowConfirm(true);
  };

  const executeUnfollow = async () => {
    if (!currentUser || !storeToUnfollow) return;
    const sellerId = storeToUnfollow.sellerId || storeToUnfollow.id;

    setActionLoadingId(sellerId);
    try {
      await apiPost("/api/v1/buyer/unfollow", { sellerId });
      setStores((prev) => prev.filter((s) => s.sellerId !== sellerId));
      toast.success("Désabonnement réussi. 👋");
    } catch (err) {
      console.error("Error unfollowing store", err);
      toast.error("Échec lors de la désinscription.");
    } finally {
      setActionLoadingId(null);
      setShowConfirm(false);
      setStoreToUnfollow(null);
    }
  };

  const handleFollow = async (seller: any) => {
    if (!currentUser) {
      navigate("/login");
      return;
    }

    setActionLoadingId(seller.id);
    try {
      const followPayload = {
        sellerId: seller.id,
        name: seller.shopName || seller.displayName || "Boutique",
        logo: seller.logoUrl || null,
        location: seller.wilaya || "Algérie",
        followedAt: new Date().toISOString(),
      };

      await apiPost("/api/v1/buyer/follow", { sellerId: seller.id, followPayload });
      setStores((prev) => [...prev, { id: seller.id, ...followPayload }]);
      toast.success(`Abonné à ${seller.shopName || "la boutique"} ! ✨`);
    } catch (err) {
      console.error("Error following store", err);
      toast.error("Erreur d'abonnement.");
    } finally {
      setActionLoadingId(null);
    }
  };

  // Pre-calculate search filtered items
  const filteredSellers = allSellers.filter((seller) => {
    const sName = (seller.shopName || seller.displayName || "").toLowerCase();
    const sDesc = (seller.shopDescription || "").toLowerCase();
    const matchesSearch = sName.includes(searchQuery.toLowerCase()) || sDesc.includes(searchQuery.toLowerCase());
    const matchesWilaya = selectedWilaya === "Tous" || seller.wilaya === selectedWilaya;
    return matchesSearch && matchesWilaya;
  });

  return (
    <div className="space-y-8">
      <ConfirmModal
        isOpen={showConfirm}
        onClose={() => {
          setShowConfirm(false);
          setStoreToUnfollow(null);
        }}
        onConfirm={executeUnfollow}
        title={t("Se désabonner") || "Se désabonner"}
        message={`Voulez-vous vraiment vous désabonner de la boutique "${storeToUnfollow?.name || storeToUnfollow?.shopName || "Boutique"}" ?`}
      />

      {/* Dynamic Header & Gen-Z Tabs */}
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-sans font-bold text-slate-900 tracking-tighter rtl:tracking-normal uppercase">
            {t("Réseau Vendeurs")}
          </h2>
          <p className="text-slate-500 font-medium text-sm">
            {t("Suivez vos favoris et explorez les pépites des 58 Wilayas.")}
          </p>
        </div>

        {/* Gen Z Light Dual Tabs */}
        <div className="flex bg-slate-100 p-1 rounded-2xl border border-slate-200/40 w-fit shrink-0 self-start">
          <button
            onClick={() => setActiveTab("followed")}
            className={`flex items-center gap-2 px-5 py-2.5 rounded-xl font-bold text-xs rtl:text-sm tracking-wide uppercase transition-all duration-300 ${
              activeTab === "followed" ? "bg-white text-slate-900 shadow-sm" : "text-slate-500 hover:text-slate-900"
            }`}
          >
            <UserCheck className="w-4 h-4" />
            {t("Abonnements")}
            <span className="ms-1.5 px-2 py-0.5 text-[10px] rtl:text-[12px] bg-slate-900 text-white rounded-full font-sans font-bold">
              {stores.length}
            </span>
          </button>

          <button
            onClick={() => setActiveTab("explore")}
            className={`flex items-center gap-2 px-5 py-2.5 rounded-xl font-bold text-xs rtl:text-sm tracking-wide uppercase transition-all duration-300 relative ${
              activeTab === "explore" ? "bg-white text-slate-900 shadow-sm" : "text-slate-500 hover:text-slate-900"
            }`}
          >
            <Sparkles className="w-4 h-4 text-slate-500" />
            {t("Explorer")}
            <span className="absolute -top-1.5 -right-1 flex h-2.5 w-2.5">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-orange-400 opacity-75"></span>
              <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-transparent0"></span>
            </span>
          </button>
        </div>
      </header>

      {/* VIEWPORT CONTROLLER */}
      <div className="min-h-[400px]">
        {activeTab === "followed" ? (
          /* =======================================================
             SUBSCRIBED STORES TAB (Traditional UI, polished)
             ======================================================= */
          loading ? (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {[1, 2, 3, 4].map((i) => (
                <div key={i} className="h-28 bg-transparent rounded-2xl animate-pulse border border-slate-200/60" />
              ))}
            </div>
          ) : stores.length === 0 ? (
            <div className="p-10 md:p-16 flex flex-col items-center justify-center text-center bg-transparent border border-slate-200/50 rounded-3xl">
              <div className="w-20 h-20 bg-white border border-slate-200 rounded-full flex items-center justify-center mb-6 shadow-sm">
                <Store className="w-8 h-8 text-slate-300" />
              </div>
              <h3 className="text-xl font-sans font-bold text-slate-900 mb-2 tracking-tight rtl:tracking-normal">
                {t("Aucun abonnement existant")}
              </h3>
              <p className="text-slate-500 font-medium max-w-sm mb-8 leading-relaxed text-sm">
                {t(
                  "Abonnez-vous à nos créateurs locaux pour être notifié instantanément de leurs derniers produits & bons plans locaux."
                )}
              </p>
              <button
                onClick={() => setActiveTab("explore")}
                className="px-6 py-3.5 bg-slate-900 text-white hover:bg-slate-800 rounded-xl font-sans font-bold text-xs rtl:text-sm uppercase tracking-widest rtl:tracking-normal transition-all shadow-md shadow-slate-900/10 flex items-center gap-2 scale-100 hover:scale-[1.02] active:scale-95"
              >
                <Sparkles className="w-4 h-4 text-orange-300" />
                {t("Découvrir des pépites")}
              </button>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {stores.map((store) => {
                return (
                  <div
                    key={store.id}
                    className="border border-slate-200/60 rounded-2xl p-5 flex gap-4 hover:border-slate-400 hover:shadow-md transition-all bg-white relative group"
                  >
                    <div className="absolute top-4 right-4 text-[10px] rtl:text-[12px] font-bold text-slate-400 font-mono uppercase">
                      {t("VIP")}
                    </div>

                    {/* Shop Avatar */}
                    <div className="w-16 h-16 rounded-full bg-transparent border border-slate-200 overflow-hidden shrink-0 flex items-center justify-center relative">
                      {store.logo ? (
                        <img
                          loading="lazy"
                          src={getOptimizedImageUrl(store.logo, 200)}
                          alt={store.name}
                          className="w-full h-full object-cover"
                        />
                      ) : (
                        <Store className="w-6 h-6 text-slate-400" />
                      )}
                      <span
                        className="absolute bottom-0 right-0 w-3.5 h-3.5 bg-emerald-500 rounded-full border-2 border-white"
                        title={t("Vendeur actif") || "Vendeur actif"}
                      />
                    </div>

                    {/* Details */}
                    <div className="flex-1 min-w-0">
                      <h4 className="font-sans font-bold text-slate-900 truncate text-base leading-tight group-hover:text-slate-600 transition-colors">
                        {store.name}
                      </h4>
                      <p className="text-xs rtl:text-sm font-bold text-slate-400 uppercase tracking-wider rtl:tracking-normal flex items-center gap-1.5 mt-1 mb-3">
                        <MapPin className="w-3 h-3 text-slate-500" />
                        {store.location}
                      </p>

                      <div className="flex items-center gap-2">
                        <button
                          onClick={() => navigate(`/store/${store.sellerId}`)}
                          className="px-4 py-2 bg-slate-900 hover:bg-slate-800 text-white rounded-xl text-[10px] rtl:text-[12px] font-sans font-bold uppercase tracking-wider rtl:tracking-normal transition-all"
                        >
                          {t("Visiter la vitrine")}
                        </button>
                        <button
                          onClick={() => triggerUnfollow(store)}
                          disabled={actionLoadingId === store.sellerId}
                          className="p-2 text-slate-400 hover:text-red-500 bg-transparent hover:bg-red-50 border border-slate-100 rounded-xl transition-all"
                          title={t("Ne plus suivre") || "Ne plus suivre"}
                        >
                          <UserMinus className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )
        ) : (
          /* =======================================================
             MÉTIRE-ORIENTED GEN-Z DISCOVER VIBE BOARD
             ======================================================= */
          <div className="space-y-6">
            {/* Filters Bar Context (Premium Search & Horizon Wilaya slider) */}
            <div className="bg-white p-5 rounded-3xl border border-slate-200/60 shadow-sm space-y-4">
              <div className="flex flex-col md:flex-row gap-3">
                <div className="relative flex-1">
                  <Search className="w-4 h-4 text-slate-400 absolute left-4 top-3.5" />
                  <input
                    type="text"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder={
                      t("Rechercher une marque, une friperie ou un artisan...") ||
                      "Rechercher une marque, une friperie ou un artisan..."
                    }
                    className="w-full bg-transparent border border-slate-200/60 rounded-2xl py-3 ps-11 pe-4 text-sm font-medium focus:outline-none focus:border-slate-900 focus:ring-1 focus:ring-slate-900 transition-all"
                  />
                  {searchQuery && (
                    <button
                      onClick={() => setSearchQuery("")}
                      className="absolute right-4 top-3.5 text-slate-400 hover:text-slate-700 text-xs rtl:text-sm font-bold font-mono"
                    >
                      {t("Clear")}
                    </button>
                  )}
                </div>

                {/* Wilaya Filter Dropdown toggle helper */}
                <button
                  onClick={() => setShowAllWilayas(!showAllWilayas)}
                  className={`px-5 py-3 rounded-2xl text-xs rtl:text-sm font-bold border transition-colors flex items-center gap-2 ${
                    showAllWilayas || selectedWilaya !== "Tous"
                      ? "bg-transparent border-slate-200 text-slate-600"
                      : "bg-white border-slate-200 text-slate-700 hover:bg-transparent"
                  }`}
                >
                  <MapPin className="w-4 h-4" />
                  {selectedWilaya === "Tous" ? t("Filtrer Wilaya") : t(selectedWilaya)}
                </button>
              </div>

              {/* Algerian Wilayas Horizontal Pill Selector */}
              <div className="space-y-2">
                <div className="flex items-center justify-between text-xs rtl:text-sm font-bold text-slate-400 uppercase tracking-wider rtl:tracking-normal">
                  <span>{t("Wilayas Populaires")}</span>
                  <button
                    onClick={() => setShowAllWilayas(!showAllWilayas)}
                    className="text-slate-600 hover:underline"
                  >
                    {showAllWilayas ? t("Masquer") : t("Voir les 58 Wilayas")}
                  </button>
                </div>

                <div className="flex flex-wrap gap-1.5">
                  {(showAllWilayas ? ALGERIA_WILAYAS : HOT_WILAYAS).map((wilaya) => (
                    <button
                      key={wilaya}
                      onClick={() => setSelectedWilaya(wilaya)}
                      className={`px-4 py-2 rounded-xl text-xs rtl:text-sm font-black transition-all ${
                        selectedWilaya === wilaya
                          ? "bg-slate-900 text-white shadow-md shadow-slate-900/15 scale-102"
                          : "bg-transparent text-slate-600 border border-slate-200/50 hover:bg-slate-100 hover:border-slate-300"
                      }`}
                    >
                      {wilaya}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            {/* RESULTS BOARD */}
            {exploreLoading ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {[1, 2, 3].map((i) => (
                  <div key={i} className="h-96 bg-transparent rounded-3xl animate-pulse border border-slate-200/60" />
                ))}
              </div>
            ) : filteredSellers.length === 0 ? (
              <div className="p-16 text-center text-slate-500 font-medium space-y-4">
                <div className="w-16 h-16 bg-transparent border border-slate-200 rounded-2xl flex items-center justify-center mx-auto text-slate-300">
                  <RefreshCw className="w-6 h-6 animate-spin" />
                </div>
                <h4 className="font-sans font-bold text-lg text-slate-900">{t("Aucune boutique correspondante")}</h4>
                <p className="text-slate-500 text-sm max-w-xs mx-auto">
                  {t("Essayez de modifier vos filtres ou de recherche par nom.")}
                </p>
                <button
                  onClick={() => {
                    setSelectedWilaya("Tous");
                    setSearchQuery("");
                  }}
                  className="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl text-xs rtl:text-sm font-bold"
                >
                  {t("Réinitialiser")}
                </button>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {filteredSellers.map((seller, index) => {
                  const isUserFollowing = stores.some((s) => s.sellerId === seller.id);
                  const isActioning = actionLoadingId === seller.id;
                  const shopProducts = productsMap[seller.id] || [];
                  const bannerColorIndex = index % PRESET_GRADIENTS.length;
                  const customBannerClass = PRESET_GRADIENTS[bannerColorIndex];

                  return (
                    <div
                      key={seller.id}
                      className="bg-white rounded-3xl border border-slate-200/60 overflow-hidden shadow-sm hover:shadow-lg hover:border-slate-300 transition-all duration-300 flex flex-col group relative"
                    >
                      {/* 1. Header Banner & Aesthetic cover */}
                      <div
                        className={`h-24 bg-gradient-to-r ${customBannerClass} relative w-full overflow-hidden shrink-0`}
                      >
                        {seller.bannerUrl ? (
                          <img
