import React, { useState, useRef } from "react";
import { motion } from "motion/react";
import { Camera, AlertCircle, X, Check, Loader2, Trash2 } from "lucide-react";
import toast from "react-hot-toast";
import { storage } from "../../lib/firebase";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";
import { useTranslation } from "react-i18next";

interface ReturnRequestProps {
  orderId: string;
  onClose: () => void;
  onSubmit: (data: any) => Promise<void>;
}

const REASONS = [
  "Produit défectueux / cassé",
  "Mauvaise taille / modèle",
  "Différent de la description",
  "Produit incomplète",
  "Changement d'avis",
];

export const ReturnRequestForm: React.FC<ReturnRequestProps> = ({ orderId, onClose, onSubmit }) => {
  const { t } = useTranslation();
  const [reason, setReason] = useState(REASONS[0]);
  const [details, setDetails] = useState("");
  const [loading, setLoading] = useState(false);
  const [photos, setPhotos] = useState<{ url: string; uploading: boolean }[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []) as File[];
    if (!files.length) return;

    if (photos.length + files.length > 5) {
      toast.error("Vous ne pouvez télécharger que 5 photos maximum.");
      return;
    }

    setLoading(true);
    for (const file of files) {
      if (!file.type.startsWith("image/")) continue;

      const newPhotoObj = { url: "", uploading: true };
      setPhotos((prev) => [...prev, newPhotoObj]);

      const photoIndex = photos.length; // Approximate, but we just update the last one that is uploading

      try {
        const storageRef = ref(storage, `returns/${orderId}/${Date.now()}_${file.name}`);
        await uploadBytes(storageRef, file);
        const url = await getDownloadURL(storageRef);

        setPhotos((prev) => {
          const newPhotos = [...prev];
          // Find the first uploading photo and complete it
          const idx = newPhotos.findIndex((p) => p.uploading);
          if (idx !== -1) {
            newPhotos[idx] = { url, uploading: false };
          }
          return newPhotos;
        });
      } catch (error) {
        console.error("Error uploading return photo:", error);
        toast.error(`Erreur lors du téléchargement de ${file.name}`);
        setPhotos((prev) => prev.filter((p) => p.uploading === false)); // remove failed
      }
    }
    setLoading(false);

    // Reset input
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleRemovePhoto = (index: number) => {
    setPhotos((prev) => prev.filter((_, i) => i !== index));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (photos.some((p) => p.uploading)) {
      toast.error("Veuillez patienter pendant le téléchargement des images.");
      return;
    }

    setLoading(true);
    try {
      const photoUrls = photos.filter((p) => !p.uploading).map((p) => p.url);
      // Adding default values for return request like refundMethod since OrderDetails renders it
      await onSubmit({
        reason,
        details,
        photos: photoUrls,
        refundMethod: "ccp",
        timestamp: new Date().toISOString(),
      });
      toast.success("Demande de retour envoyée avec succès.");
      onClose();
    } catch (e) {
      toast.error("Erreur lors de l'envoi.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="fixed inset-0 z-[100] bg-slate-950/20 backdrop-blur-sm flex items-center justify-center p-4"
    >
      <form
        onSubmit={handleSubmit}
        className="bg-white rounded-[2rem] p-6 w-full max-w-md shadow-2xl relative max-h-[90vh] overflow-y-auto"
      >
        <button type="button" onClick={onClose} className="absolute top-4 end-4 p-2 text-slate-400 hover:text-slate-600">
          <X className="w-5 h-5" />
        </button>
        <h2 className="text-xl font-sans font-bold text-slate-900 mb-6">{t("Demander un retour")}</h2>

        <div className="space-y-4">
          <div>
            <label className="block text-xs rtl:text-sm font-bold text-slate-500 uppercase mb-2">{t("Motif")}</label>
            <select
              value={reason || ""}
              onChange={(e) => setReason(e.target.value)}
              className="w-full p-4 bg-transparent border border-slate-200 rounded-2xl font-medium text-slate-800"
            >
              {REASONS.map((r) => (
                <option key={r} value={r}>
                  {r}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-xs rtl:text-sm font-bold text-slate-500 uppercase mb-2">{t("Détails")}</label>
            <textarea
              value={details || ""}
              onChange={(e) => setDetails(e.target.value)}
              className="w-full p-4 bg-transparent border border-slate-200 rounded-2xl h-24 font-medium text-slate-800 resize-none"
              placeholder={t("Expliquez en détail le problème...") || "Expliquez en détail le problème..."}
            />
          </div>

          <div>
            <label className="block text-xs rtl:text-sm font-bold text-slate-500 uppercase mb-2">
              {t("Preuves (Photos)")}
            </label>
            <input
              type="file"
              ref={fileInputRef}
              onChange={handleFileSelect}
              accept="image/*"
              multiple
              className="hidden"
            />
            {photos.length > 0 && (
              <div className="flex flex-wrap gap-3 mb-4">
                {photos.map((photo, idx) => (
                  <div
                    key={idx}
                    className="relative w-16 h-16 rounded-xl overflow-hidden bg-slate-100 border border-slate-200"
                  >
                    {photo.uploading ? (
                      <div className="absolute inset-0 flex items-center justify-center bg-white/60 backdrop-blur-sm">
                        <Loader2 className="w-5 h-5 text-slate-500 animate-spin" />
                      </div>
                    ) : (
                      <>
                        <img
                          loading="lazy"
                          src={photo.url}
                          alt={`Preuve ${idx + 1}`}
                          className="w-full h-full object-cover"
                        />
                        <button
                          type="button"
                          onClick={() => handleRemovePhoto(idx)}
                          className="absolute top-1 right-1 p-0.5 bg-black/50 text-white rounded-full hover:bg-red-500 transition-colors"
                        >
                          <X className="w-3 h-3" />
                        </button>
                      </>
                    )}
                  </div>
                ))}
              </div>
            )}
            {photos.length < 5 && (
              <button
                type="button"
                onClick={() => fileInputRef.current?.click()}
                disabled={loading}
                className="w-full py-3 flex items-center justify-center gap-2 border-2 border-dashed border-slate-300 rounded-2xl text-slate-500 hover:bg-transparent hover:text-slate-700 transition-colors disabled:opacity-50 font-bold"
              >
                <Camera className="w-5 h-5" /> {t("Ajouter des photos (Max 5)")}
              </button>
            )}
          </div>
        </div>

        <button
          disabled={loading}
          className="w-full mt-6 py-4 flex items-center justify-center gap-2 bg-slate-900 text-white rounded-2xl font-bold hover:bg-[#A94320] transition-colors disabled:opacity-50"
        >
          {loading && <Loader2 className="w-5 h-5 animate-spin" />}
          {loading ? "Envoi en cours..." : "Envoyer la demande"}
        </button>
      </form>
    </motion.div>
  );
};

import React, { useState } from "react";
import { ShieldCheck, Mail, Key, Eye, EyeOff, X, Lock } from "lucide-react";
import {
  EmailAuthProvider,
  reauthenticateWithCredential,
  updatePassword as firebaseUpdatePassword,
  verifyBeforeUpdateEmail,
} from "firebase/auth";
import { toast } from "react-hot-toast";
import { useTranslation } from "react-i18next";
import { apiPost } from "../../lib/api";

interface SecuritySettingsProps {
  currentUser: any;
}

export const SecuritySettings: React.FC<SecuritySettingsProps> = ({ currentUser }) => {
  const { t } = useTranslation();
  const [email, setEmail] = useState(currentUser?.email || "");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");

  const [showPassToggle, setShowPassToggle] = useState(false);
  const [loading, setLoading] = useState(false);

  // Re-auth Modal control state
  const [showReauthModal, setShowReauthModal] = useState(false);
  const [currentPassword, setCurrentPassword] = useState("");
  const [reauthAction, setReauthAction] = useState<"email" | "password" | null>(null);

  const triggerEmailUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email.trim() || email === currentUser.email) {
      return toast.error("Veuillez entrer une nouvelle adresse e-mail différente.");
    }
    setReauthAction("email");
    setCurrentPassword("");
    setShowReauthModal(true);
  };

  const triggerPasswordUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (newPassword.length < 6) {
      return toast.error("Le mot de passe doit mesurer au moins 6 caractères.");
    }
    if (newPassword !== confirmPassword) {
      return toast.error("Les mots de passe ne correspondent pas.");
    }
    setReauthAction("password");
    setCurrentPassword("");
    setShowReauthModal(true);
  };

  const executeReauthenticatedAction = async () => {
    if (!currentPassword.trim()) {
      return toast.error("Veuillez saisir votre mot de passe actuel.");
    }

    setLoading(true);
    try {
      // 1. Establish Credentials
      const credential = EmailAuthProvider.credential(currentUser.email!, currentPassword);

      // 2. Perform Re-authentication
      await reauthenticateWithCredential(currentUser, credential);

      // 3. Execute main mutation based on selected flow
      if (reauthAction === "email") {
        // Safe update with state-of-the-art verification flow
        await verifyBeforeUpdateEmail(currentUser, email);

        // Update user Firestore document too
        await apiPost("/api/v1/auth/profile", {
          email: email,
        });

        toast.success("E-mail de vérification envoyé à la nouvelle adresse ! Veuillez vérifier votre boîte mail.");
        setShowReauthModal(false);
      } else if (reauthAction === "password") {
        await firebaseUpdatePassword(currentUser, newPassword);
        toast.success("Mot de passe mis à jour avec succès !");
        setNewPassword("");
        setConfirmPassword("");
        setShowReauthModal(false);
      }
    } catch (err: any) {
      console.error("Re-authentication fail:", err);
      if (err.code === "auth/wrong-password" || err.code === "auth/invalid-credential") {
        toast.error("Mot de passe actuel incorrect.");
      } else {
        toast.error(err.message || "Erreur lors de la sécurisation.");
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-8" id="security-settings-module">
      <div>
        <h3 className="font-sans font-bold text-xl text-slate-900 tracking-tight rtl:tracking-normal">
          {t("Configuration de Sécurité")}
        </h3>
        <p className="text-slate-500 text-xs rtl:text-sm font-medium">
          {t("Gérez vos accès et sécurisez votre connexion d'e-commerce.")}
        </p>
      </div>

      <div className="grid md:grid-cols-2 gap-8">
        {/* Email Form */}
        <form
          onSubmit={triggerEmailUpdate}
          className="bg-white border border-slate-100 p-8 rounded-3xl space-y-6 shadow-sm"
        >
          <div className="flex items-center gap-3 mb-2">
            <div className="w-8 h-8 rounded-xl bg-blue-50 flex items-center justify-center text-blue-600">
              <Mail className="w-4 h-4" />
            </div>
            <h4 className="font-sans font-bold text-xs rtl:text-sm uppercase tracking-wider rtl:tracking-normal text-slate-900">
              {t("Adresse de Connexion")}
            </h4>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] rtl:text-[12px] font-bold text-slate-400 uppercase tracking-wider rtl:tracking-normal">
              {t("Adresse E-mail actuelle et valide")}
            </label>
            <input
              type="email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full px-5 py-3.5 bg-transparent border border-slate-100 rounded-2xl font-bold text-xs rtl:text-sm outline-none focus:bg-white focus:border-slate-500 transition-all text-slate-700"
              placeholder={t("Ex: abc@gmail.com") || "Ex: abc@gmail.com"}
            />
          </div>

          <div className="pt-2">
            <button
              type="submit"
              className="w-full py-4 bg-slate-100 hover:bg-slate-200 text-slate-800 rounded-2xl font-sans font-bold text-[10px] rtl:text-[12px] uppercase tracking-widest rtl:tracking-normal transition-all focus:scale-95 text-center min-h-[44px]"
            >
              {t("Mettre à jour l'e-mail")}
            </button>
          </div>
        </form>

        {/* Password Form */}
        <form
          onSubmit={triggerPasswordUpdate}
          className="bg-white border border-slate-100 p-8 rounded-3xl space-y-6 shadow-sm"
        >
          <div className="flex items-center gap-3 mb-2">
            <div className="w-8 h-8 rounded-xl bg-transparent flex items-center justify-center text-slate-600">
              <Key className="w-4 h-4" />
            </div>
            <h4 className="font-sans font-bold text-xs rtl:text-sm uppercase tracking-wider rtl:tracking-normal text-slate-900">
              {t("Changer de Mot de passe")}
            </h4>
          </div>

          <div className="space-y-4">
            <div className="space-y-2 relative">
              <label className="text-[10px] rtl:text-[12px] font-bold text-slate-400 uppercase tracking-wider rtl:tracking-normal">
                {t("Nouveau Mot de passe")}
              </label>
              <input
                type={showPassToggle ? "text" : "password"}
                required
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                className="w-full px-5 py-3.5 bg-transparent border border-slate-100 rounded-2xl font-bold text-xs rtl:text-sm outline-none focus:bg-white focus:border-slate-500 transition-all text-slate-700"
                placeholder={t("Minimum 6 caractères") || "Minimum 6 caractères"}
              />
              <button
                type="button"
                onClick={() => setShowPassToggle(!showPassToggle)}
                className="absolute end-4 top-[38px] text-slate-400 hover:text-slate-600 p-1"
              >
                {showPassToggle ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
              </button>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] rtl:text-[12px] font-bold text-slate-400 uppercase tracking-wider rtl:tracking-normal font-sans">
                {t("Confirmer le Mot de passe")}
              </label>
              <input
                type={showPassToggle ? "text" : "password"}
                required
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                className="w-full px-5 py-3.5 bg-transparent border border-slate-100 rounded-2xl font-bold text-xs rtl:text-sm outline-none focus:bg-white focus:border-slate-500 transition-all text-slate-700"
                placeholder={t("Répétez le nouveau mot de passe") || "Répétez le nouveau mot de passe"}
              />
            </div>
          </div>

          <div className="pt-2">
            <button
              type="submit"
              className="w-full py-4 bg-slate-900 hover:bg-slate-800 text-white rounded-2xl font-sans font-bold text-[10px] rtl:text-[12px] uppercase tracking-widest rtl:tracking-normal transition-all focus:scale-95 text-center min-h-[44px]"
            >
              {t("Changer mon mot de passe")}
            </button>
          </div>
        </form>
      </div>

      {/* Re-Authentication Verification Modal (CRITICAL ARCHITECTURE REQUIREMENT) */}
      {showReauthModal && (
        <div className="fixed inset-0 z-50 bg-slate-950/60 backdrop-blur-md flex items-center justify-center p-4 animate-fadeIn">
          <div className="bg-white rounded-[2rem] border border-slate-150 p-8 max-w-md w-full relative shadow-2xl space-y-6">
            <button
              onClick={() => {
                setShowReauthModal(false);
                setReauthAction(null);
              }}
              className="absolute end-6 top-6 p-2 text-slate-400 hover:text-slate-900 rounded-full hover:bg-transparent transition-all"
            >
              <X className="w-5 h-5" />
            </button>

            <div className="text-center space-y-3">
              <div className="w-12 h-12 bg-red-50 text-red-600 rounded-2xl flex items-center justify-center mx-auto">
                <Lock className="w-6 h-6 animate-bounce" />
              </div>
              <h3 className="font-extrabold text-lg text-slate-900 tracking-tight rtl:tracking-normal">
                {t("Vérification de Sécurité")}
              </h3>
              <p className="text-slate-500 text-xs rtl:text-sm">
                {t(
                  "Par mesure de sécurité hautement requise par Olma, veuillez confirmer votre mot de passe de connexion actuel avant de modifier vos informations d'identité sensibles."
                )}
              </p>
            </div>

            <div className="space-y-4 pt-2">
              <div className="space-y-2">
                <label className="text-[10px] rtl:text-[12px] font-sans font-bold text-slate-400 uppercase tracking-widest rtl:tracking-normal block leading-none">
                  {t("Votre mot de passe actuel")}
                </label>
                <input
                  type="password"
                  required
                  value={currentPassword}
                  onChange={(e) => setCurrentPassword(e.target.value)}
                  className="w-full px-5 py-4 bg-transparent border border-slate-200 rounded-xl font-bold text-xs rtl:text-sm outline-none focus:bg-white focus:ring-4 focus:ring-red-500/10 focus:border-red-500 transition-all"
                  placeholder={t("Saisissez votre mot de passe actuel") || "Saisissez votre mot de passe actuel"}
                />
              </div>

              <div className="flex gap-3 pt-4 border-t border-slate-100">
                <button
                  type="button"
                  onClick={() => {
                    setShowReauthModal(false);
                    setReauthAction(null);
                  }}
                  className="flex-1 py-3.5 border border-slate-200 text-slate-700 font-extrabold text-[10px] rtl:text-[12px] uppercase tracking-widest rtl:tracking-normal rounded-xl hover:bg-transparent active:scale-95 transition-all text-center"
                >
                  {t("Annuler")}
                </button>
                <button
                  type="button"
                  disabled={loading}
                  onClick={executeReauthenticatedAction}
                  className="flex-1 py-3.5 bg-red-600 hover:bg-red-700 text-white font-extrabold text-[10px] rtl:text-[12px] uppercase tracking-widest rtl:tracking-normal rounded-xl disabled:opacity-50 active:scale-95 transition-all text-center"
                >
                  {loading ? t("security.verifying", "Vérification...") : t("security.confirm", "Confirmer")}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

