import React, { useMemo } from "react";
import { ShoppingBag, Package, ArrowRight, X, Trash2, Plus, Minus } from "lucide-react";
import { useTranslation } from "react-i18next";
import { useNavigate } from "react-router-dom";
import { useCart } from "../../context/CartContext";
import { SideDrawer } from "../SideDrawer";
import { formatPrice } from "../../utils/format";
import { getTranslatedField } from "../../utils/translations";
import { Language } from "../../domains/home/homepage.types";
import { getOptimizedImageUrl } from "../../utils/imageUtils";
import { useConfirm } from "../../hooks/useConfirm";

export const CartDrawer: React.FC<{ isOpen: boolean; onClose: () => void }> = ({ isOpen, onClose }) => {
  const { cart, removeFromCart, updateQuantity, totalPrice, getCartItemPrice } = useCart();
  const { confirm: showConfirmModal, ConfirmationDialog } = useConfirm();
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const lang = i18n.language as Language;

  // Group items by seller
  const groupedCart = useMemo(() => {
    const groups: Record<string, { sellerName: string; items: any[]; total: number }> = {};
    cart.forEach((item, index) => {
      const sellerId = item.sellerId || "unknown";
      const sellerName = item.sellerName || item.shopName || "Boutique Partenaire";
      if (!groups[sellerId]) {
        groups[sellerId] = { sellerName, items: [], total: 0 };
      }
      groups[sellerId].items.push({ ...item, originalIndex: index });
      groups[sellerId].total += getCartItemPrice(item) * item.quantity;
    });
    return groups;
  }, [cart, getCartItemPrice]);

  return (
    <SideDrawer
      isOpen={isOpen}
      onClose={onClose}
      title={t("Mon Panier") || "Mon Panier"}
      icon={<ShoppingBag className="w-5 h-5" />}
    >
      <div className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-8 bg-transparent">
        {cart.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-center space-y-6 px-4">
            <div className="w-24 h-24 bg-[var(--color-orange-600, #ea580c)]/10 rounded-full flex items-center justify-center text-[var(--color-orange-600, #ea580c)] mb-2">
              <Package className="w-10 h-10" />
            </div>
            <div className="space-y-2">
              <h3 className="text-xl font-sans font-bold text-[var(--color-slate-900, #0f172a)]">{t("Votre panier est curieusement léger...")}</h3>
              <p className="text-stone-500 font-semibold text-sm">{t("Remplissons-le avec des trésors uniques !")}</p>
            </div>
            <button
              onClick={() => {
                onClose();
                navigate("/shop");
              }}
              className="btn-premium-orange w-full"
            >
              {t("Découvrir les tendances")}
            </button>
          </div>
        ) : (
          Object.values(groupedCart).map((group: any, groupIdx) => {
            // Free shipping threshold logic (example threshold: 5000 DA)
            const threshold = 5000;
            const remaining = Math.max(0, threshold - group.total);
            const progress = Math.min(100, (group.total / threshold) * 100);

            return (
              <div
                key={groupIdx}
                className="bg-white rounded-3xl p-4 sm:p-5 shadow-sm border border-stone-100 flex flex-col gap-4"
              >
                {/* Seller Header */}
                <div className="flex flex-col gap-2 border-b border-stone-100 pb-3">
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                      <span className="bg-[var(--color-slate-900, #0f172a)] text-white text-[9px] rtl:text-[11px] font-sans font-bold uppercase tracking-widest rtl:tracking-normal px-2 py-0.5 rounded-full">
                        {t("Sous-colis")}
                        {groupIdx + 1}
                      </span>
                      <h3 className="font-sans font-bold text-sm text-[var(--color-slate-900, #0f172a)] uppercase tracking-widest rtl:tracking-normal leading-none">
                        {group.sellerName}
                      </h3>
                    </div>
                    <span className="text-xs rtl:text-sm font-bold text-stone-500">
                      {group.items.length} {t("Article(s)")}
                    </span>
                  </div>

                  {/* Incentive Progress Bar */}
                  {remaining > 0 ? (
                    <div className="space-y-1.5">
                      <p className="text-[10px] rtl:text-[12px] sm:text-xs rtl:text-sm font-bold text-stone-500">
                        {t("Ajoutez encore")}
                        <span className="text-[var(--color-orange-600, #ea580c)]">{formatPrice(remaining)}</span>{" "}
                        {t("pour amortir la livraison !")}
                      </p>
                      <div className="h-1.5 w-full bg-stone-100 rounded-full overflow-hidden">
                        <div
                          className="h-full bg-[var(--color-orange-600, #ea580c)] transition-all duration-500"
                          style={{ width: `${progress}%` }}
                        />
                      </div>
                    </div>
                  ) : (
                    <div className="space-y-1.5">
                      <p className="text-[10px] rtl:text-[12px] sm:text-xs rtl:text-sm font-bold text-emerald-600">
                        {t("🎉 Excellent ! Vous optimisez vos frais de livraison chez ce vendeur.")}
                      </p>
                      <div className="h-1.5 w-full bg-stone-100 rounded-full overflow-hidden">
                        <div className="h-full bg-emerald-500 w-full" />
                      </div>
                    </div>
                  )}
                </div>

                {/* Items */}
                <div className="space-y-4">
                  {group.items.map((item, i) => (
                    <div key={i} className="flex gap-4 group/item">
                      <div className="w-20 h-24 sm:w-24 sm:h-28 rounded-2xl overflow-hidden bg-transparent shrink-0 border border-stone-100 relative">
                        <img
                          loading="lazy"
                          src={getOptimizedImageUrl(item.image, 200)}
                          className="w-full h-full object-cover"
                          alt={getTranslatedField(item, "name", lang)}
                        />
                      </div>
                      <div className="flex-1 flex flex-col justify-between py-1">
                        <div>
                          <div className="flex justify-between items-start gap-2">
                            <h4 className="font-bold text-xs rtl:text-sm sm:text-sm text-[var(--color-slate-900, #0f172a)] line-clamp-2">
                              {getTranslatedField(item, "name", lang)}
                            </h4>
                            <button
                              onClick={async () => {
                                const ok = await showConfirmModal(
                                  t("Êtes-vous sûr de vouloir retirer cet article de votre panier ?") || "Êtes-vous sûr de vouloir retirer cet article de votre panier ?",
                                  t("Retirer un article") || "Retirer un article"
                                );
                                if (ok) {
                                  removeFromCart(item.originalIndex);
                                }
                              }}
                              className="text-stone-300 hover:text-red-500 transition-colors p-1 bg-transparent rounded-full"
                            >
                              <Trash2 className="w-3.5 h-3.5" />
                            </button>
                          </div>
                          {item.selectedVariant && (
                            <p className="text-[9px] font-bold text-stone-500 uppercase tracking-widest mt-0.5">
                              {item.selectedVariant}
                            </p>
                          )}
                          <p className="text-[10px] rtl:text-[12px] font-bold text-[var(--color-orange-600, #ea580c)] uppercase tracking-widest rtl:tracking-normal mt-1">
                            {formatPrice(getCartItemPrice(item))}
                          </p>
                        </div>

                        {/* Quantity Controls */}
                        <div className="flex items-center justify-between mt-2">
                          <div className="flex items-center gap-3 bg-transparent rounded-full px-2 py-1 border border-stone-200">
                            <button
                              disabled={item.quantity <= 1}
                              onClick={() => updateQuantity(item.originalIndex, item.quantity - 1)}
                              className="w-6 h-6 flex items-center justify-center text-[var(--color-slate-900, #0f172a)] disabled:text-stone-300 hover:bg-white rounded-full transition-colors"
                            >
                              <Minus className="w-3 h-3" />
                            </button>
                            <span className="text-xs rtl:text-sm font-sans font-bold min-w-[12px] text-center text-[var(--color-slate-900, #0f172a)]">
                              {item.quantity}
                            </span>
                            <button
                              onClick={() => updateQuantity(item.originalIndex, item.quantity + 1)}
                              className="w-6 h-6 flex items-center justify-center text-[var(--color-slate-900, #0f172a)] hover:bg-white rounded-full transition-colors"
                            >
                              <Plus className="w-3 h-3" />
                            </button>
                          </div>
                          <p className="text-sm font-sans font-bold text-[var(--color-slate-900, #0f172a)]">
                            {formatPrice(getCartItemPrice(item) * item.quantity)}
                          </p>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            );
          })
        )}
      </div>

      {cart.length > 0 && (
        <div className="p-4 sm:p-6 border-t border-stone-100 space-y-4 bg-white">
          <div className="flex items-center justify-between text-sm sm:text-base font-medium">
            <span className="text-stone-400 font-bold uppercase tracking-widest rtl:tracking-normal text-[10px] rtl:text-[12px] sm:text-xs rtl:text-sm">
              {t("Sous-total")}
            </span>
            <span className="text-xl sm:text-2xl font-sans font-bold text-[var(--color-slate-900, #0f172a)]">{formatPrice(totalPrice)}</span>
          </div>
          <button
            onClick={() => {
              onClose();
              navigate("/checkout");
            }}
            className="btn-premium-orange w-full flex items-center justify-center gap-2"
          >
            {t("Passer à la caisse")}
            <ArrowRight className="w-4 h-4" />
          </button>
        </div>
      )}
      <ConfirmationDialog />
    </SideDrawer>
  );
};

import React, { useState, useRef, useEffect } from "react";
import { motion, AnimatePresence } from "motion/react";
import { X, Send, Bot, User, Loader2 } from "lucide-react";
import { useTranslation } from "react-i18next";
import { useAuth } from "../../context/AuthContext";

interface AiChatDrawerProps {
  isOpen: boolean;
  onClose: () => void;
}

interface Message {
  role: "user" | "model";
  parts: { text: string }[];
}

export const AiChatDrawer: React.FC<AiChatDrawerProps> = ({ isOpen, onClose }) => {
  const { t } = useTranslation();
  const { currentUser } = useAuth();
  const [messages, setMessages] = useState<Message[]>([
    {
      role: "model",
      parts: [
        { text: "Bonjour ! Je suis Olma, votre assistant IA personnel. Comment puis-je vous aider aujourd'hui ?" },
      ],
    },
  ]);
  const [inputValue, setInputValue] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const endOfMessagesRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isOpen) {
      endOfMessagesRef.current?.scrollIntoView({ behavior: "smooth" });
    }
  }, [messages, isOpen]);

  const handleSendMessage = async (textToSend?: string) => {
    const text = textToSend || inputValue;
    if (!text.trim() || isLoading) return;

    const newUserMsg: Message = { role: "user", parts: [{ text }] };
    const conversationHistory = [...messages, newUserMsg];
    setMessages(conversationHistory);
    if (!textToSend) {
      setInputValue("");
    }
    setIsLoading(true);

    // Instant local FAQ responses for specific common queries
    let localReply = "";
    const lowerText = text.toLowerCase();
    if (lowerText.includes("statut") || lowerText.includes("suivre") || lowerText.includes("suivi")) {
      localReply = "Pour vérifier le statut de votre commande, accédez à l'onglet 'Mes Commandes' dans votre Tableau de bord Acheteur ou cliquez sur la commande concernée dans vos notifications. Toutes les étapes (préparation, expédition, livraison) y sont suivies en temps réel ! 📦";
    } else if (lowerText.includes("livraison") || lowerText.includes("délai") || lowerText.includes("wilaya")) {
      localReply = "Olmart livre sur l'ensemble des 58 Wilayas d'Algérie ! Les délais de livraison varient généralement entre 24h et 5 jours selon l'artisan vendeur et la destination. Vous pouvez estimer les frais de livraison précis grâce au calculateur présent sur chaque panier ou fiche produit 🚚.";
    } else if (lowerText.includes("retour") || lowerText.includes("rembourser") || lowerText.includes("remboursement")) {
      localReply = "Conformément à notre charte de confiance, vous pouvez demander le retour d'un produit non conforme ou défectueux directement depuis les détails de la commande sous 7 jours après réception. Le support Olmart interviendra pour valider l'action avec l'artisan concerné 🔄.";
    }

    if (localReply) {
      setTimeout(() => {
        setMessages([...conversationHistory, { role: "model", parts: [{ text: localReply }] }]);
        setIsLoading(false);
      }, 700);
      return;
    }

    try {
      const idToken = currentUser ? await currentUser.getIdToken() : null;
      const headers: Record<string, string> = { "Content-Type": "application/json" };
      if (idToken) {
        headers["Authorization"] = `Bearer ${idToken}`;
      }

      const response = await fetch("/api/v1/chat", {
        method: "POST",
        headers,
        body: JSON.stringify({
          message: newUserMsg.parts[0].text,
          history: messages.slice(1).map((m) => ({
            // Don't send initial offline greeting
            role: m.role,
            parts: [{ text: m.parts[0].text }],
          })),
        }),
      });
      const data = await response.json();

      if (!response.ok) throw new Error(data.error || "Erreur API");

      setMessages([...conversationHistory, { role: "model", parts: [{ text: data.reply }] }]);
    } catch (error) {
      console.error(error);
      setMessages([
        ...conversationHistory,
        {
          role: "model",
          parts: [
            { text: "Désolé, je rencontre des difficultés techniques actuellement. Veuillez réessayer plus tard." },
          ],
        },
      ]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 bg-black/40 backdrop-blur-sm z-50 transition-all"
          />
          <motion.div
            initial={{ x: "100%", borderTopLeftRadius: "2rem", borderBottomLeftRadius: "2rem" }}
            animate={{ x: 0, borderTopLeftRadius: "1.5rem", borderBottomLeftRadius: "1.5rem" }}
            exit={{ x: "100%", borderTopLeftRadius: "2rem", borderBottomLeftRadius: "2rem" }}
            transition={{ type: "spring", bounce: 0, duration: 0.4 }}
            className="fixed inset-y-0 right-0 w-full md:w-[400px] bg-white shadow-2xl z-50 flex flex-col border-l border-zinc-100 overflow-hidden"
          >
            {/* Header */}
            <div className="flex items-center justify-between px-6 py-5 border-b border-zinc-100 bg-zinc-50/50">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-full bg-orange-100 text-orange-600 flex items-center justify-center">
                  <Bot className="w-5 h-5" />
                </div>
                <div>
                  <h3 className="text-zinc-900 font-bold text-sm tracking-wide">{t("Assistant Olma Gemini")}</h3>
                  <span className="text-green-600 font-semibold text-[10px] rtl:text-[12px] tracking-widest rtl:tracking-normal uppercase flex items-center gap-1">
                    <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></span> {t("En ligne")}
                  </span>
                </div>
              </div>
              <button
                onClick={onClose}
                className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-zinc-200 text-zinc-500 transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            {/* Chat Area */}
            <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-zinc-50/30">
              {messages.map((msg, idx) => (
                <div key={idx} className={`flex gap-4 ${msg.role === "user" ? "flex-row-reverse" : "flex-row"}`}>
                  <div
                    className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${msg.role === "user" ? "bg-zinc-900 text-white" : "bg-orange-600 text-white"}`}
                  >
                    {msg.role === "user" ? <User className="w-4 h-4" /> : <Bot className="w-4 h-4" />}
                  </div>
                  <div
                    className={`p-4 rounded-2xl max-w-[80%] text-sm leading-relaxed ${msg.role === "user" ? "bg-zinc-900 text-white rounded-tr-sm" : "bg-white border border-zinc-100 shadow-sm text-zinc-700 rounded-tl-sm"}`}
                  >
                    {msg.parts[0].text}
                  </div>
                </div>
              ))}
              {isLoading && (
                <div className="flex gap-4 flex-row">
                  <div className="w-8 h-8 rounded-full bg-orange-600 text-white flex items-center justify-center shrink-0">
                    <Bot className="w-4 h-4" />
                  </div>
                  <div className="bg-white border border-zinc-100 shadow-sm text-zinc-700 p-4 rounded-2xl rounded-tl-sm flex gap-1">
                    <span className="w-1.5 h-1.5 bg-zinc-300 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                    <span className="w-1.5 h-1.5 bg-zinc-300 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                    <span className="w-1.5 h-1.5 bg-zinc-300 rounded-full animate-bounce"></span>
                  </div>
                </div>
              )}
              <div ref={endOfMessagesRef} />
            </div>

            {/* Input Area */}
            <div className="p-4 border-t border-zinc-100 bg-white flex flex-col gap-3">
              {/* Quick Replies FAQ Chips */}
              <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-none shrink-0" style={{ scrollbarWidth: 'none' }}>
                <button
                  type="button"
                  onClick={() => handleSendMessage("Comment suivre le statut de ma commande ?")}
                  className="px-3 py-1.5 bg-zinc-50 border border-zinc-200 hover:border-orange-200 hover:bg-orange-50 hover:text-orange-600 rounded-full text-[11px] font-sans font-bold transition-all whitespace-nowrap cursor-pointer text-zinc-700"
                >
                  📦 Statut de commande
                </button>
                <button
                  type="button"
                  onClick={() => handleSendMessage("Quels sont les délais de livraison ?")}
                  className="px-3 py-1.5 bg-zinc-50 border border-zinc-200 hover:border-orange-200 hover:bg-orange-50 hover:text-orange-600 rounded-full text-[11px] font-sans font-bold transition-all whitespace-nowrap cursor-pointer text-zinc-700"
                >
                  🚚 Délais de livraison
                </button>
                <button
                  type="button"
                  onClick={() => handleSendMessage("Comment retourner un produit défectueux ?")}
                  className="px-3 py-1.5 bg-zinc-50 border border-zinc-200 hover:border-orange-200 hover:bg-orange-50 hover:text-orange-600 rounded-full text-[11px] font-sans font-bold transition-all whitespace-nowrap cursor-pointer text-zinc-700"
                >
                  🔄 Retourner un produit
                </button>
              </div>

              <form
                onSubmit={(e) => {
                  e.preventDefault();
                  handleSendMessage();
                }}
                className="flex items-center gap-2"
              >
                <input
                  type="text"
                  value={inputValue}
                  onChange={(e) => setInputValue(e.target.value)}
                  placeholder={t("Posez votre question...") || "Posez votre question..."}
                  className="flex-1 bg-zinc-100 border-none rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-orange-500/20 outline-none transition-all"
                  disabled={isLoading}
                />
                <button
                  type="submit"
                  disabled={!inputValue.trim() || isLoading}
                  className="w-12 h-12 flex items-center justify-center bg-orange-600 text-white rounded-xl hover:bg-orange-700 active:scale-95 transition-all disabled:opacity-50 disabled:active:scale-100"
                >
                  <Send className="w-5 h-5" />
                </button>
              </form>
            </div>
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
};

