        <div className="flex items-center gap-3 shrink-0 ms-4">
          <button onClick={clear} className="p-2 text-slate-500 hover:text-red-500 hover:bg-transparent rounded-lg transition-colors">
            <Trash2 className="w-5 h-5" />
          </button>
          <button 
            onClick={() => navigate('/compare')}
            disabled={products.length < 2}
            className="flex items-center gap-2 bg-slate-900 hover:bg-orange-600 text-white px-6 py-3 rounded-xl font-bold transition-colors disabled:opacity-50 disabled:cursor-not-allowed text-sm"
          >
            <Scale className="w-4 h-4" />
            {t("comparer") || "Comparer"}
          </button>
        </div>
      </div>
    </motion.div>
  );
};

