              <div className="flex flex-wrap items-center gap-2">
                {flashProducts.some((p) => p.flashSaleActive || p.promoPrice) && (
                  <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-rose-100 text-rose-600 text-[10px] sm:text-[11px] font-sans font-bold uppercase tracking-wider shadow-sm border border-rose-200/60">
