  );
};

import React, { useState, useEffect, useRef } from "react";
import { motion, AnimatePresence } from "motion/react";
import { Link } from "react-router-dom";
import { useMegaMenu, FeaturedProduct } from "../context/MegaMenuContext";
import { useShop } from "../context/ShopContext";
import { useTranslation } from "react-i18next";
import { CATEGORY_ICONS } from "../constants";
import { Box } from "lucide-react";
import { Product } from "../domains/product/product.types";
import { Language } from "../domains/home/homepage.types";
import { getTranslatedField } from "../utils/translations";

export interface MegaMenuProps {
  isVisible?: boolean;
}

export const MegaMenu: React.FC<MegaMenuProps> = ({ isVisible = true }) => {
  const { categoriesData } = useMegaMenu();
  const { fetchProductsByIds } = useShop();
  const { t, i18n } = useTranslation();
  const [activeCategory, setActiveCategory] = useState<string | null>(null);
  const [activeSectionName, setActiveSectionName] = useState<string | null>(null);
  const [hoveredProduct, setHoveredProduct] = useState<FeaturedProduct | null>(null);
  const [productCache, setProductCache] = useState<Record<string, Product>>({});
  const menuRef = useRef<HTMLDivElement>(null);

  // Close active category when menu is hidden on scroll
  useEffect(() => {
    if (!isVisible) {
      setActiveCategory(null);
    }
  }, [isVisible]);

  // Fermer le menu si on clique à l'extérieur
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setActiveCategory(null);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const activeCategoryData = categoriesData.find((c) => c.id === activeCategory);

  // Pre-fetch related products when a category is opened
  useEffect(() => {
    if (!activeCategoryData) return;
    const idsToFetch = new Set<string>();
    if (activeCategoryData.featuredProduct?.productId) {
      idsToFetch.add(activeCategoryData.featuredProduct.productId);
    }
    activeCategoryData.sections.forEach((sec) => {
      sec.links.forEach((link: any) => {
        if (link.featuredProduct?.productId) {
          idsToFetch.add(link.featuredProduct.productId);
        }
      });
    });

    const neededIds = Array.from(idsToFetch).filter((id) => !productCache[id]);
    if (neededIds.length > 0) {
      fetchProductsByIds(neededIds).then((prods) => {
        setProductCache((prev) => {
          const next = { ...prev };
          prods.forEach((p) => {
            next[p.id] = p;
          });
          return next;
        });
      });
    }
  }, [activeCategoryData, fetchProductsByIds, productCache]);

  // Réinitialiser les états de survol lorsqu'on change de catégorie principale
  useEffect(() => {
    if (activeCategoryData && activeCategoryData.sections.length > 0) {
      setActiveSectionName(activeCategoryData.sections[0].name);
    } else {
      setActiveSectionName(null);
    }
    setHoveredProduct(null);
  }, [activeCategory, activeCategoryData]);

  const toggleCategory = (id: string) => {
    setActiveCategory((prev) => (prev === id ? null : id));
  };

  const displayedProductInfo = hoveredProduct || activeCategoryData?.featuredProduct;
  const productToDisplay = displayedProductInfo?.productId ? productCache[displayedProductInfo.productId] : null;

  return (
    <motion.div
      ref={menuRef}
      initial={false}
      animate={{
        height: isVisible ? "auto" : 0,
        opacity: isVisible ? 1 : 0,
        borderTopWidth: isVisible ? "1px" : "0px",
        borderBottomWidth: isVisible ? "1px" : "0px",
      }}
      transition={{ duration: 0.3, ease: [0.16, 1, 0.3, 1] }}
      className="relative w-full z-40 bg-white border-slate-100 text-slate-900 font-sans hidden xl:block shadow-sm overflow-hidden"
    >
      {/* Barre secondaire des catégories (Clic uniquement) */}
      <div className="max-w-[1600px] mx-auto px-6">
        <ul className="flex items-center justify-between overflow-x-auto scrollbar-hide py-3">
          {categoriesData.map((category) => {
            const IconComponent = CATEGORY_ICONS[category.name] || Box;

            return (
              <li key={category.id} className="relative shrink-0">
                <button
                  onClick={() => toggleCategory(category.id)}
                  className={`py-3 transition-colors cursor-pointer border-none bg-transparent flex items-center justify-center px-1`}
                >
                  <span
                    className={`flex flex-col items-center justify-center gap-1 ${activeCategory === category.id ? "text-orange-600" : "text-slate-600 hover:text-orange-600"}`}
                    title={t(category.name) || category.name}
                  >
                    {category.iconUrl ? (
                      <img
                        src={category.iconUrl}
                        alt={category.name}
                        className="w-8 h-8 object-contain"
                        referrerPolicy="no-referrer"
                      />
                    ) : (
                      <IconComponent className="w-8 h-8 stroke-[1.5]" />
                    )}
                  </span>
                </button>

                {/* Soulignement pour la catégorie active */}
                {activeCategory === category.id && (
                  <div className="absolute bottom-0 start-0 w-full h-[2px] bg-orange-600 rounded-t-full shadow-[0_0_8px_rgba(234,88,12,0.4)]" />
                )}
              </li>
            );
          })}
        </ul>
      </div>

      {/* Panneau Blanc du Mega Menu Déroulant */}
      <AnimatePresence>
        {activeCategoryData && (
          <motion.div
            initial={{ opacity: 0, y: 10, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 5, scale: 0.98 }}
            transition={{ duration: 0.3, ease: [0.16, 1, 0.3, 1] }}
            className="absolute top-full start-0 w-full bg-white text-black border-t border-slate-200 shadow-2xl"
          >
            <div className="w-full max-w-[1600px] mx-auto px-6 py-10">
              <div className="grid grid-cols-12 gap-12">
                {/* 1ère Colonne : Liste des sous-catégories (Sections) */}
                <div className="col-span-3 pe-4">
                  <h3 className="text-xl font-display italic tracking-[0.1em] rtl:tracking-normal text-slate-900 mb-6 uppercase">
                    {t("sub_categories") || "Sous-catégories"}
                  </h3>
                  <ul className="flex flex-col gap-1">
                    {activeCategoryData.sections.map((section, idx) => {
                      const isActive = activeSectionName === section.name;
                      return (
                        <li key={idx}>
                          <button
                            onClick={() => setActiveSectionName(section.name)}
                            onMouseEnter={() => {
                              if (!isActive) {
                                setActiveSectionName(section.name);
                              }
                            }}
                            className={`w-full text-start py-3 px-5 rounded-2xl text-[15px] font-semibold transition-all duration-300 flex items-center justify-between group relative overflow-hidden ${
                              isActive
                                ? "bg-black text-white shadow-md"
                                : "bg-transparent text-zinc-500 hover:text-black hover:bg-zinc-100"
                            }`}
                          >
                            <span className="relative z-10 line-clamp-1">{t(section.name) || section.name}</span>
                            <div className="relative z-10">
                              <svg
                                className={`w-4 h-4 shrink-0 transition-transform duration-300 rtl:-scale-x-100 ${isActive ? "text-white translate-x-1 rtl:-translate-x-1" : "opacity-0 -translate-x-2 rtl:translate-x-2 group-hover:opacity-100 group-hover:translate-x-0"}`}
                                fill="none"
                                stroke="currentColor"
                                viewBox="0 0 24 24"
                              >
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                              </svg>
                            </div>
                          </button>
                        </li>
                      );
                    })}
                  </ul>
                </div>

                {/* 2ème et 3ème Colonnes : Sous-sous-catégories (Liens) */}
                <div className="col-span-6 ps-4 border-s border-zinc-100/60">
                  <h3 className="text-[10px] rtl:text-[12px] font-sans font-bold tracking-[0.2em] rtl:tracking-normal text-zinc-400 mb-6 uppercase">
                    {activeSectionName ? t(activeSectionName) || activeSectionName : t("explore") || "Explorer"}
                  </h3>
                  {activeCategoryData.sections
                    .filter((sec) => sec.name === activeSectionName)
                    .map((activeSection) => (
                      <div key={activeSection.name} className="grid grid-cols-2 gap-x-8 gap-y-2">
                        {activeSection.links.map((link, linkIdx) => (
                          <div key={linkIdx} className="break-inside-avoid">
                            <Link
                              to={(activeCategoryData.name.toLowerCase() === 'electromenager' || activeCategoryData.name.toLowerCase() === 'électroménager') ? `/univers/electromenager` : `/shop?category=${encodeURIComponent(activeCategoryData.name)}&subcategory=${encodeURIComponent(activeSection.name.trim())}&subsubcategory=${encodeURIComponent(link.name.trim())}`}
                              className="group flex items-center justify-between py-3 px-5 w-full h-full rounded-2xl transition-all duration-300 hover:bg-zinc-100/80"
                              onMouseEnter={() => {
                                if (link.featuredProduct) {
                                  setHoveredProduct(link.featuredProduct);
                                }
                              }}
                            >
                              <span className="text-[14px] font-medium text-zinc-600 group-hover:text-black transition-colors">
                                {t(link.name) || link.name}
                              </span>
                              <svg
                                className="w-3.5 h-3.5 opacity-0 rtl:-scale-x-100 -translate-x-3 rtl:translate-x-3 group-hover:opacity-100 group-hover:translate-x-0 transition-all duration-300 text-black"
                                fill="none"
                                stroke="currentColor"
                                viewBox="0 0 24 24"
                              >
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                              </svg>
                            </Link>
                          </div>
                        ))}
                      </div>
                    ))}
                </div>

                {/* Colonne 4: Produit mis en avant */}
                <div className="col-span-3 ps-8">
                  <div className="flex flex-col h-full">
                    {productToDisplay ? (
                      <div className="flex flex-col">
                        <h3 className="text-[10px] rtl:text-[12px] font-sans font-bold tracking-[0.2em] rtl:tracking-normal text-zinc-400 mb-6 uppercase">
                          {t("featured_product") || "En vedette"}
                        </h3>
                        <Link
                          to={`/product/${productToDisplay.id}`}
                          className="group flex flex-col relative w-full aspect-[4/5] bg-zinc-50 overflow-hidden rounded-3xl shadow-sm hover:shadow-xl transition-all duration-500"
                        >
                          <img

                            src={productToDisplay.images?.[0] || productToDisplay.image}
                            alt={getTranslatedField(productToDisplay, "name", i18n.language as Language)}
                            className="w-full h-full object-cover transition-transform duration-700 ease-[0.16,1,0.3,1] group-hover:scale-105"
                          />
                          {/* Overlay très subtil sur le bas */}
                          <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/10 to-transparent opacity-80 group-hover:opacity-100 transition-opacity duration-500" />
                          <div className="absolute bottom-6 left-6 right-6 flex flex-col translate-y-2 group-hover:translate-y-0 transition-transform duration-500">
                            <h4 className="text-lg font-bold text-white leading-snug mb-1 line-clamp-2">
                              {getTranslatedField(productToDisplay, "name", i18n.language as Language)}
                            </h4>
                            <p className="text-sm font-semibold text-zinc-200">
                              {productToDisplay.price.toLocaleString("fr-DZ")} {t("DA")}
                            </p>
                          </div>
                        </Link>
                      </div>
                    ) : (
                      <div className="flex flex-col h-full items-center justify-center text-center px-4">
                        {/* Empty State, completely clean if nothing provided by admin */}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

import React from 'react';
import { Helmet } from 'react-helmet-async';
import { useTranslation } from 'react-i18next';

interface MetaTagsProps {
  title?: string;
  description?: string;
  image?: string;
  url?: string;
  type?: 'website' | 'product' | 'article';
  schema?: Record<string, any>;
}

export const MetaTags: React.FC<MetaTagsProps> = ({
  title = "Olma Marketplace - Le meilleur de l'Algérie",
  description = "Découvrez nos artisans et vendeurs de confiance à travers les 58 wilayas d'Algérie.",
  image = "/assets/icon.png",
  url = typeof window !== 'undefined' ? window.location.href : "https://olma-dz.com",
  type = "website",
  schema
}) => {
  const { i18n } = useTranslation();
  const lang = (i18n.language || "fr").split("-")[0];

  return (
    <Helmet>
      <html lang={lang} dir={lang === 'ar' ? 'rtl' : 'ltr'} />
      <title>{title}</title>
      <meta name="description" content={description} />

      {/* Open Graph / Facebook */}
      <meta property="og:type" content={type} />
      <meta property="og:url" content={url} />
      <meta property="og:title" content={title} />
      <meta property="og:description" content={description} />
      <meta property="og:image" content={image} />

      {/* Twitter */}
      <meta property="twitter:card" content="summary_large_image" />
      <meta property="twitter:url" content={url} />
      <meta property="twitter:title" content={title} />
      <meta property="twitter:description" content={description} />
      <meta property="twitter:image" content={image} />

      {/* hreflang tags */}
      <link rel="alternate" hrefLang="fr" href={`${url}?lang=fr`} />
      <link rel="alternate" hrefLang="en" href={`${url}?lang=en`} />
      <link rel="alternate" hrefLang="ar" href={`${url}?lang=ar`} />
      <link rel="alternate" hrefLang="x-default" href={url} />

      {/* Schema.org JSON-LD */}
      {schema && (
        <script type="application/ld+json">
          {JSON.stringify(schema)}
        </script>
      )}
    </Helmet>
  );
};

import React from "react";
import { Home, Heart, ShoppingBag, User as UserIcon, LayoutGrid } from "lucide-react";
import { useTranslation } from "react-i18next";
import { useLocation, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { useCart } from "../context/CartContext";
import { useUI } from "../context/UIContext";

export const MobileBottomNav: React.FC<{ hideOnRoutes?: string[] }> = ({ hideOnRoutes = [] }) => {
  const { currentUser, userProfile } = useAuth();
  const { cart, wishlist } = useCart();
  const { setIsCartOpen, setIsWishlistOpen } = useUI();
  const { t } = useTranslation();
  const location = useLocation();
  const navigate = useNavigate();

  const isHidden = hideOnRoutes.some(route => location.pathname === route || location.pathname.startsWith(route + "/"));
  if (isHidden) {
    return null;
  }

  const isActive = (path: string) => location.pathname === path;

  return (
    <div
      className="md:hidden fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-2xl border-t border-slate-100 z-50 shadow-[0_-8px_32px_rgba(0,0,0,0.04)] overflow-hidden"
      style={{ paddingBottom: "env(safe-area-inset-bottom)" }}
    >
      <div className="flex items-center justify-around h-[4.5rem] w-full px-2">
        {/* Home */}
        <button
          onClick={() => navigate("/")}
          className="flex flex-col items-center justify-center w-14 h-14 rounded-2xl active:scale-[0.92] transition-all bg-transparent border-none cursor-pointer relative"
        >
          {isActive("/") && <div className="absolute inset-0 bg-sky-50 rounded-2xl -z-10" />}
          <Home
            className={`w-6 h-6 transition-colors ${isActive("/") ? "text-sky-500" : "text-slate-500"}`}
            strokeWidth={isActive("/") ? 2.5 : 2}
          />
        </button>

        {/* Categories */}
        <button
          onClick={() => navigate("/categories")}
          className="flex flex-col items-center justify-center w-14 h-14 rounded-2xl active:scale-[0.92] transition-all bg-transparent border-none cursor-pointer relative"
        >
          {isActive("/categories") && <div className="absolute inset-0 bg-sky-50 rounded-2xl -z-10" />}
          <LayoutGrid
            className={`w-6 h-6 transition-colors ${isActive("/categories") ? "text-sky-500" : "text-slate-500"}`}
            strokeWidth={isActive("/categories") ? 2.5 : 2}
          />
        </button>

        {/* Wishlist */}
        <button
          onClick={() => setIsWishlistOpen(true)}
          className="flex flex-col items-center justify-center w-14 h-14 rounded-2xl active:scale-[0.92] transition-all relative bg-transparent border-none cursor-pointer"
        >
          <Heart
            className={`w-6 h-6 transition-colors ${wishlist.length > 0 ? "text-pink-500 fill-pink-500/20" : "text-slate-500"}`}
            strokeWidth={wishlist.length > 0 ? 2.5 : 2}
          />
          {wishlist.length > 0 && (
            <span className="absolute top-2 right-3 w-2 h-2 bg-pink-500 border-2 border-white rounded-full shadow-sm" />
          )}
        </button>

        {/* Cart */}
        <button
          onClick={() => setIsCartOpen(true)}
          className="flex flex-col items-center justify-center w-14 h-14 rounded-2xl active:scale-[0.92] transition-all relative bg-transparent border-none cursor-pointer"
        >
          <div className="relative">
            <ShoppingBag
              className={`w-6 h-6 transition-colors ${cart.length > 0 ? "text-sky-500" : "text-slate-500"}`}
              strokeWidth={cart.length > 0 ? 2.5 : 2}
            />
            {cart.length > 0 && (
              <span className="absolute -top-1.5 -right-2 w-4.5 h-4.5 bg-zinc-900 text-white text-[9px] rounded-full flex items-center justify-center font-bold border-[1.5px] border-white shadow-sm">
                {cart.length}
              </span>
            )}
          </div>
        </button>

        {/* Account / Dashboard */}
        <button
          onClick={() => {
            if (!currentUser) {
              navigate("/auth", { replace: true });
              return;
            }
            if (userProfile?.role === "admin") {
              navigate("/dashboard/admin");
            } else if (userProfile?.role === "seller") {
              navigate("/dashboard/seller");
            } else {
              navigate("/dashboard/buyer");
            }
          }}
          className="flex flex-col items-center justify-center w-14 h-14 rounded-2xl active:scale-[0.92] transition-all bg-transparent border-none cursor-pointer relative"
        >
          {location.pathname.startsWith("/dashboard") && (
            <div className="absolute inset-0 bg-sky-50 rounded-2xl -z-10" />
          )}
          <UserIcon
            className={`w-6 h-6 transition-colors ${location.pathname.startsWith("/dashboard") ? "text-sky-500" : "text-slate-500"}`}
            strokeWidth={location.pathname.startsWith("/dashboard") ? 2.5 : 2}
          />
        </button>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from "react";
import { motion, AnimatePresence } from "motion/react";
import { ChevronRight, LayoutGrid, ArrowRight, Sparkles, Zap } from "lucide-react";
import { useTranslation } from "react-i18next";
import { useNavigate } from "react-router-dom";
import { useShop } from "../context/ShopContext";
import { PRODUCT_HIERARCHY, CATEGORY_ICONS } from "../constants";
import { Language } from "../domains/home/homepage.types";
import { apiGet } from "../lib/api";
import { getCategoryTranslation } from "../utils/translations";
import { getOptimizedImageUrl, getFallbackSubImage } from "../utils/imageUtils";

interface CategoryData {
  id: string;
  name: string;
  icon?: React.ComponentType<{ className?: string }>;
  banner?: string;
  colorTheme?: string;
  subs: { name: string; image: string; subSubs: { name: string; image: string | null }[] }[];
}

export default function MobileCategories(): React.ReactElement {
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();
  const { setActiveCategory, setSearchQuery } = useShop();
  const { categoryHierarchy } = useShop();
  const lang = (i18n.language || "fr") as Language;

  const [activeExpanded, setActiveExpanded] = useState<string | null>("Maison & Déco");
  const [activeExpandedSub, setActiveExpandedSub] = useState<string | null>(null);
  const [customConfigs, setCustomConfigs] = useState<any[]>([]);

  const isRTL = lang === "ar";

  useEffect(() => {
    let cancelled = false;
    const fetchConfigs = async () => {
      try {
        const data = await apiGet<{ categories: any[] }>("/api/v1/settings/homepage-categories");
        if (!cancelled && data && data.categories) {
          setCustomConfigs(data.categories);
          sessionStorage.setItem("home_custom_categories", JSON.stringify(data.categories));
        }
      } catch (err) {
        if (!cancelled) {
          console.warn("Error loading configs:", err);
        }
      }
    };
    fetchConfigs();
    return () => {
      cancelled = true;
    };
  }, []);

  const categoriesData: CategoryData[] = useMemo(() => {
    return Object.entries(categoryHierarchy).map(([catName, subGroups]) => {
      const customConfig = customConfigs?.find((cc: any) => cc.id === catName);
      // More reliable Unsplash photo IDs that are typically stable
      const ABSTRACT_IDS = [
        "1557672172-298e090bd0f1",
        "1518640467708-62f1f5164f7b",
        "1528459801415-3cb8a5a415ed",
        "1550850839925-58f5bc68f006",
        "1615529851608-f404af362483",
        "1541701494587-cb58502866ab",
        "1498049794561-7780e7231661",
        "1583847268964-b28dc8f51f92",
        "1445205170230-053b83016050",
        "1522335789203-aabd1fc54bc9",
        "1492144534655-ae79c964c9d7",
        "1517836357463-d25dfeac3438",
        "1519689689353-897c1bd303b5",
        "1581244276891-997d6273424a",
        "1533038590840-349c81a285d8",
        "1542838132-92c53300491e",
        "1456513080510-7bf3a84b82f8",
      ];
      const CATEGORY_IMAGES_MAP: Record<string, string> = {
        "Maison & Déco": "/images/placeholders/product.svg",
        Électronique: "/images/placeholders/product.svg",
        Électroménager: "/images/placeholders/product.svg",
        Mode: "/images/placeholders/product.svg",
        "Beauté & Santé": "/images/placeholders/product.svg",
        "Auto & Moto": "/images/placeholders/product.svg",
        "Sport & Loisirs": "/images/placeholders/product.svg",
        "Bébé & Puériculture": "/images/placeholders/product.svg",
        "Bricolage & Outillage": "/images/placeholders/product.svg",
        "Jeux & Jouets": "/images/placeholders/product.svg",
        Supermarché: "/images/placeholders/product.svg",
        "Scolaire & Bureau": "/images/placeholders/product.svg",
      };

      const allSubs: { name: string; image: string; subSubs: { name: string; image: string | null }[] }[] = [];
      Object.entries(subGroups).forEach(([subName, subSubsArray]) => {
        const subCategoryImages = customConfig?.subCategoryImages || {};

        // Case-insensitive lookup helper for custom subCategory images
        const findImageInConfig = (key: string) => {
          if (!key) return null;
          const normalizedKey = key.trim().toLowerCase();
          for (const [k, v] of Object.entries(subCategoryImages)) {
            if (k.trim().toLowerCase() === normalizedKey && typeof v === "string" && v) {
              return v;
            }
          }
          return null;
        };

        // Resolve parent subcategory image
        let customSubImage = findImageInConfig(subName);
        if (!customSubImage) {
          // Fallback: use first child's image if parent does not have one
          for (const ss of subSubsArray) {
            customSubImage = findImageInConfig(ss);
            if (customSubImage) break;
          }
        }
        if (!customSubImage) {
          customSubImage = getFallbackSubImage(subName);
        }

        // Resolve child sub-subcategory images
        const mappedSubSubs = subSubsArray.map((ss) => {
          let customImg = findImageInConfig(ss);
          if (!customImg) {
            // Fallback: use parent subcategory's image
            customImg = findImageInConfig(subName);
          }
          if (!customImg) {
            customImg = getFallbackSubImage(ss);
          }
          return {
            name: ss,
            image: customImg,
          };
        });

        allSubs.push({ name: subName, image: customSubImage, subSubs: mappedSubSubs });
      });

      const fallbackBannerId =
        CATEGORY_IMAGES_MAP[catName] ||
        `/images/placeholders/category.svg`;

      return {
        id: catName,
        name: catName,
        icon: CATEGORY_ICONS[catName],
        banner: customConfig?.image || `${fallbackBannerId}`,
        colorTheme: customConfig?.color_theme || "#ea580c",
        subs: allSubs,
      };
    });
  }, [customConfigs]);

  const selectSubCategoryAndNavigate = (catId: string, subName: string) => {
    setActiveCategory(catId);
    setSearchQuery(subName);
    const isElectromenager = catId?.toLowerCase() === "electromenager" || catId?.toLowerCase() === "électroménager";
    if (isElectromenager) {
      navigate("/univers/electromenager");
    } else {
      navigate("/shop");
    }
  };

  const handleToggle = (catId: string) => {
    if (activeExpanded === catId) {
      setActiveExpanded(null);
    } else {
      setActiveExpanded(catId);
      setActiveExpandedSub(null);
    }
  };

  const handleSubToggle = (subName: string, event: React.MouseEvent) => {
    event.stopPropagation();
    if (activeExpandedSub === subName) {
      setActiveExpandedSub(null);
    } else {
      setActiveExpandedSub(subName);
    }
  };

  return (
    <div className="min-h-screen bg-transparent pb-32 overflow-x-hidden pt-4" dir={isRTL ? "rtl" : "ltr"}>
      <div className="max-w-xl mx-auto px-5">
        {/* Superior Header: Abstract & Minimalist */}
        <header className="mb-10 flex flex-col items-start gap-1">
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            className="flex items-center gap-2 text-orange-600 mb-1"
          >
            <Sparkles className="w-4 h-4 fill-current" />
            <span className="text-[10px] font-sans font-bold uppercase tracking-[0.25em]">
              {t("exploration_premium") || "Exploration Premium"}
            </span>
          </motion.div>
          <h1 className="text-4xl font-sans font-bold text-slate-900 tracking-tighter rtl:tracking-normal uppercase leading-none">
            {t("univers_olma")?.split(" ")[0] || "Univers"}{" "}
            <span className="text-slate-500">{t("univers_olma")?.split(" ")[1] || "Olma"}</span>
          </h1>
          <p className="text-[11px] font-bold text-zinc-400 uppercase tracking-widest rtl:tracking-normal mt-2 max-w-[200px] leading-relaxed">
            {t("browse_collections_desc") || "Parcourez nos collections par atmosphère et style de vie."}
          </p>
        </header>

        {/* Categories Stack: The Portal Architecture */}
        <div className="space-y-4">
          {categoriesData.map((cat, idx) => {
            const isExpanded = activeExpanded === cat.id;

            return (
              <div
                key={cat.id}
                className={`relative transition-all duration-500 ease-[cubic-bezier(0.23,1,0.32,1)] ${isExpanded ? "mb-8" : "mb-0"}`}
              >
                {/* Main Category Entry Card */}
                <motion.button
                  layout
                  onClick={() => handleToggle(cat.id)}
                  className={`w-full relative h-40 sm:h-48 rounded-[32px] overflow-hidden group border-none cursor-pointer transition-all duration-500 ${isExpanded ? "ring-2 ring-slate-900 ring-offset-2 ring-offset-slate-50" : "hover:shadow-xl shadow-lg shadow-slate-900/5"}`}
                >
                  <motion.img
                    layout
                    src={cat.banner}
                    className={`absolute inset-0 w-full h-full object-cover transition-transform duration-1000 ${isExpanded ? "scale-110 blur-[2px]" : "group-hover:scale-105"}`}
                    alt={cat.name}
                    onError={(e) => {
                      (e.target as HTMLImageElement).src =
                        `/images/placeholders/product.svg`;
                    }}
                  />
                  <div
                    className={`absolute inset-0 transition-opacity duration-500 ${isExpanded ? "bg-slate-900/75" : "bg-gradient-to-t from-slate-900/85 via-transparent to-transparent"}`}
                  />

                  <div className="absolute inset-x-0 bottom-0 p-6 flex items-end justify-between">
                    <div className="flex flex-col items-start gap-1">
                      <div
                        className={`flex items-center gap-2 transition-transform duration-500 ${isExpanded ? "translate-y-[-10px]" : ""}`}
                      >
                        <div className="w-8 h-8 rounded-xl bg-white/35 flex items-center justify-center text-white border border-white/45">
                          {cat.icon ? (
                            React.createElement(cat.icon as any, { className: "w-4 h-4" })
                          ) : (
                            <LayoutGrid className="w-4 h-4" />
                          )}
                        </div>
                        <span className="text-[10px] font-bold text-orange-400 uppercase tracking-wider rtl:tracking-normal drop-shadow-sm">
                          {t("atmosphere") || "Atmosphère"}
                        </span>
                      </div>
                      <h2
                        className={`text-2xl font-bold text-white leading-none tracking-tight rtl:tracking-normal uppercase transition-transform duration-500 ${isExpanded ? "translate-y-[-10px]" : ""}`}
                      >
                        {getCategoryTranslation(cat.name, t)}
                      </h2>
                    </div>
                    <div
                      className={`w-10 h-10 rounded-full flex shrink-0 items-center justify-center shadow-xl transition-all duration-500 ${isExpanded ? "rotate-90 scale-110 bg-slate-900 text-white" : "bg-white/35 text-white border border-white/45 rtl:rotate-180"}`}
                    >
                      <ArrowRight className="w-5 h-5" />
                    </div>
                  </div>
                </motion.button>

                {/* Sub-categories Grid: Bento Reveal */}
                <AnimatePresence>
                  {isExpanded && (
                    <motion.div
                      initial={{ opacity: 0, height: 0, marginTop: 0 }}
                      animate={{ opacity: 1, height: "auto", marginTop: 24 }}
                      exit={{ opacity: 0, height: 0, marginTop: 0 }}
                      transition={{ duration: 0.4, ease: [0.23, 1, 0.32, 1] }}
                      className="overflow-hidden"
                    >
                      <div className="grid grid-cols-2 gap-3">
                        {cat.subs.map((sub, sIdx) => {
                          const isSelectedSub = activeExpandedSub === sub.name;
                          const isWide = sIdx % 5 === 0 || isSelectedSub;
                          return (
                            <motion.div
                              key={sub.name}
                              initial={{ opacity: 0, scale: 0.9, y: 10 }}
                              animate={{ opacity: 1, scale: 1, y: 0 }}
                              transition={{ delay: sIdx * 0.03 + 0.1 }}
                              className={`relative overflow-hidden rounded-3xl group bg-white ${isWide ? "col-span-2" : "col-span-1"} ${isSelectedSub ? "h-auto shadow-md border border-slate-200" : isWide ? "h-32" : "h-36"} flex flex-col transition-all duration-300`}
                            >
                              {!isSelectedSub ? (
                                <button
                                  onClick={(e) => handleSubToggle(sub.name, e)}
                                  className="w-full h-full text-left p-0 border-none bg-transparent cursor-pointer flex flex-col relative"
                                >
                                  {isWide ? (
                                    <div className="w-full h-full flex flex-row items-center p-4 gap-4 relative overflow-hidden">
                                      <div className="absolute top-0 end-0 w-32 h-32 bg-orange-500/5 rounded-full -me-16 -mt-16 blur-3xl" />
                                      <div className="w-16 h-16 md:w-24 md:h-24 rounded-2xl overflow-hidden shrink-0 shadow-lg border-2 border-white/50 relative z-10 block">
                                        <img
                                          src={getOptimizedImageUrl(sub.image || undefined, 400)}
                                          className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700"
                                          alt={sub.name}
                                        />
                                      </div>
                                      <div className="flex flex-col items-start gap-1 relative z-10 w-full min-w-0">
                                        <span className="text-[10px] font-sans font-bold text-orange-500 uppercase tracking-widest rtl:tracking-normal">
                                          {t("view_collection") || "Voir la collection"}
                                        </span>
                                        <h3 className="text-base sm:text-lg font-sans font-bold text-slate-900 uppercase tracking-tighter rtl:tracking-normal leading-tight truncate w-full">
                                          {getCategoryTranslation(sub.name, t)}
                                        </h3>
                                        <div className="flex flex-wrap gap-1 mt-1 w-full">
                                          {sub.subSubs.slice(0, 3).map((ss) => (
                                            <span
                                              key={ss.name}
                                              className="px-2 py-0.5 text-[8px] font-bold bg-slate-100 text-slate-900 rounded-full whitespace-nowrap"
                                            >
                                              {getCategoryTranslation(ss.name, t)}
                                            </span>
                                          ))}
                                          {sub.subSubs.length > 3 && (
                                            <span className="px-2 py-0.5 text-[8px] font-bold bg-slate-100 text-slate-900 rounded-full">
                                              +{sub.subSubs.length - 3}
                                            </span>
                                          )}
                                        </div>
                                        <div className="mt-1 w-7 h-1 bg-slate-900 rounded-full group-hover:w-full transition-all duration-500" />
                                      </div>
                                    </div>
                                  ) : (
                                    <>
                                      <div className="w-full h-[60%] overflow-hidden flex-1 relative">
                                        <img

                                          src={getOptimizedImageUrl(sub.image || undefined, 400)}
                                          className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700"
                                          alt={sub.name}
                                        />
                                        <div className="absolute inset-0 bg-gradient-to-t from-zinc-900/60 to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex items-end p-2 pb-3 justify-center">
                                          <div className="flex flex-wrap gap-1 justify-center translate-y-4 group-hover:translate-y-0 transition-transform duration-500">
                                            {sub.subSubs.slice(0, 2).map((ss) => (
                                              <span
                                                key={ss.name}
                                                className="px-1.5 py-0.5 text-[7px] font-bold bg-black/60 text-white rounded-md whitespace-nowrap border border-white/5"
                                              >
                                                {ss.name}
                                              </span>
                                            ))}
                                          </div>
                                        </div>
                                      </div>
                                      <div className="p-3 bg-white flex flex-col items-center justify-center flex-1">
                                        <span className="text-[10px] font-bold text-slate-900 uppercase tracking-wide text-center leading-tight line-clamp-2">
                                          {getCategoryTranslation(sub.name, t)}
                                        </span>
                                        <span className="text-[8px] font-semibold text-stone-500 mt-1 uppercase tracking-wider rtl:tracking-normal">
                                          {sub.subSubs.length} {t("departments") || "rayons"}
                                        </span>
                                      </div>
                                    </>
                                  )}
                                </button>
                              ) : (
                                <div className="flex flex-col w-full h-full">
                                  <button
                                    onClick={(e) => handleSubToggle(sub.name, e)}
                                    className="w-full flex items-center p-5 bg-slate-900 text-white shrink-0 border-none text-left cursor-pointer active:bg-[#0a0b0c] transition-colors relative overflow-hidden"
                                  >
                                    <div className="absolute top-0 end-0 w-32 h-32 bg-white/5 rounded-full -me-10 -mt-10 blur-2xl" />
                                    <div className="flex-1 flex flex-col relative z-10">
                                      <span className="text-[10px] text-orange-400 font-sans font-bold uppercase tracking-widest rtl:tracking-normal mb-1">
