import React, { useState, useEffect, useRef, useMemo } from "react";
import { motion, AnimatePresence } from "motion/react";
import { Bell, MessageSquare, Truck, Check, ShieldCheck, Ticket, AlertCircle } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { apiGet, apiPost } from "../lib/api";
import toast from "react-hot-toast";
import { formatPrice } from "../utils/format";
import { useTranslation } from "react-i18next";

interface NotificationItem {
  id: string;
  title: string;
  description: string;
  time: string;
  createdAt: number;
  type:
    | "message"
    | "status_shipped"
    | "status_delivered"
    | "support"
    | "coupon"
    | "system"
    | "new_order"
    | "dispute"
    | "withdrawal";
  link: string;
  read: boolean;
}

const parseTimestamp = (val: any): number => {
  if (!val) return Date.now();
  if (typeof val === "number") return val;
  if (typeof val === "string") return Date.parse(val) || Date.now();
  if (val && typeof val === "object") {
    if (val.seconds) return val.seconds * 1000;
    if (val._seconds) return val._seconds * 1000;
  }
  return Date.now();
};

export const NotificationCenter: React.FC = () => {
  const { currentUser, userProfile } = useAuth();
  const navigate = useNavigate();
  const { i18n, t } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);
  const [orderNotifications, setOrderNotifications] = useState<NotificationItem[]>([]);
  const [directNotifications, setDirectNotifications] = useState<NotificationItem[]>([]);
  const [globalCoupons, setGlobalCoupons] = useState<NotificationItem[]>([]);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const notifiedIdsRef = useRef<Set<string>>(new Set());
  const [permission, setPermission] = useState<NotificationPermission>(
    typeof window !== "undefined" && "Notification" in window ? Notification.permission : "default"
  );

  const requestPushPermission = () => {
    if (typeof window !== "undefined" && "Notification" in window) {
      Notification.requestPermission().then((perm) => {
        setPermission(perm);
        if (perm === "granted") {
          toast.success("Notifications activées ! 🔔");
          try {
            new Notification("Notifications activées", {
              body: "Vous recevrez des alertes en temps réel sur Olmart.",
              icon: "/icon.png",
            });
          } catch (e) {
            console.warn("Could not fire test notification", e);
          }
        }
      });
    }
  };

  // Parse active language
  const lang = (i18n.language || "fr").substring(0, 2) as "fr" | "en" | "ar";

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const fetchNotifications = async (isFirstLoad = false) => {
    if (!currentUser) return;
    try {
      const response = await apiGet<{
        orders: any[];
        direct: any[];
        coupons: any[];
      }>("/api/v1/auth/notifications");

      if (!response) return;

      // 1. Process orders
      const newOrdersNotif: NotificationItem[] = [];
      (response.orders || []).forEach((order) => {
        const orderIdShort = order.id.substring(0, 8);
        const orderTimeMs = parseTimestamp(order.updatedAt);
        const orderTime = new Date(orderTimeMs).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });

        if (order.status === "shipped") {
          newOrdersNotif.push({
            id: `shipped-${order.id}`,
            title: t("notif.shipped_title") || `🚨 Ça arrive !`,
            description: `${t("notif.shipped_desc") || "L'artisan a remis votre colis au livreur. Préparez les "}${formatPrice(order.total || 0)}${t(" en espèces.")}`,
            time: orderTime,
            createdAt: orderTimeMs,
            type: "status_shipped",
            link: `/dashboard/buyer`,
            read: localStorage.getItem(`notif_read_shipped-${order.id}`) === "true",
          });
        } else if (order.status === "delivered") {
          newOrdersNotif.push({
            id: `delivered-${order.id}`,
            title: t("notif.delivered_title") || `📍 Le livreur est là !`,
            description: `${t("notif.delivered_desc") || "Gardez votre téléphone près de vous aujourd'hui pour réceptionner votre commande #"}${orderIdShort}.`,
            time: orderTime,
            createdAt: orderTimeMs,
            type: "status_delivered",
            link: `/dashboard/buyer`,
            read: localStorage.getItem(`notif_read_delivered-${order.id}`) === "true",
          });
        } else {
          newOrdersNotif.push({
            id: `pending-${order.id}`,
            title: `${t("notif.order_recorded") || "Commande #"} ${orderIdShort} ${t("notif.registered") || "Enregistrée"}`,
            description: t("notif.pending_desc") || `Le vendeur prépare votre colis en paiement CASH à la livraison.`,
            time: orderTime,
            createdAt: orderTimeMs,
            type: "system",
            link: `/dashboard/buyer`,
            read: localStorage.getItem(`notif_read_pending-${order.id}`) === "true",
          });
        }
      });

      // Also support custom static user notifications
      newOrdersNotif.push({
        id: "support-hub",
        title: t("notif.support_title") || "Messagerie Olma active 💬",
        description: t("notif.support_desc") || "Échangez directement avec les artisans depuis le suivi de commande.",
        time: t("notif.permanent") || "Permanent",
        createdAt: Date.now(),
        type: "message",
        link: "/dashboard/buyer",
        read: localStorage.getItem("notif_read_support-hub") === "true",
      });

      setOrderNotifications(newOrdersNotif);

      // 2. Process direct notifications
      const newDirectNotif: NotificationItem[] = (response.direct || []).map((data) => {
        const timeMs = parseTimestamp(data.createdAt);
        const timeStr = new Date(timeMs).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });

        const titleText = data.title ? data.title[lang] || data.title.fr || data.title : "Notification";
        const descText = data.message ? data.message[lang] || data.message.fr || data.message : "";

        let computedLink: string;
        if (userProfile?.role === "seller") {
          computedLink = "/dashboard/seller";
          if (data.type === "new_order" || data.type === "order") {
            computedLink = "/dashboard/seller/orders";
          } else if (data.type === "support" || data.type === "message") {
            computedLink = "/dashboard/seller/support";
          }
        } else {
          computedLink = "/dashboard/buyer";
        }

        const notifId = `user-notif-${data.id}`;

        // Direct Native push notification trigger for unread & unseen yet
        if (!isFirstLoad && !data.read && !notifiedIdsRef.current.has(notifId)) {
          if ("Notification" in window && Notification.permission === "granted") {
            try {
              new Notification(typeof titleText === "string" ? titleText : "Nouvelle alerte", {
                body: typeof descText === "string" ? descText : "Vous avez une nouvelle notification.",
                icon: "/icon.png",
                badge: "/icon.png",
              });
            } catch (err) {
              console.warn("Failed sending native push", err);
            }
          }
        }

        // Add to notified reference set
        notifiedIdsRef.current.add(notifId);

        return {
          id: notifId,
          title: titleText,
          description: descText,
          time: timeStr,
          createdAt: timeMs,
          type: data.type || "system",
          link: computedLink,
          read: data.read === true,
        };
      });

      setDirectNotifications(newDirectNotif);

      // 3. Process coupons
      const newCouponsNotif: NotificationItem[] = (response.coupons || []).map((data) => {
        const timeMs = parseTimestamp(data.createdAt);
        const timeStr = new Date(timeMs).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });

        let discountDisplay: string;
        if (data.discountType === "percentage") {
          discountDisplay = `${data.discountValue}%`;
        } else {
          discountDisplay = `${data.discountValue} DA`;
        }

        return {
          id: `global-coupon-${data.id}`,
          title: t("notification.new_coupon_title", "🎁 Nouveau Code Promo : {{code}}", { code: data.code }),
          description: t(
            "notification.new_coupon_desc",
            "Profitez de {{discount}} de réduction ! (Min. {{min}} DA)",
            { discount: discountDisplay, min: data.minOrderValue || 0 }
          ),
          time: timeStr,
          createdAt: timeMs,
          type: "coupon",
          link: "/shop",
          read: localStorage.getItem(`notif_read_global-coupon-${data.id}`) === "true",
        };
      });

      setGlobalCoupons(newCouponsNotif);

    } catch (err) {
      console.error("Error fetching notifications via apiGet:", err);
    }
  };

  // Sync / Fetch live firebase events
  useEffect(() => {
    if (!currentUser) {
      // Offline fallback notifications (e.g., campaign info, platform system messages)
      setOrderNotifications([
        {
          id: "welcome-off",
          title: t("notif.welcome_title") || "Bienvenue sur Olma 🇩🇿",
          description:
            t("notif.welcome_desc") || "La marketplace des créations de nos 58 Wilayas. Vos achats sont protégés.",
          time: t("A l'instant"),
          createdAt: Date.now(),
          type: "system",
          link: "/shop",
          read: false,
        },
        {
          id: "promo-off",
          title: t("notif.promo_title") || "Livraison Offerte",
          description: t("notif.promo_desc") || "Profitez de réductions exclusives de la part des vendeurs !",
          time: t("notif.two_hours_ago") || "Il y a 2h",
          createdAt: Date.now() - 7200000,
          type: "coupon",
          link: "/shop",
          read: false,
        },
      ]);
      setDirectNotifications([]);
      return;
    }

    // Initial load
    fetchNotifications(true);

    // Set up a polling interval for background updates every 60 seconds
    const interval = setInterval(() => {
      fetchNotifications(false);
    }, 60000);

    return () => {
      clearInterval(interval);
    };
  }, [currentUser, lang, userProfile?.role, t]);

  // Combined notifications memo sorted chronologically
  const notifications = useMemo(() => {
    const all = [...directNotifications, ...orderNotifications, ...globalCoupons];
    all.sort((a, b) => b.createdAt - a.createdAt);
    return all.slice(0, 50);
  }, [orderNotifications, directNotifications, globalCoupons]);

  const unreadCount = useMemo(() => {
    return notifications.filter((n) => !n.read).length;
  }, [notifications]);

  const markAllAsRead = async () => {
    // 1. Local storage read state for order updates and global coupons
    orderNotifications.forEach((n) => {
      localStorage.setItem(`notif_read_${n.id}`, "true");
    });
    globalCoupons.forEach((n) => {
      localStorage.setItem(`notif_read_${n.id}`, "true");
    });
    setOrderNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
    setGlobalCoupons((prev) => prev.map((n) => ({ ...n, read: true })));

    // 2. Update all unread direct notifications in Firestore via API
    try {
      await apiPost("/api/v1/auth/notifications/read-all", {});
      setDirectNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
    } catch (err) {
      console.error("Could not update notification read-all state:", err);
    }
  };

  const markOneAsRead = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (id.startsWith("user-notif-")) {
      const docId = id.replace("user-notif-", "");
      try {
        await apiPost(`/api/v1/auth/notifications/${docId}/read`, {});
        setDirectNotifications((prev) => prev.map((n) => (n.id === id ? { ...n, read: true } : n)));
      } catch (err) {
        console.error("Could not mark direct notification as read:", err);
      }
    } else {
      localStorage.setItem(`notif_read_${id}`, "true");
      setOrderNotifications((prev) => prev.map((n) => (n.id === id ? { ...n, read: true } : n)));
      setGlobalCoupons((prev) => prev.map((n) => (n.id === id ? { ...n, read: true } : n)));
    }
  };

  const handleNotificationClick = async (item: NotificationItem) => {
    setIsOpen(false);
    if (item.id.startsWith("user-notif-")) {
      const docId = item.id.replace("user-notif-", "");
      try {
        await apiPost(`/api/v1/auth/notifications/${docId}/read`, {});
        setDirectNotifications((prev) => prev.map((n) => (n.id === item.id ? { ...n, read: true } : n)));
      } catch (err) {
        console.error("Could not mark clicked notification as read:", err);
      }
    } else {
      localStorage.setItem(`notif_read_${item.id}`, "true");
      setOrderNotifications((prev) => prev.map((n) => (n.id === item.id ? { ...n, read: true } : n)));
      setGlobalCoupons((prev) => prev.map((n) => (n.id === item.id ? { ...n, read: true } : n)));
    }
    navigate(item.link);
  };

  const toggleOpen = () => {
    if (!isOpen) {
      fetchNotifications(false);
    }
    setIsOpen(!isOpen);
  };

  const getIcon = (type: string) => {
    switch (type) {
      case "message":
        return <MessageSquare className="w-4 h-4 text-orange-600" />;
      case "status_shipped":
        return <Truck className="w-4 h-4 text-amber-600" />;
      case "status_delivered":
        return <ShieldCheck className="w-4 h-4 text-emerald-600" />;
      case "coupon":
        return <Ticket className="w-4 h-4 text-purple-600" />;
      case "new_order":
        return <Truck className="w-4 h-4 text-blue-600" />;
      case "dispute":
        return <AlertCircle className="w-4 h-4 text-red-600" />;
      default:
        return <Bell className="w-4 h-4 text-[var(--color-slate-900, #0f172a)]" />;
    }
  };

  return (
    <div className="relative shrink-0" ref={dropdownRef}>
      <motion.button
        onClick={toggleOpen}
        className="w-9 h-9 sm:w-10 sm:h-10 rounded-full items-center justify-center bg-white/50 text-[var(--color-slate-900, #0f172a)] border border-[var(--color-orange-600, #ea580c)]/50 hover:bg-white transition-all active:scale-95 cursor-pointer relative flex group"
        whileHover={{ scale: 1.05 }}
        whileTap={{ scale: 0.95 }}
        title={t("Notifications") || "Notifications"}
      >
        <Bell className="w-5 h-5 stroke-[2] text-[var(--color-slate-900, #0f172a)]/70 group-hover:text-[var(--color-slate-900, #0f172a)]" />
        <AnimatePresence>
          {unreadCount > 0 && (
            <motion.div
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              exit={{ scale: 0 }}
              className="absolute -top-1 -right-1 w-4 h-4 shrink-0"
            >
              <span className="absolute inline-flex w-full h-full rounded-full bg-[var(--color-orange-600, #ea580c)] opacity-75 animate-ping" />
              <span className="relative flex bg-[var(--color-orange-600, #ea580c)] text-white text-[9px] rtl:text-[11px] font-sans font-bold w-4 h-4 rounded-full items-center justify-center border border-[#FAF8F5] shadow-sm">
                {unreadCount}
              </span>
            </motion.div>
          )}
        </AnimatePresence>
      </motion.button>

      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 15, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 12, scale: 0.95 }}
            className="absolute end-0 mt-3 w-80 sm:w-96 bg-transparent/95 backdrop-blur-2xl border border-[var(--color-orange-600, #ea580c)] rounded-[2rem] shadow-2xl z-[100] overflow-hidden flex flex-col py-1"
          >
            <div className="px-6 py-4 border-b border-[var(--color-orange-600, #ea580c)]/50 flex items-center justify-between bg-transparent/60 shrink-0">
              <div>
                <h4 className="font-extrabold text-[var(--color-slate-900, #0f172a)] text-sm">{t("Notifications")}</h4>
                <p className="text-[9px] rtl:text-[11px] font-sans font-bold uppercase text-[var(--color-orange-600, #ea580c)] tracking-widest rtl:tracking-normal mt-0.5">
                  {t("Mélodieux & Direct")}
                </p>
              </div>
              {unreadCount > 0 && (
                <button
                  onClick={markAllAsRead}
                  className="text-[9px] rtl:text-[11px] font-sans font-bold uppercase tracking-wider rtl:tracking-normal text-[var(--color-slate-900, #0f172a)] hover:text-[var(--color-orange-600, #ea580c)] bg-white border border-[var(--color-orange-600, #ea580c)] px-3 py-1.5 rounded-lg transition-all cursor-pointer"
                >
                  {t("Tout lire (")}
                  {unreadCount})
                </button>
              )}
            </div>

            {permission === "default" && (
              <div className="px-6 py-3 bg-[var(--color-orange-600,#ea580c)]/10 border-b border-[var(--color-orange-600,#ea580c)]/20 flex items-center justify-between gap-4 shrink-0">
                <span className="text-[10px] sm:text-[11px] font-medium text-slate-700">
                  {t("notif.enable_desk", "Activer les notifications de bureau en temps réel.")}
                </span>
                <button
                  onClick={requestPushPermission}
                  className="bg-[var(--color-orange-600,#ea580c)] text-white px-3 py-1.5 rounded-lg text-[9px] font-sans font-bold uppercase tracking-wider whitespace-nowrap cursor-pointer hover:bg-[var(--color-orange-600,#ea580c)]/90"
                >
                  {t("notif.enable", "Activer")}
                </button>
              </div>
            )}

            <div className="max-h-[360px] overflow-y-auto divide-y divide-[#EBE5DF]/30">
              {notifications.length === 0 ? (
                <div className="p-8 text-center space-y-4">
                  <div className="w-12 h-12 bg-white/50 border border-[var(--color-orange-600, #ea580c)] rounded-full flex items-center justify-center mx-auto text-stone-400">
                    <Bell className="w-5 h-5" />
                  </div>
                  <p className="text-[10px] rtl:text-[12px] font-sans font-bold uppercase tracking-wider rtl:tracking-normal text-[var(--color-slate-900, #0f172a)]/60">
                    {t("Aucune alerte")}
                  </p>
                </div>
              ) : (
                notifications.map((item) => {
                  return (
                    <div
                      key={item.id}
                      onClick={() => handleNotificationClick(item)}
                      className={`flex gap-3.5 p-4 text-start transition-colors cursor-pointer select-none relative ${item.read ? "bg-transparent hover:bg-transparent/35" : "bg-[var(--color-orange-600, #ea580c)]/5 hover:bg-[var(--color-orange-600, #ea580c)]/8"}`}
                    >
                      <div className="w-9 h-9 rounded-xl bg-white border border-[var(--color-orange-600, #ea580c)]/40 flex items-center justify-center shrink-0 shadow-xs">
                        {getIcon(item.type)}
                      </div>

                      <div className="flex-1 min-w-0 space-y-1">
                        <div className="flex items-start justify-between gap-2">
                          <p
                            className={`text-xs rtl:text-sm tracking-tight rtl:tracking-normal truncate leading-tight ${item.read ? "text-[var(--color-slate-900, #0f172a)] font-bold" : "text-[var(--color-slate-900, #0f172a)] font-extrabold"}`}
                          >
                            {item.title}
                          </p>
                          <span className="text-[8px] font-sans font-bold uppercase tracking-wider rtl:tracking-normal text-stone-400 shrink-0 mt-0.5">
                            {item.time}
                          </span>
                        </div>
                        <p className="text-[11px] leading-relaxed text-stone-600 font-medium">{item.description}</p>
                      </div>

                      <div className="flex flex-col items-center justify-center shrink-0">
                        {!item.read ? (
                          <button
                            onClick={(e) => markOneAsRead(item.id, e)}
                            className="w-5 h-5 rounded-full hover:bg-[var(--color-orange-600, #ea580c)]/20 flex items-center justify-center transition-all bg-[var(--color-orange-600, #ea580c)]/10 shrink-0 cursor-pointer"
                            title={t("Marquer comme lu") || "Marquer comme lu"}
                          >
                            <Check className="w-3 h-3 text-[var(--color-orange-600, #ea580c)]" />
                          </button>
                        ) : (
                          <span className="w-1.5 h-1.5 bg-stone-300 rounded-full shrink-0" />
                        )}
                      </div>
                    </div>
                  );
                })
              )}
            </div>

            <div className="p-3.5 border-t border-[var(--color-orange-600, #ea580c)]/50 bg-transparent/60 text-center shrink-0">
              <button
                onClick={() => {
                  setIsOpen(false);
                  navigate(
                    currentUser ? (userProfile?.role === "seller" ? "/dashboard/seller" : "/dashboard/buyer") : "/auth"
                  );
                }}
                className="text-[9px] rtl:text-[11px] font-sans font-bold uppercase tracking-widest rtl:tracking-normal text-[var(--color-slate-900, #0f172a)]/80 hover:text-[var(--color-slate-900, #0f172a)] block w-full text-center py-2 cursor-pointer"
              >
                {t("navbar.seller_dashboard") || "Accéder au Tableau de Bord"}
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

import React, { useEffect, useState, useRef } from "react";
import { auth, storage } from "../lib/firebase";
import { apiGet, apiPost } from "../lib/api";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";
import { motion, AnimatePresence } from "motion/react";
import { 
  Send, 
  AlertTriangle, 
  CheckCheck, 
  ShieldCheck, 
  Clock, 
  Store, 
  User, 
  Info, 
  Copy, 
  Check, 
  MessageSquare,
  Sparkles,
  Paperclip,
  Flag,
  Loader2,
  AlertCircle
} from "lucide-react";
import { useAuth } from "../context/AuthContext";
import { useTranslation } from "react-i18next";
import { maskSensitiveData, hasExternalChannel } from "../utils/masking";
import { toast } from "react-hot-toast";

interface Message {
  id: string;
  senderId: string;
  senderRole?: "buyer" | "seller" | "admin";
  text: string;
  imageUrl?: string;
  createdAt: any;
  isLog?: boolean;
  flagged?: boolean;
  flaggedReason?: string;
}

interface OrderLog {
  id: string;
  status: string;
  type: string;
  date: any;
  isLog: boolean;
}

export const OrderChatBox: React.FC<{ orderId: string; buyerId: string }> = ({ orderId, buyerId }) => {
  const { t, i18n } = useTranslation();
  const { currentUser } = useAuth();
  const [messages, setMessages] = useState<Message[]>([]);
  const [logs, setLogs] = useState<OrderLog[]>([]);
  const [newMessage, setNewMessage] = useState("");
  const [error, setError] = useState("");
  const [buyerName, setBuyerName] = useState("");
  const [shopName, setShopName] = useState("");
  const [copied, setCopied] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [reportingMessageId, setReportingMessageId] = useState<string | null>(null);
  const [reportReason, setReportReason] = useState("");

  const isRtl = i18n.language === "ar";
  const isBuyer = currentUser?.uid === buyerId;

  // Poll for chat updates
  useEffect(() => {
    if (!orderId) return;
    let isCancelled = false;

    const fetchChat = async () => {
      try {
        const data = await apiGet<any>(`/api/v1/orders/${orderId}/chat`);
        if (isCancelled) return;
        setBuyerName(data.buyerName || t("Acheteur Olmart"));
        setShopName(data.shopName || t("Boutique Olmart"));

        const prevMsgCount = messages.length;
        setMessages(data.messages || []);
        setLogs(data.logs || []);

        if (data.messages?.length > prevMsgCount) {
          setTimeout(() => {
            if (scrollRef.current) {
              scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
            }
          }, 100);
        }
      } catch (err) {
        if (!isCancelled) console.error("Error fetching chat:", err);
      }
    };

    fetchChat();
    const interval = setInterval(fetchChat, 5000);
    return () => {
      isCancelled = true;
      clearInterval(interval);
    };
  }, [orderId, messages.length, t]);

  // Merge messages and logs in chronological order for a unified timeline
  const timelineItems = React.useMemo(() => {
    const combined = [
      ...messages.map((m) => ({
        ...m,
        timestamp: m.createdAt?.toDate
          ? m.createdAt.toDate().getTime()
          : m.createdAt?.seconds
            ? m.createdAt.seconds * 1000
            : Date.now(),
        isLog: false,
      })),
      ...logs.map((l) => ({
        ...l,
        timestamp: l.date?.toDate
          ? l.date.toDate().getTime()
          : l.date?.seconds
            ? l.date.seconds * 1000
            : Date.now(),
        isLog: true,
      })),
    ];
    return combined.sort((a, b) => a.timestamp - b.timestamp);
  }, [messages, logs]);

  const handleCopyOrderId = () => {
    navigator.clipboard.writeText(orderId);
    setCopied(true);
    toast.success(t("ID Commande copié !"));
    setTimeout(() => setCopied(false), 2000);
  };

  const handleQuickReply = (text: string) => {
    setNewMessage(text);
    setError("");
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith("image/")) {
      setError(t("Veuillez sélectionner un fichier image valide."));
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      setError(t("L'image est trop volumineuse. Taille maximale : 5 Mo."));
      return;
    }

    try {
      setUploading(true);
      setError("");
      toast.loading(t("Téléchargement de l'image..."), { id: "chat-upload" });

      const fileRef = ref(storage, `chat_images/${orderId}/${Date.now()}_${file.name}`);
      const snapshot = await uploadBytes(fileRef, file);
      const downloadUrl = await getDownloadURL(snapshot.ref);

      // Send message with the image
      const idToken = await currentUser?.getIdToken();
      const res = await fetch("/api/v1/messages/send", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${idToken}`,
        },
        body: JSON.stringify({
          orderId,
          text: "",
          imageUrl: downloadUrl,
        }),
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error || "Failed to send image message");
      }

      toast.success(t("Image envoyée !"), { id: "chat-upload" });
    } catch (err: any) {
      console.error(err);
      setError(err.message || t("Erreur lors de l'envoi de l'image."));
      toast.error(t("Échec de l'envoi de l'image."), { id: "chat-upload" });
    } finally {
      setUploading(false);
    }
  };

  const handleReportMessage = async () => {
    if (!reportingMessageId) return;

    try {
      const idToken = await currentUser?.getIdToken();
      const res = await fetch("/api/v1/messages/report", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${idToken}`,
        },
        body: JSON.stringify({
          orderId,
          messageId: reportingMessageId,
          reason: reportReason.trim() || t("Signalé par l'utilisateur"),
        }),
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error || "Failed to report message");
      }

      toast.success(t("Le message a été signalé à l'équipe de modération."));
      setReportingMessageId(null);
      setReportReason("");
    } catch (err: any) {
      console.error(err);
      toast.error(err.message || t("Erreur lors du signalement du message."));
    }
  };

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");

    if (!currentUser || !newMessage.trim()) return;

    // 1. Sanitize text
    const rawText = newMessage.trim();
    const sanitizedText = rawText.replace(/<\/?[^>]+(>|$)/g, "").trim();

    if (!sanitizedText) {
      setError(t("Le message ne doit pas être vide ou contenir que du code HTML."));
      return;
    }

    if (sanitizedText.length > 1000) {
      setError(t("Le message est trop long. Maximum 1000 caractères."));
      return;
    }

    // 2. Strict DLP: Prevent external communication channels
    if (hasExternalChannel(sanitizedText)) {
      setError(
        t(
          "Sécurité OLMART : Le partage de coordonnées (téléphone, e-mail, réseaux sociaux) est interdit pour votre protection."
        )
      );
      return;
    }

    const compliantText = maskSensitiveData(sanitizedText);

    try {
      setNewMessage("");

      const idToken = await currentUser.getIdToken();
      const res = await fetch("/api/v1/messages/send", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${idToken}`,
        },
        body: JSON.stringify({
          orderId: orderId,
          text: compliantText,
        }),
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error || "Failed to send message");
      }
    } catch (err: any) {
      console.error(err);
      setError(err.message || t("Erreur lors de l'envoi du message."));
    }
  };

  // Predefined seller templates translated
  const sellerQuickReplies = [
    {
      fr: "Votre commande est en cours de préparation et sera expédiée très bientôt.",
      ar: "طلبكم قيد التحضير وسيتم شحنه في أقرب وقت ممكن.",
      en: "Your order is being prepared and will be shipped very soon.",
    },
    {
      fr: "Pouvez-vous confirmer votre adresse et commune de livraison s'il vous plaît ?",
      ar: "هل يمكنك تأكيد عنوانك وبلدية التوصيل من فضلك؟",
      en: "Can you confirm your address and delivery commune please?",
    },
    {
      fr: "Le colis a été remis au transporteur aujourd'hui. Suivi disponible.",
      ar: "تم تسليم الطرد لشركة الشحن اليوم. التتبع متوفر.",
      en: "The package was handed over to the carrier today. Tracking available.",
    },
    {
      fr: "Merci pour votre confiance ! N'hésitez pas à évaluer notre boutique.",
      ar: "شكراً لثقتكم بنا! لا تترددوا في تقييم متجرنا.",
      en: "Thank you for your trust! Feel free to rate our shop.",
    },
  ];

  const buyerQuickReplies = [
    {
      fr: "Bonjour, quand est-ce que ma commande sera expédiée ?",
      ar: "مرحباً، متى سيتم شحن طلبي؟",
      en: "Hello, when will my order be shipped?",
    },
    {
      fr: "Pouvez-vous me donner plus de détails sur la livraison ?",
      ar: "هل يمكنك إعطائي مزيد من التفاصيل حول التوصيل؟",
      en: "Can you give me more details about the delivery?",
    },
    {
      fr: "J'ai bien reçu ma commande, merci beaucoup !",
      ar: "لقد استلمت طلبي، شكراً جزيلاً لكم!",
      en: "I have successfully received my order, thank you very much!",
    }
  ];

  const quickReplies = isBuyer ? buyerQuickReplies : sellerQuickReplies;

  return (
    <div className="flex flex-col h-[520px] w-full max-w-full min-w-0 bg-transparent/60 rounded-[1.5rem] sm:rounded-[2.5rem] border-2 border-zinc-950 overflow-hidden shadow-xl relative" id="order-chat-box">
      {/* Premium Connection & Status Bar */}
      <div className="bg-zinc-950 p-3.5 sm:p-5 shrink-0 flex flex-col xs:flex-row xs:items-center justify-between gap-3 border-b-2 border-zinc-950">
        <div className="flex items-center gap-2.5 sm:gap-3 min-w-0">
          <div className="w-8 h-8 sm:w-9 sm:h-9 bg-orange-500 rounded-full flex items-center justify-center text-white border-2 border-zinc-950 shrink-0">
            {isBuyer ? <Store className="w-4 sm:w-4.5 h-4 sm:h-4.5" /> : <User className="w-4 sm:w-4.5 h-4 sm:h-4.5" />}
          </div>
          <div className="text-start min-w-0">
            <h4 className="text-white font-sans font-bold text-[11px] sm:text-xs uppercase tracking-wider leading-none truncate max-w-[140px] xs:max-w-[150px] sm:max-w-[200px] md:max-w-none">
              {isBuyer ? shopName : buyerName}
            </h4>
            <div className="flex items-center gap-1.5 mt-1">
              <span className="w-1.5 h-1.5 sm:w-2 sm:h-2 rounded-full bg-emerald-500 animate-pulse shrink-0" />
              <span className="text-[9px] sm:text-[10px] text-zinc-400 font-mono truncate">
                {t("Mise à jour en temps réel")}
              </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-1.5 sm:gap-2 shrink-0 self-end xs:self-auto">
          <button 
            type="button" 
            onClick={handleCopyOrderId}
            className="px-2 py-0.5 sm:px-2.5 sm:py-1 bg-zinc-900 border border-zinc-800 text-zinc-400 rounded-xl text-[8px] sm:text-[9px] font-mono hover:text-white hover:border-zinc-700 transition-all flex items-center gap-1 cursor-pointer shrink-0"
          >
            {copied ? <Check className="w-2.5 h-2.5 text-emerald-400" /> : <Copy className="w-2.5 h-2.5" />}
            <span className="hidden xxs:inline">#</span>{orderId.substring(0, 6)}
          </button>
          <div className="flex items-center gap-1 bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 px-1.5 py-0.5 sm:px-2 sm:py-1 rounded-xl text-[8px] sm:text-[9px] font-sans font-bold uppercase tracking-widest rtl:tracking-normal shrink-0">
            <ShieldCheck className="w-2.5 h-2.5" />
            <span className="hidden xs:inline">{t("Sécurisé")}</span>
          </div>
        </div>
      </div>

      {/* Unified Timeline Area with framer motion animations */}
      <div ref={scrollRef} className="flex-1 p-3.5 sm:p-6 overflow-y-auto space-y-3.5 sm:space-y-4 flex flex-col scroll-smooth">
        <AnimatePresence initial={false}>
          {timelineItems.length === 0 ? (
            <div className="flex-1 flex flex-col items-center justify-center text-stone-400 space-y-2">
              <div className="w-12 h-12 rounded-full bg-stone-100 flex items-center justify-center border-2 border-zinc-200">
                <MessageSquare className="w-5 h-5 text-stone-300" />
              </div>
              <p className="text-xs text-center font-semibold">
                {t("Aucun message ni journal d'activité pour le moment.")}
              </p>
            </div>
          ) : (
            timelineItems.map((item, i) => {
              if (item.isLog) {
                // Activity log layout
                return (
                  <motion.div 
                    initial={{ opacity: 0, scale: 0.95 }}
                    animate={{ opacity: 1, scale: 1 }}
                    key={item.id || i} 
                    className="flex justify-center my-1.5 px-1"
                  >
                    <div className="bg-amber-100/60 border border-amber-200/50 text-amber-900 text-[10px] sm:text-[11px] font-medium px-3 sm:px-4 py-1 sm:py-1.5 rounded-2xl flex items-center justify-center gap-1.5 sm:gap-2 shadow-sm max-w-full text-center">
                      <Info className="w-3.5 h-3.5 text-amber-700 shrink-0" />
                      <span className="line-clamp-2 sm:line-clamp-none">
                        {t(`order_log_status_${item.status}`, item.status)} • {item.type ? t(`order_log_type_${item.type}`, item.type) : ""}
                      </span>
                      <span className="text-[8px] sm:text-[9px] text-amber-700/70 font-mono shrink-0">
                        {new Date(item.timestamp).toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" })}
                      </span>
                    </div>
                  </motion.div>
                );
              }

              const isMe = item.senderId === currentUser?.uid;
              return (
                <motion.div 
                  initial={{ opacity: 0, y: 12 }}
                  animate={{ opacity: 1, y: 0 }}
                  key={item.id || i} 
                  className={`flex w-full ${isMe ? "justify-end" : "justify-start"}`}
                >
                  <div className={`flex gap-1.5 sm:gap-2.5 max-w-[90%] sm:max-w-[80%] ${isMe ? "flex-row-reverse" : "flex-row"}`}>
                    {/* Avatar */}
                    <div className={`w-7 h-7 sm:w-8 sm:h-8 rounded-full flex items-center justify-center text-[10px] sm:text-xs font-black shrink-0 shadow-sm border ${
                       isMe ? "bg-zinc-950 text-white border-zinc-900" : "bg-orange-100 text-[var(--color-orange-600, #ea580c)] border-orange-200"
                    }`}>
                      {item.senderId === buyerId ? <User className="w-3 h-3 sm:w-3.5 sm:h-3.5" /> : <Store className="w-3 h-3 sm:w-3.5 sm:h-3.5" />}
                    </div>

                    <div className="space-y-1 min-w-0">
                      <div
                        className={`p-3 sm:p-3.5 rounded-2xl sm:rounded-3xl text-xs sm:text-sm leading-relaxed relative group/msg ${
                          isMe 
                            ? "bg-zinc-950 text-white rounded-tr-none shadow-md shadow-zinc-950/10" 
                            : "bg-white border-2 border-zinc-950 text-zinc-900 rounded-tl-none shadow-md"
                        }`}
                      >
                        {item.text && <p className="font-medium whitespace-pre-wrap break-words">{item.text}</p>}

                        {item.imageUrl && (
                          <div className="mt-2 rounded-2xl overflow-hidden border border-black/10 max-w-[200px] sm:max-w-[240px]">
                            <img
                              src={item.imageUrl}
                              alt="Attached"
                              className="w-full h-auto cursor-pointer hover:opacity-90 max-h-[150px] sm:max-h-[180px] object-cover"
                              referrerPolicy="no-referrer"
                              onClick={() => window.open(item.imageUrl, "_blank")}
                            />
                          </div>
                        )}

                        {item.flagged && (
                          <div className="mt-1 bg-red-50 text-red-600 text-[10px] px-2 py-1 rounded-md flex items-center gap-1 font-medium border border-red-150">
                            <AlertCircle className="w-3 h-3" />
                            {t("Message signalé")}
                          </div>
                        )}

                        {/* Report button */}
                        {!isMe && !item.flagged && (
                          <button
                            type="button"
                            onClick={() => setReportingMessageId(item.id)}
                            title={t("Signaler ce message")}
                            className="absolute -right-8 top-1/2 -translate-y-1/2 p-1 hover:text-red-500 text-stone-400 rounded transition-all cursor-pointer opacity-0 group-hover/msg:opacity-100 bg-transparent border-none hidden sm:block"
                          >
                            <Flag className="w-3.5 h-3.5" />
                          </button>
                        )}
                      </div>

                      <span className={`text-[9px] font-mono block px-1 ${isMe ? "text-end text-zinc-400" : "text-start text-stone-400"} flex items-center justify-start ${isMe ? "justify-end" : "justify-start"} gap-1.5`}>
                        <span>{new Date(item.timestamp).toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" })}</span>
                        {isMe && <CheckCheck className="w-3 h-3 text-emerald-500 inline font-bold" />}
                        {!isMe && !item.flagged && (
                          <button
                            type="button"
                            onClick={() => setReportingMessageId(item.id)}
                            className="text-stone-400 hover:text-red-500 transition-colors cursor-pointer border-none bg-transparent p-0 sm:hidden flex items-center gap-0.5"
                          >
                            • <Flag className="w-2.5 h-2.5" />
                          </button>
                        )}
                      </span>
                    </div>
                  </div>
                </motion.div>
              );
            })
          )}
        </AnimatePresence>
      </div>

      {/* Predefined Quick Replies (Carousel with scrolling) */}
      <div className="px-3 py-2 sm:px-4 sm:py-2.5 bg-stone-100 border-t border-b border-stone-250 shrink-0 flex items-center gap-1.5 sm:gap-2 overflow-x-auto scrollbar-none w-full max-w-full min-w-0">
        <div className="flex items-center gap-1 text-orange-600 text-[9px] sm:text-[10px] font-sans font-bold uppercase tracking-widest shrink-0">
          <Sparkles className="w-3 h-3 sm:w-3.5 sm:h-3.5" />
          <span>{t("Modèles")} :</span>
        </div>
        <div className="flex gap-1.5 sm:gap-2 shrink-0">
          {quickReplies.map((reply, index) => {
            const labelText = reply[i18n.language as "fr" | "ar" | "en"] || reply.fr;
            return (
              <button
                key={index}
                type="button"
                onClick={() => handleQuickReply(labelText)}
                className="bg-white hover:bg-zinc-900 hover:text-white border border-stone-300 text-stone-700 px-2.5 py-1 sm:px-3 sm:py-1.5 rounded-full text-[10px] sm:text-xs font-medium whitespace-nowrap transition-all shadow-sm active:scale-95 cursor-pointer"
              >
                {labelText}
              </button>
            );
          })}
        </div>
      </div>

      {/* Input Form Area */}
      <div className="p-3 sm:p-4 bg-white shrink-0 border-t border-stone-150">
        {error && (
          <div className="mb-2 sm:mb-3 p-2.5 sm:p-3.5 bg-rose-50 border border-rose-200 text-rose-600 rounded-xl sm:rounded-2xl flex items-start gap-2 text-[11px] sm:text-xs font-medium leading-normal">
            <AlertTriangle className="w-3.5 h-3.5 shrink-0 text-rose-500 mt-0.5" />
            <span>{error}</span>
          </div>
        )}
        <form onSubmit={handleSend} className="relative flex items-center gap-1.5 sm:gap-2">
          {/* File attachment hidden input and button */}
          <input
            type="file"
            accept="image/*"
            ref={fileInputRef}
            onChange={handleImageUpload}
            className="hidden"
            disabled={uploading}
          />
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            disabled={uploading}
            className="p-2.5 sm:p-3 text-stone-500 hover:text-orange-600 transition-all rounded-full cursor-pointer disabled:opacity-50 shrink-0 border border-zinc-200 flex items-center justify-center bg-transparent"
          >
            {uploading ? <Loader2 className="w-4 h-4 sm:w-4.5 sm:h-4.5 animate-spin text-orange-600" /> : <Paperclip className="w-4 h-4 sm:w-4.5 sm:h-4.5" />}
          </button>

          <div className="relative flex-1 flex items-center">
            <input
              type="text"
              value={newMessage}
              onChange={(e) => {
                setNewMessage(e.target.value);
                setError("");
              }}
              maxLength={1000}
              placeholder={isRtl ? "اكتب رسالة..." : "Écrire un message..."}
              className="w-full bg-transparent border-2 border-zinc-950 rounded-[2rem] ps-4 sm:ps-6 pe-12 sm:pe-14 py-3 sm:py-4 text-xs sm:text-sm font-medium focus:outline-none focus:ring-4 focus:ring-orange-500/10 focus:border-orange-500 transition-all text-zinc-900 placeholder:text-stone-400"
            />
            <span className="absolute end-14 text-[8px] sm:text-[9px] font-mono text-stone-400 hidden xxs:inline">
              {newMessage.length}/1000
            </span>
            <button
              type="submit"
              disabled={!newMessage.trim()}
              className="absolute end-1.5 top-1/2 -translate-y-1/2 w-8 h-8 sm:w-11 sm:h-11 bg-orange-600 text-white rounded-full flex items-center justify-center disabled:opacity-40 hover:bg-orange-500 transition-all active:scale-95 shadow-md hover:shadow-orange-600/20 cursor-pointer border-none"
            >
              <Send className={`w-3.5 h-3.5 sm:w-4.5 sm:h-4.5 ${isRtl ? "rotate-180" : ""}`} />
            </button>
          </div>
        </form>
      </div>

      {/* Flag Report Modal overlay */}
      {reportingMessageId && (
        <div className="absolute inset-0 bg-zinc-950/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-6 w-full max-w-sm border border-stone-200 shadow-2xl relative animate-in zoom-in-95 duration-150 text-start">
            <h4 className="font-sans font-bold text-sm text-zinc-900 mb-2 uppercase tracking-wide">
              {t("Signaler ce message")}
            </h4>
            <p className="text-xs text-stone-500 mb-4 leading-relaxed">
              {t("Veuillez indiquer la raison du signalement. Le message sera examiné par nos modérateurs sous 24 heures.")}
            </p>
            <textarea
              value={reportReason}
              onChange={(e) => setReportReason(e.target.value)}
              placeholder={t("Ex: Contenu agressif, partage de contact externe, spam...")}
              className="w-full p-3 text-xs border border-stone-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-red-500/15 focus:border-red-500 mb-4 h-24 font-sans font-medium"
            />
            <div className="flex gap-2 justify-end">
              <button
                type="button"
                onClick={() => {
                  setReportingMessageId(null);
                  setReportReason("");
                }}
                className="px-4 py-2 text-xs font-semibold text-stone-600 bg-stone-100 hover:bg-stone-200 rounded-xl transition-all cursor-pointer border-none"
              >
                {t("Annuler")}
              </button>
              <button
                type="button"
                onClick={handleReportMessage}
                className="px-4 py-2 text-xs font-bold text-white bg-red-600 hover:bg-red-700 rounded-xl transition-all cursor-pointer border-none"
              >
                {t("Confirmer")}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React from "react";
import { ShoppingBag, Heart, Share2, ShieldCheck, Scale } from "lucide-react";
import { useTranslation } from "react-i18next";
import { useComparatorStore } from "../../../store/useComparatorStore";

interface BuyBoxProps {
  product: any;
  isCurrentSelectionOutOfStock: boolean;
  onAddToCart: () => void;
  onToggleWishlist: () => void;
  wishlist: string[];
  onShare: () => void;
  stickyRef?: React.Ref<HTMLDivElement>;
  isSticky?: boolean;
}

export const ProductBuyBox: React.FC<BuyBoxProps> = ({
  product,
  isCurrentSelectionOutOfStock,
  onAddToCart,
  onToggleWishlist,
  wishlist,
  onShare,
  stickyRef,
  isSticky,
}) => {
  const { t } = useTranslation();
  const { products: comparedProducts, addProduct: addToCompare, removeProduct: removeFromCompare } = useComparatorStore();
  const isCompared = comparedProducts.some(p => p.id === product.id);

  return (
    <div
      ref={stickyRef}
      className={`z-40 ${isSticky ? "fixed bottom-0 left-0 right-0 p-3 sm:p-5 bg-white/95 backdrop-blur-md border-t border-stone-200 shadow-[0_-10px_30px_rgba(40,30,20,0.08)] animate-in slide-in-from-bottom-12 duration-300" : "relative"}`}
    >
      <div className={`flex gap-2 sm:gap-3.5 max-w-7xl mx-auto ${isSticky ? "justify-center" : ""}`}>
        <button
          disabled={isCurrentSelectionOutOfStock}
          onClick={onAddToCart}
          className={`flex-1 sm:flex-[3] py-3.5 sm:py-4.5 rounded-full flex items-center justify-center gap-2 sm:gap-3 transition-all duration-300 group border border-transparent shadow-md hover:shadow-lg ${
            isCurrentSelectionOutOfStock
              ? "bg-stone-100 text-stone-400 cursor-not-allowed"
              : "bg-[#008BB5] text-white hover:bg-[#007CA7] active:scale-95"
          }`}
        >
          <ShoppingBag className="w-4.5 h-4.5" />
          <span className="font-sans font-bold uppercase tracking-wider text-[11px] sm:text-xs whitespace-nowrap">
            {isCurrentSelectionOutOfStock ? t("out_of_stock") || "En rupture" : t("add_to_cart") || "Ajouter au Panier"}
          </span>
        </button>

        <button
          onClick={onToggleWishlist}
          className={`w-12 sm:w-14 h-12 sm:h-auto rounded-full border transition-all flex items-center justify-center shrink-0 shadow-sm active:scale-90 ${
            wishlist.includes(product.id)
              ? "border-[#D81159] bg-[#FFEAEF] text-[#D81159]"
              : "border-stone-200 bg-white text-stone-600 hover:text-[#D81159] hover:border-[#D81159]"
          }`}
          aria-label={t("Add to wishlist") || "Add to wishlist"}
        >
          <Heart className={`w-4 h-4 sm:w-5 sm:h-5 ${wishlist.includes(product.id) ? "fill-[#D81159]" : ""}`} />
        </button>

        <button
          onClick={() => {
            if (isCompared) {
              removeFromCompare(product.id);
            } else {
              addToCompare(product);
            }
          }}
          className={`w-12 sm:w-14 h-12 sm:h-auto rounded-full border transition-all flex items-center justify-center shrink-0 shadow-sm active:scale-90 ${
            isCompared
              ? "border-[#008BB5] bg-[#E5F6FA] text-[#008BB5]"
              : "border-stone-200 bg-white text-stone-600 hover:text-[#008BB5] hover:border-[#008BB5]"
          }`}
          aria-label={t("Comparer") || "Comparer"}
        >
          <Scale className={`w-4 h-4 sm:w-5 sm:h-5 ${isCompared ? "stroke-[2.5]" : ""}`} />
        </button>

        <button
          onClick={onShare}
          className={`w-12 sm:w-14 h-12 sm:h-auto rounded-full bg-white border border-stone-200 text-stone-600 flex items-center justify-center hover:text-black hover:border-black shadow-sm active:scale-90 transition-all ${
            isSticky ? "hidden sm:flex" : "flex"
          }`}
          aria-label={t("Share product") || "Share product"}
        >
          <Share2 className="w-4 h-4 sm:w-5 sm:h-5" />
        </button>
      </div>

      {isSticky && (
        <div className="hidden sm:flex max-w-7xl mx-auto mt-2.5 items-center justify-center gap-1.5 text-[10px] rtl:text-[12px] font-bold text-stone-500 uppercase tracking-widest rtl:tracking-normal">
          <ShieldCheck className="w-3.5 h-3.5 text-[#008BB5]" /> {t("secured_cash_on_delivery") || "Paiement à la livraison sécurisé"}
        </div>
      )}
    </div>
  );
};

import React from "react";
import { motion, AnimatePresence } from "motion/react";
import { ImageMagnifier } from "../ImageMagnifier";
import { Play, ArrowLeft } from "lucide-react";
import { getOptimizedImageUrl } from "../../../utils/imageUtils";

interface GalleryProps {
  images: string[];
  selectedIndex: number;
  productName: string;
  onSelectImage: (index: number) => void;
  showVideo: boolean;
  setShowVideo: (show: boolean) => void;
  productVideoUrl?: string;
  onOpenLightbox: () => void;
}

export const ProductGallery: React.FC<GalleryProps> = ({
  images,
  selectedIndex,
  productName,
  onSelectImage,
  showVideo,
  setShowVideo,
  productVideoUrl,
  onOpenLightbox,
}) => {
  const handleDragEnd = (event: any, info: any) => {
    const swipeThreshold = 50;
    if (info.offset.x < -swipeThreshold) {
      // Swiped left -> next image
      if (selectedIndex < images.length - 1) {
        onSelectImage(selectedIndex + 1);
        setShowVideo(false);
      }
    } else if (info.offset.x > swipeThreshold) {
      // Swiped right -> previous image
      if (selectedIndex > 0) {
        onSelectImage(selectedIndex - 1);
        setShowVideo(false);
      }
    }
  };

  return (
    <div className="space-y-4 px-0">
      {/* Arched Frame inspired by the traditional door in the picture */}
      <div
        onContextMenu={(e) => e.preventDefault()}
        className="relative aspect-[4/5] max-h-[500px] sm:max-h-none rounded-t-[160px] rounded-b-[32px] overflow-hidden bg-[#FAF6F0] border-[10px] sm:border-[14px] border-[#EAE3D5] shadow-[0_15px_40px_-15px_rgba(40,30,20,0.15),inset_0_2px_8px_rgba(0,0,0,0.06)] group cursor-pointer transition-all duration-300"
      >
        {/* Traditional studded door metallic accents (simulated on outer edges) */}
        <div className="absolute inset-x-0 top-12 flex justify-between px-6 pointer-events-none opacity-30">
          <div className="w-2.5 h-2.5 rounded-full bg-[#3E3A35] shadow-[0_1px_2px_rgba(0,0,0,0.5)]"></div>
          <div className="w-2.5 h-2.5 rounded-full bg-[#3E3A35] shadow-[0_1px_2px_rgba(0,0,0,0.5)]"></div>
        </div>

        {showVideo && productVideoUrl ? (
          <div className="absolute inset-0 z-20 bg-black flex items-center justify-center">
            <video
              key={productVideoUrl}
              src={`/api/v1/proxy-video?url=${encodeURIComponent(productVideoUrl)}`}
              controls
              playsInline
              autoPlay
              muted
              loop
              preload="metadata"
              className="w-full h-full object-contain bg-black"
            />
            {productVideoUrl && (
              <a 
                href={productVideoUrl} 
                target="_blank" 
                rel="noopener noreferrer"
                className="absolute top-4 right-[60px] bg-white/90 backdrop-blur-md px-3.5 py-2 rounded-xl shadow-lg z-30 text-xs font-bold text-black"
              >
                Ouvrir la vidéo
              </a>
            )}
            <button
              onClick={(e) => {
                e.stopPropagation();
                setShowVideo(false);
              }}
              className="absolute top-4 right-4 w-10 h-10 bg-black/50 hover:bg-black text-white rounded-full flex items-center justify-center transition-colors z-30"
            >
              ✕
            </button>
          </div>
        ) : null}

        {/* Desktop View with ImageMagnifier */}
        <div className="hidden lg:block w-full h-full bg-[#FAF6F0]">
          <ImageMagnifier
            src={getOptimizedImageUrl(images[selectedIndex], 1200)}
            alt={productName}
            className="w-full h-full object-cover mix-blend-multiply"
            onClick={onOpenLightbox}
          />
        </div>

        {/* Mobile Swipe-enabled View */}
        <div className="lg:hidden w-full h-full relative overflow-hidden flex items-center justify-center bg-[#FAF6F0]">
          <AnimatePresence mode="wait">
            <motion.img
              key={selectedIndex}
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 1.05 }}
              transition={{ type: "tween", ease: "easeInOut", duration: 0.3 }}
              src={getOptimizedImageUrl(images[selectedIndex], 800)}
              draggable="true"
              drag="x"
              dragConstraints={{ left: 0, right: 0 }}
              dragElastic={0.8}
              onDragEnd={handleDragEnd}
              className="w-full h-full object-cover select-none mix-blend-multiply pointer-events-auto"
              alt={productName}
              onClick={onOpenLightbox}
            />
          </AnimatePresence>

          {/* Swipe indicator dots - Zara style */}
          {images.length > 1 && (
            <div className="absolute bottom-6 left-0 w-full flex justify-center gap-2 z-10 px-4">
              {images.map((_, idx) => (
                <button
                  key={idx}
                  onClick={(e) => {
                    e.stopPropagation();
                    onSelectImage(idx);
                    setShowVideo(false);
                  }}
                  className={`h-1 rounded-full transition-all duration-300 ${
                    selectedIndex === idx 
                      ? "bg-[#008BB5] w-6" 
                      : "bg-black/15 w-2 hover:bg-black/40"
                  }`}
                  aria-label={`Go to slide ${idx + 1}`}
                />
              ))}
            </div>
          )}
        </div>

        {productVideoUrl && !showVideo && (
          <button
            onClick={(e) => {
              e.stopPropagation();
              setShowVideo(true);
            }}
            className="absolute bottom-6 right-6 w-12 h-12 rounded-full bg-[#008BB5] text-white flex items-center justify-center hover:bg-[#007CA7] shadow-lg hover:scale-105 active:scale-95 transition-all duration-200 z-10"
          >
            <Play className="w-5 h-5 fill-current ml-0.5 text-white" />
          </button>
        )}
      </div>

      {(images.length > 1 || productVideoUrl) && (
        <div className="flex gap-2.5 overflow-x-auto pb-2 scrollbar-hide justify-start sm:justify-start px-1 sm:px-0 mt-3">
          {productVideoUrl && (
            <button
              onClick={() => setShowVideo(true)}
              className={`w-14 h-18 sm:w-20 sm:h-28 rounded-t-3xl rounded-b-xl overflow-hidden transition-all shrink-0 bg-stone-100 flex items-center justify-center relative ${
                showVideo 
                  ? "border-2 border-[#008BB5] opacity-100 shadow-md scale-95" 
                  : "border border-stone-250 opacity-60 hover:opacity-100"
              }`}
            >
              <Play className="w-5 h-5 text-[#008BB5] fill-[#008BB5]" />
            </button>
          )}
          {images.map((img, i) => (
            <button
              key={i}
              onClick={() => {
                onSelectImage(i);
                setShowVideo(false);
              }}
              onContextMenu={(e) => e.preventDefault()}
              className={`w-14 h-18 sm:w-20 sm:h-28 rounded-t-3xl rounded-b-xl overflow-hidden transition-all shrink-0 bg-[#FAF6F0] border-2 ${
                selectedIndex === i && !showVideo
                  ? "border-[#008BB5] opacity-100 shadow-md scale-95" 
                  : "border-stone-200/50 opacity-70 hover:opacity-100"
              }`}
            >
              <img
                loading="lazy"
                src={getOptimizedImageUrl(img, 200)}
                draggable={false}
                className="w-full h-full object-cover mix-blend-multiply select-none pointer-events-none"
                alt=""
              />
            </button>
          ))}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from "react";
import {
  Star,
  Info,
  Store,
  MapPin,
  Truck,
  ShieldCheck,
  Tag,
  Sparkles,
  CalendarDays,
  Layers,
  Undo2,
  Maximize2,
  FileText,
  Check,
  UserPlus,
  UserCheck,
  Flame,
  Clock,
} from "lucide-react";
import { Link, useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { motion, AnimatePresence } from "motion/react";
import { Product } from "../../../domains/product/product.types";
import { Shop } from "../../../domains/seller/shop.types";
import { formatPrice } from "../../../utils/format";
import { DYNAMIC_CATEGORIES } from "../../../config/dynamicFilters";
import { PRODUCT_COLORS } from "../../../constants";
import { useAuth } from "../../../context/AuthContext";
import { toast } from "react-hot-toast";
import { ConfirmModal } from "../../ui/ConfirmModal";
import { apiGet, apiPost } from "../../../lib/api";

const MATERIAL_TRANSLATIONS: Record<string, Record<string, string>> = {
  Coton: { fr: "Coton", en: "Cotton", ar: "قطن" },
  Laine: { fr: "Laine", en: "Wool", ar: "صوف" },
  Cuir: { fr: "Cuir", en: "Leather", ar: "جلد" },
  Argile: { fr: "Argile (Poterie)", en: "Clay (Pottery)", ar: "طين / فخار" },
  Cuivre: { fr: "Cuivre", en: "Copper", ar: "نحاس" },
  Soie: { fr: "Soie", en: "Silk", ar: "حرير" },
  Lin: { fr: "Lin", en: "Linen", ar: "كتان" },
  Or: { fr: "Or", en: "Gold", ar: "ذهب" },
  Argent: { fr: "Argent", en: "Silver", ar: "فضة" },
  Bois: { fr: "Bois", en: "Wood", ar: "خشب" },
  Céramique: { fr: "Céramique", en: "Ceramic", ar: "سيراميك" },
  Verre: { fr: "Verre", en: "Glass", ar: "زجاج" },
  "Fil d'Or": { fr: "Fil d'Or (Majboud/Fetla)", en: "Gold Thread (Fetla)", ar: "فتلة / مجبود" },
  Autre: { fr: "Autre", en: "Other", ar: "أخرى" },
};

const SEASON_TRANSLATIONS: Record<string, Record<string, string>> = {
  "Toutes Saisons": { fr: "Toutes Saisons", en: "All Seasons", ar: "كل الفصول" },
  "Printemps / Été": { fr: "Printemps / Été", en: "Spring / Summer", ar: "الربيع / الصيف" },
  "Automne / Hiver": { fr: "Automne / Hiver", en: "Autumn / Winter", ar: "الخريف / الشتاء" },
  "Collection Ramadan": { fr: "Collection Ramadan", en: "Ramadan Collection", ar: "مجموعة رمضان" },
  "Collection Traditionnelle": { fr: "Collection Traditionnelle", en: "Traditional Collection", ar: "مجموعة تقليدية" },
  "Édition Limitée": { fr: "Édition Limitée", en: "Limited Edition", ar: "طبعة محدودة" },
};

interface InfoProps {
  product: Product;
  shop: Shop | null;
  currentPrice: number;
  selectedColor: string | null;
  selectedSize: string | null;
  onSelectColor: (c: string) => void;
  onSelectSize: (s: string) => void;
  isColorOutOfStock: (c: string) => boolean;
  isSizeOutOfStock: (s: string) => boolean;
}

export const ProductInfo: React.FC<InfoProps> = ({
  product,
  shop,
  currentPrice,
  selectedColor,
  selectedSize,
  onSelectColor,
  onSelectSize,
  isColorOutOfStock,
  isSizeOutOfStock,
}) => {
  const navigate = useNavigate();
  const { currentUser } = useAuth();
  const { t, i18n } = useTranslation();
  const [isSizeGuideOpen, setIsSizeGuideOpen] = React.useState(false);
  const [isFollowing, setIsFollowing] = useState(false);
  const [followLoading, setFollowLoading] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [bilingualMode, setBilingualMode] = useState(false);

  const [openAccordion, setOpenAccordion] = useState<string | null>("description");
  const [isDescExpanded, setIsDescExpanded] = useState(false);

  const toggleAccordion = (section: string) => {
    setOpenAccordion(openAccordion === section ? null : section);
  };

  const [timeLeft, setTimeLeft] = useState({ hours: 0, minutes: 0, seconds: 0 });
  const isProductFlashActive = !!(
    product.flashSaleActive &&
    product.flashPrice &&
    (!product.flashEndDate || new Date(product.flashEndDate).getTime() > Date.now())
  );

  useEffect(() => {
    if (!isProductFlashActive) return;
    const calculateTimeLeft = () => {
      const now = new Date();
      let targetDate = new Date();
      if (product.flashEndDate) {
        targetDate = new Date(product.flashEndDate);
      } else {
        targetDate.setHours(23, 59, 59, 999);
      }
      const difference = targetDate.getTime() - now.getTime();

      if (difference > 0) {
        setTimeLeft({
          hours: Math.floor((difference / (1000 * 60 * 60)) % 24),
          minutes: Math.floor((difference / 1000 / 60) % 60),
          seconds: Math.floor((difference / 1000) % 60),
        });
      } else {
        setTimeLeft({ hours: 0, minutes: 0, seconds: 0 });
      }
    };

    calculateTimeLeft();
    const timer = setInterval(calculateTimeLeft, 1000);
    return () => clearInterval(timer);
  }, [product.flashEndDate, isProductFlashActive]);

  useEffect(() => {
    const checkFollowStatus = async () => {
      if (!currentUser || !shop?.id) return;
      try {
        const res = await apiGet<{ following: boolean }>(`/api/v1/auth/following/${encodeURIComponent(shop.id)}`);
        if (res && res.following) {
          setIsFollowing(true);
        }
      } catch (err) {
        console.error("Error checking follow status:", err);
      }
    };
    checkFollowStatus();
  }, [currentUser, shop?.id]);

  const handleFollowToggle = async () => {
    if (!currentUser) {
      navigate("/login");
      return;
    }
    if (!shop?.id || followLoading) return;

    if (isFollowing) {
      setShowConfirm(true);
      return;
    }

    executeFollowToggle();
  };

  const executeFollowToggle = async () => {
    setFollowLoading(true);
    try {
      if (isFollowing) {
        const res = await fetch(`/api/v1/auth/following/${encodeURIComponent(shop!.id)}`, { method: "DELETE" });
        if (!res.ok) throw new Error("Unfollow failed");
        setIsFollowing(false);
        toast.success(t("product.details.unfollow_success") || "Désabonnement réussi.");
      } else {
        await apiPost(`/api/v1/auth/following/${encodeURIComponent(shop!.id)}`, {
          sellerId: shop!.id,
          name: shop!.shopName || "Boutique",
          logo: shop!.logoUrl || null,
          location: shop!.wilaya || "Algérie",
        });
        setIsFollowing(true);
        toast.success(t("product.details.follow_success") || "Boutique suivie !");
      }
    } catch (err) {
      console.error("Error toggling follow:", err);
      toast.error(t("product.details.error_action") || "Erreur lors de l'action.");
    } finally {
      setFollowLoading(false);
      setShowConfirm(false);
    }
  };

  const currentLang = i18n.language || "fr";
  const isRTL = currentLang === "ar";

  const getTranslatedMaterials = () => {
    if (!product.materials || product.materials.length === 0) return null;
    return product.materials
      .map((m) => {
        if (MATERIAL_TRANSLATIONS[m]?.[currentLang]) {
          return MATERIAL_TRANSLATIONS[m][currentLang];
        }
        return m;
      })
      .join(", ");
  };

  const getTranslatedSeason = () => {
    if (!product.season) return null;
    if (SEASON_TRANSLATIONS[product.season]?.[currentLang]) {
      return SEASON_TRANSLATIONS[product.season][currentLang];
    }
    return product.season;
  };

  // Automated translation logic for user uploaded items
  const productName = product.translations?.[currentLang]?.name || product.name;
  const productDescription = product.translations?.[currentLang]?.description || product.description;

  // Extract custom attributes based on category
  const categoryDef = DYNAMIC_CATEGORIES[product.category || ""];
  const detailedAttributes: any[] = [];

  if (categoryDef && categoryDef.allowed_filters && product?.attributes) {
    const attrs = product.attributes;
    categoryDef.allowed_filters.forEach((filter) => {
      const val = attrs[filter.id];
      if (val) {
        detailedAttributes.push({
          label: filter.label,
          value: Array.isArray(val) ? val.join(", ") : val,
          unit: filter.unit,
        });
      }
    });
  }

  return (
    <div className="space-y-6" dir={isRTL ? "rtl" : "ltr"}>
      <ConfirmModal
        isOpen={showConfirm}
        onClose={() => setShowConfirm(false)}
        onConfirm={executeFollowToggle}
        title={t("product.details.unfollow_confirm_title") || "Se désabonner"}
        message={
          t("product.details.unfollow_confirm_message") || "Voulez-vous vraiment ne plus suivre cette boutique ?"
        }
      />

      {/* HEADER BENTO BLOCK */}
      <div className="bg-[#FAF6F0] rounded-[2rem] p-4 sm:p-6 border border-[#EAE3D5] shadow-sm space-y-3.5 relative overflow-hidden">
        {/* Decorative corner curve resembling the arch */}
        <div className="absolute top-0 right-0 w-16 h-16 bg-[#008BB5]/5 rounded-bl-[2.5rem] border-l border-b border-[#EAE3D5]/40 pointer-events-none" />

        <div className="flex items-center justify-between gap-3 relative z-10">
          {product.condition && (
            <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] uppercase font-bold tracking-wider bg-[#FFEAEF] text-[#D81159] border border-[#FFEAEF]">
              <Sparkles className="w-3 h-3" /> {product.condition}
            </span>
          )}
          <button
            type="button"
            onClick={() => setBilingualMode(!bilingualMode)}
            className={`px-3 py-1 border text-[9px] font-bold uppercase tracking-wider transition-all rounded-full cursor-pointer flex items-center gap-1.5 ${
              bilingualMode 
                ? "bg-[#008BB5] text-white border-[#008BB5] shadow-sm" 
                : "bg-white border-[#EAE3D5] text-[#008BB5] hover:bg-[#008BB5]/5"
            }`}
          >
            🌍 {bilingualMode ? "AR / FR" : "Affichage Bilingue"}
          </button>
        </div>

        {bilingualMode ? (
          <div className="space-y-1.5 text-start relative z-10">
            <h1 className="text-xl sm:text-2xl font-sans font-extrabold text-[#2C2C28] uppercase tracking-wide leading-tight break-words">
              {product.translations?.["ar"]?.name || product.name}
            </h1>
            <h2 className="text-sm sm:text-base font-sans text-stone-500 uppercase tracking-wide leading-tight break-words border-t border-stone-200/50 pt-1.5 font-medium">
              {product.translations?.["fr"]?.name || product.name}
            </h2>
          </div>
        ) : (
          <h1 className="text-xl sm:text-2xl font-sans font-extrabold text-[#2C2C28] uppercase tracking-wide leading-tight break-words relative z-10">
            {productName}
          </h1>
        )}

        {/* PRICING & RATING ROW */}
        <div className="flex items-center justify-between gap-4 pt-1 border-t border-[#EAE3D5]/50 relative z-10">
          <div className="flex items-baseline gap-2">
            <span className="text-2xl sm:text-3xl font-sans font-black text-[#008BB5]">
              {formatPrice(currentPrice)}
            </span>
            {isProductFlashActive ? (
              <span className="text-sm text-stone-400 line-through font-sans">
                {formatPrice(product.price)}
              </span>
            ) : (
              product.onSale && (
                <span className="text-sm text-stone-400 line-through font-sans">
                  {formatPrice(currentPrice * 1.2)}
                </span>
              )
            )}
          </div>

          {/* Quick rating snippet with bougainvillea pink stars */}
          {product.stats?.averageRating && (
            <div className="flex items-center gap-1 bg-[#D81159]/5 px-2.5 py-1 rounded-full border border-[#D81159]/10">
              <Star className="w-3.5 h-3.5 fill-[#D81159] text-[#D81159]" />
              <span className="text-xs font-bold text-[#D81159]">
                {Number(product.stats.averageRating).toFixed(1)}
              </span>
            </div>
          )}
        </div>

        {product.energyClass && (
          <div className="flex items-center pt-1">
            <div className="flex items-center border border-stone-300 rounded overflow-hidden">
               <div 
                  className="text-white font-bold text-[9px] px-2 py-0.5"
                  style={{
                    backgroundColor: (() => {
                      switch(product.energyClass) {
                        case "A": return "#00A650";
                        case "B": return "#50B848";
                        case "C": return "#C4D400";
                        case "D": return "#FFF200";
                        case "E": return "#F7B500";
                        case "F": return "#EB690B";
                        case "G": return "#E2001A";
                        default: return "#00A650";
                      }
                    })()
                  }}
               >
                  Classe {product.energyClass}
               </div>
               <div className="bg-stone-100 text-[8px] flex flex-col leading-none px-1.5 py-0.5 font-bold">
                 <span>A</span>
                 <span>↑</span>
                 <span>G</span>
               </div>
            </div>
          </div>
        )}
      </div>

      {/* FLASH SALE - SOPHISTICATED NO-WASTE DESIGN */}
      {isProductFlashActive && (
        <div className="border border-[#D81159]/25 bg-[#FFEAEF]/40 rounded-3xl p-4 relative overflow-hidden shadow-sm">
          {/* Subtle fuchsia glowing circle */}
          <div className="absolute top-0 right-0 w-32 h-32 bg-[#D81159]/5 rounded-full blur-2xl" />

          <div className="flex flex-col gap-3 relative z-10">
            <div className="flex items-center justify-between gap-3 border-b border-[#D81159]/10 pb-2">
              <div className="flex items-center gap-2">
                <span className="inline-flex w-2 h-2 rounded-full bg-[#D81159] animate-pulse" />
                <span className="text-[10px] font-bold uppercase tracking-widest text-[#D81159]">
                  {t("VENTE FLASH EXCLUSIVE")}
                </span>
              </div>
              <span className="text-xs font-extrabold text-[#D81159] bg-white px-2 py-0.5 rounded-lg border border-[#D81159]/10">
                -{Math.round(((product.price - currentPrice) / product.price) * 100)}%
              </span>
            </div>

            <div className="grid grid-cols-2 gap-3 items-center">
              <div className="space-y-0.5">
                <span className="text-[9px] font-bold text-stone-400 uppercase tracking-wider">
                  {t("EXPIRE DANS")}
                </span>
                <div className="flex items-center gap-1 font-sans font-bold text-base text-[#2C2C28]">
                  <span>{String(timeLeft.hours).padStart(2, "0")}</span>
                  <span className="text-[#D81159] animate-pulse">:</span>
                  <span>{String(timeLeft.minutes).padStart(2, "0")}</span>
                  <span className="text-[#D81159] animate-pulse">:</span>
                  <span>{String(timeLeft.seconds).padStart(2, "0")}</span>
                </div>
              </div>

              <div className="space-y-1.5 border-l border-stone-200/60 pl-3">
                <div className="flex justify-between text-[9px] font-bold uppercase tracking-wider text-stone-500">
                  <span>{currentLang === "ar" ? "محجوز" : "Réservé"}</span>
                  <span className="text-[#D81159]">92%</span>
                </div>
                <div className="w-full h-1.5 bg-stone-200 rounded-full overflow-hidden">
                  <div className="h-full bg-[#D81159]" style={{ width: "92%" }} />
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* SELLER PROMINENCE - Moorish Arch Alcove Layout */}
      {shop && (
        <div className="bg-white rounded-[2rem] p-4 border border-[#EAE3D5] shadow-sm flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 rounded-t-full rounded-b-xl bg-[#FAF6F0] flex items-center justify-center overflow-hidden border-2 border-[#008BB5] shrink-0">
              {shop.logoUrl ? (
                <img loading="lazy" src={shop.logoUrl} alt={shop.shopName} className="w-full h-full object-cover" />
              ) : (
                <Store className="w-5 h-5 text-[#008BB5]" />
              )}
            </div>
            <div>
              <p className="text-[9px] font-bold text-[#008BB5] uppercase tracking-wider mb-0.5">
                {t("product.details.sold_by") || "Vendu par"}
              </p>
              <Link
                to={`/shop/${shop.id}`}
                className="text-sm font-sans font-bold text-[#2C2C28] hover:text-[#008BB5] transition-all line-clamp-1"
              >
                {shop.shopName}
              </Link>
            </div>
          </div>

          <div className="flex items-center gap-2 w-full sm:w-auto">
            <button
              onClick={handleFollowToggle}
              disabled={followLoading}
              className={`flex-1 sm:flex-none flex items-center justify-center gap-1.5 px-4 py-2 rounded-full font-bold text-[10px] uppercase tracking-wider transition-all border shadow-sm ${
                isFollowing
                  ? "bg-transparent text-stone-600 border-stone-200 hover:bg-stone-100"
                  : "bg-[#008BB5] text-white border-[#008BB5] hover:bg-[#007CA7]"
              }`}
            >
              {isFollowing ? (
                <span className="flex items-center gap-1"><UserCheck className="w-3.5 h-3.5" /> {t("product.details.following") || "Abonné"}</span>
              ) : (
                <span className="flex items-center gap-1"><UserPlus className="w-3.5 h-3.5" /> {t("product.details.follow") || "Suivre"}</span>
              )}
            </button>
            <Link
              to={`/shop/${shop.id}`}
              className="flex-1 sm:flex-none text-center px-4 py-2 bg-white text-stone-600 border border-stone-200 rounded-full text-[10px] font-bold uppercase tracking-wider transition-colors hover:bg-transparent"
            >
              {t("product.details.view_shop") || "Boutique"}
            </Link>
          </div>
        </div>
      )}

      {/* VARIANTS (COLOR/SIZE) - BEAUTIFUL BRASS AND BLUE STUDS DESIGN */}
      {((product.colors?.length || 0) > 0 || (product.sizes?.length || 0) > 0) && (
        <div className="bg-[#FAF6F0] rounded-[2rem] p-4 sm:p-5 border border-[#EAE3D5] shadow-sm space-y-5">
          {product.colors && product.colors.length > 0 && (
            <div className="space-y-2.5">
              <h4 className="text-[10px] font-bold uppercase tracking-widest text-stone-500">
                {t("product.details.nuances") || "Couleurs"}
              </h4>
              <div className="flex flex-wrap gap-2.5">
                {product.colors.map((c: string) => {
                  const matchingColor = PRODUCT_COLORS.find(
                    (pc) => pc.name.toLowerCase().trim() === c.toLowerCase().trim()
                  );
                  const isHex = /^#([0-9A-F]{3}){1,2}$/i.test(c);
                  const isRgb = /^rgb/i.test(c);
                  const colorHex = matchingColor ? matchingColor.hex : isHex || isRgb ? c : "#FFFFFF";
                  const isWhiteOrLight =
                    colorHex.toLowerCase() === "#ffffff" ||
                    colorHex.toLowerCase() === "#fde68a" ||
                    colorHex.toLowerCase() === "#facc15";

                  return (
                    <button
                      key={c}
                      disabled={isColorOutOfStock(c) && selectedColor !== c}
                      onClick={() => onSelectColor(c)}
                      className={`flex items-center justify-center p-0.5 rounded-full border-2 transition-all shadow-sm ${
                        selectedColor === c 
                          ? "border-[#008BB5] scale-110" 
                          : "border-transparent hover:border-stone-300"
                      } ${isColorOutOfStock(c) ? "opacity-30 cursor-not-allowed" : ""}`}
                    >
                      <div 
                        className="w-8 h-8 rounded-full border border-black/15 flex items-center justify-center relative shadow-[inset_0_1px_3px_rgba(0,0,0,0.15)]"
                        style={{ background: colorHex }}
                      >
                        {selectedColor === c && (
                          <Check className={`w-3.5 h-3.5 ${isWhiteOrLight ? "text-black" : "text-white"}`} />
                        )}
                        {isColorOutOfStock(c) && (
                          <div className="absolute inset-0 flex items-center justify-center">
                            <div className="w-full h-[1.5px] bg-black rotate-45"></div>
                          </div>
                        )}
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {product.sizes && product.sizes.length > 0 && (
            <div className="space-y-2.5 pt-4 border-t border-[#EAE3D5]">
              <div className="flex items-center justify-between">
                <h4 className="text-[10px] font-bold uppercase tracking-widest text-stone-500">
                  {t("product.details.sizes") || "Tailles"}
                </h4>
                <button
                  type="button"
                  onClick={() => setIsSizeGuideOpen(true)}
                  className="text-[9px] font-bold uppercase tracking-wider text-[#008BB5] hover:underline transition-all cursor-pointer"
                >
                  {t("product.details.size_guide") || "Guide des tailles"}
                </button>
              </div>
              <div className="flex flex-wrap gap-2">
                {product.sizes.map((s: string) => (
                  <button
                    key={s}
                    disabled={isSizeOutOfStock(s) && selectedSize !== s}
                    onClick={() => onSelectSize(s)}
                    className={`px-4 py-2 rounded-xl font-sans font-bold text-[10px] uppercase tracking-wider transition-all border ${
                      selectedSize === s 
                        ? "bg-[#008BB5] text-white border-[#008BB5] shadow-md" 
                        : "bg-white border-stone-200 text-stone-700 hover:border-[#008BB5]"
                    } ${isSizeOutOfStock(s) ? "opacity-30 cursor-not-allowed" : ""}`}
                  >
                    {s}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {/* ACCORDIONS - EXTREMELY SOPHISTICATED BENTO TABS */}
      <div className="bg-white rounded-[2rem] border border-[#EAE3D5] overflow-hidden shadow-sm">
        {/* Accordion 1: Description */}
        <div className="border-b border-[#EAE3D5]">
          <button
            onClick={() => toggleAccordion("description")}
            className="w-full flex items-center justify-between px-5 py-4 text-start font-sans font-bold text-xs uppercase tracking-wider text-[#2C2C28]"
          >
            <span className="flex items-center gap-2">
              <FileText className="w-4 h-4 text-[#008BB5]" />
              {t("Description / taillant")}
            </span>
            <span className={`text-stone-400 font-light text-base transition-transform duration-300 ${openAccordion === "description" ? "rotate-180" : ""}`}>
              ▼
            </span>
          </button>

          <AnimatePresence initial={false}>
            {openAccordion === "description" && (
              <motion.div
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: "auto", opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                className="overflow-hidden"
              >
                <div className="px-5 pb-5 pt-1 space-y-4 text-stone-600 bg-[#FAF6F0]/25">
                  {bilingualMode ? (
                    <div className="space-y-4 text-start">
                      {(product.translations?.["ar"]?.description || product.description) && (
                        <div className="space-y-1 text-right" dir="rtl">
                          <span className="text-[8px] font-bold text-[#D81159] bg-[#FFEAEF] px-2 py-0.5 rounded uppercase tracking-wider">العربية</span>
                          <p className="text-[#2C2C28]/85 text-xs whitespace-pre-wrap leading-relaxed font-medium">
                            {product.translations?.["ar"]?.description || product.description}
                          </p>
                        </div>
                      )}
                      {(product.translations?.["fr"]?.description || product.description) && (
                        <div className="space-y-1 text-left border-t border-[#EAE3D5] pt-3" dir="ltr">
                          <span className="text-[8px] font-bold text-stone-600 bg-stone-100 px-2 py-0.5 rounded uppercase tracking-wider">Français</span>
                          <p className="text-[#2C2C28]/85 text-xs whitespace-pre-wrap leading-relaxed font-medium">
                            {product.translations?.["fr"]?.description || product.description}
                          </p>
                        </div>
                      )}
                    </div>
                  ) : (
                    <p className="text-[#2C2C28]/85 text-xs whitespace-pre-wrap leading-relaxed font-medium">
                      {productDescription}
                    </p>
                  )}
