                  product.promoPrice &&
                  product.promoPrice < product.price && (
                    <span className="bg-slate-900 text-white font-sans font-bold text-[10px] px-2.5 py-1 rounded-full shadow-sm">
                      -{Math.round(((product.price - product.promoPrice) / product.price) * 100)}%
                    </span>
