              </div>

              {/* Wishlist Button */}
              <div className="absolute top-3 right-3 z-20 flex flex-col gap-2">
                <button
                  aria-label={wishlist.includes(product.id) ? "Retirer des favoris" : "Ajouter aux favoris"}
