            body {
              font-family: 'Inter', sans-serif;
              margin: 0;
              padding: 10px;
              color: #000;
              background: #fff;
              -webkit-print-color-adjust: exact;
            }
            .label-card {
              width: 100%;
              max-width: ${labelSize === "a6" ? "101mm" : "76mm"};
              margin: 0 auto;
              border: 2px solid #000;
              padding: 10px;
              box-sizing: border-box;
            }
            .header-bar {
              display: flex;
              align-items: center;
              justify-content: space-between;
              border-bottom: 2px solid #000;
              padding-bottom: 8px;
              margin-bottom: 8px;
            }
            .header-bar h2 {
              margin: 0;
              font-size: 16px;
              font-weight: 950;
              text-transform: uppercase;
            }
            .row-grid {
              display: grid;
              grid-template-columns: 1fr 1fr;
              gap: 8px;
              border-bottom: 1px solid #000;
              padding-bottom: 8px;
              margin-bottom: 8px;
            }
            .full-width {
              border-bottom: 1px solid #000;
              padding-bottom: 8px;
              margin-bottom: 8px;
            }
            .label-text {
              font-size: 8px;
              text-transform: uppercase;
              font-weight: 700;
              color: #555;
            }
            .val-text {
              font-size: 11px;
              font-weight: 700;
            }
            .big-val {
              font-size: 13px;
              font-weight: 900;
              text-transform: uppercase;
            }
            .cash-badge {
              border: 3px solid #000;
              padding: 8px;
              text-align: center;
              background-color: #000;
              color: #fff;
              margin: 8px 0;
            }
            .cash-badge .amount {
              font-size: 20px;
              font-weight: 900;
            }
            .barcode-visual {
              text-align: center;
              padding: 10px 0;
