import { GoogleGenAI } from "@google/genai";

// Determine the active API key: prioritize user's custom key if provided, then fallback to default
const activeApiKey = process.env.GEMINI_API_KEY || "missing_key_force_error";

// Initialize Gemini - force api key mode to prevent ADC Vertex AI fallback
export const ai = new GoogleGenAI({
  apiKey: activeApiKey,
  httpOptions: { headers: { "User-Agent": "aistudio-build" } },
});

// Decorate generateContent to add automatic retries (exponential backoff) and fallback models on 503/429 errors
const originalGenerateContent = ai.models.generateContent.bind(ai.models);

const FALLBACK_MODELS = [
  "gemini-2.5-flash",
  "gemini-1.5-flash",
  "gemini-2.0-flash-exp",
];

ai.models.generateContent = async function (params: any) {
  let attempt = 0;
  const maxAttempts = 3;
  let delay = 1000; // start with 1s delay
  let lastError: any = null;

  // Keep a copy of original params to manipulate
  const localParams = { ...params };
  const requestedModel = localParams.model;

  while (attempt < maxAttempts) {
    try {
      return await originalGenerateContent(localParams);
    } catch (err: any) {
      lastError = err;
      const status = err?.status || err?.statusCode || err?.code;
      const message = err?.message || "";

      const isRateLimit = status === 429 || message.includes("429") || message.includes("ResourceExhausted") || message.includes("quota");
      const is503 = status === 503 || message.includes("503") || message.includes("UNAVAILABLE") || message.includes("high demand") || message.includes("overloaded");

      if (isRateLimit || is503) {
        attempt++;
        if (attempt >= maxAttempts) {
          break;
        }

        // Try model fallback on 503 / high demand if there is a fallback model available
        if (is503 && attempt < FALLBACK_MODELS.length) {
          const fallbackModel = FALLBACK_MODELS[attempt - 1];
          if (fallbackModel && fallbackModel !== requestedModel) {
            console.warn(`[Gemini Resiliency] Model ${localParams.model} is overloaded. Falling back to ${fallbackModel}.`);
            localParams.model = fallbackModel;
          }
        }

        console.warn(`[Gemini Resiliency] Attempt ${attempt} failed with ${status}. Retrying in ${delay}ms...`);
        await new Promise((resolve) => setTimeout(resolve, delay));
        delay *= 2; // exponential backoff
      } else {
        // Non-transient error, throw immediately
        throw err;
      }
    }
  }

  throw lastError;
};

import React, { createContext, useContext, useEffect, useState, ReactNode } from "react";
import {
  User as FirebaseUser,
  onAuthStateChanged,
  signInWithPopup,
  GoogleAuthProvider,
  signInWithEmailAndPassword,
  createUserWithEmailAndPassword,
  signOut,
  updateProfile,
  sendEmailVerification,
} from "firebase/auth";
import { auth } from "../lib/firebase";
import { ALGERIA_WILAYAS, ALGERIA_SHIPPING_DATA } from "../constants";
import { UserProfile } from "../domains/user/user.types";
import toast from "react-hot-toast";

export const checkIsAdminEmail = (email: string | null | undefined): boolean => {
  if (!email) return false;
  const cleanEmail = email.toLowerCase().trim();
  const adminEmails = [
    "laifa.ait@gmail.com",
    "admin@olmart.dz",
    "admin@olmart.com",
    "admin@olmart.store"
  ];
  return adminEmails.includes(cleanEmail) || cleanEmail.startsWith("admin@");
};

interface AuthContextType {
  currentUser: FirebaseUser | null;
  userProfile: UserProfile | null;
  loading: boolean;
  signInWithGoogle: (role?: string) => Promise<void>;
  signInWithEmail: (email: string, pass: string) => Promise<void>;
  signUpWithEmail: (email: string, pass: string, name: string, role: string) => Promise<void>;
  logout: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<FirebaseUser | null>(null);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribeAuth = onAuthStateChanged(auth, async (user) => {
      setCurrentUser(user);
      if (!user) {
        setUserProfile(null);
        setLoading(false);
      } else {
        // Sync & Fetch initial profile
        try {
          const idToken = await user.getIdToken();
          const response = await fetch("/api/v1/auth/sync", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "Authorization": `Bearer ${idToken}`
            },
            body: JSON.stringify({
              displayName: user.displayName,
              email: user.email,
              photoURL: user.photoURL,
              lastAuthMethod: "auto_sync"
            })
          });
          if (response.ok) {
            const data = await response.json();
            if (data?.success) {
              setUserProfile(data.profile);
            }
          }
        } catch (err) {
          console.error("AuthContext: Sync failed on initial load", err);
        } finally {
          setLoading(false);
        }
      }
    });

    return () => unsubscribeAuth();
  }, []);

  // Poll for profile updates every 60s as a direct replacement for onSnapshot (conforming to instructions)
  useEffect(() => {
    if (!currentUser) return;

    const fetchProfile = async () => {
      try {
        const idToken = await currentUser.getIdToken();
        const response = await fetch("/api/v1/auth/profile", {
          headers: {
            "Authorization": `Bearer ${idToken}`
          }
        });
        if (response.ok) {
          const data = await response.json();
          setUserProfile(data);
        }
      } catch (err) {
        console.error("AuthContext: Periodic profile fetch failed", err);
      }
    };

    fetchProfile();
    const interval = setInterval(fetchProfile, 60000);
    return () => clearInterval(interval);
  }, [currentUser]);

  useEffect(() => {
    const healAdminRole = async () => {
      if (currentUser && checkIsAdminEmail(currentUser.email)) {
        try {
          const idToken = await currentUser.getIdToken(true);
          const response = await fetch("/api/v1/auth/heal-admin", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              "Authorization": `Bearer ${idToken}`
            }
          });
          const data = await response.json();
          if (data?.success) {
            console.log("AuthContext: Admin role checked/healed on backend. Upgraded:", data.upgraded);
            await currentUser.getIdToken(true);
            console.log("AuthContext: ID token refreshed with claims successfully.");
          }
        } catch (err) {
          console.warn("AuthContext: Failed to heal admin role", err);
        }
      }
    };
    healAdminRole();
  }, [currentUser]);

  const signInWithGoogle = async (role?: string) => {
    try {
      const provider = new GoogleAuthProvider();
      provider.setCustomParameters({
        prompt: "select_account",
      });
      const result = await signInWithPopup(auth, provider);
      const user = result.user;

      const idToken = await user.getIdToken();
      const response = await fetch("/api/v1/auth/sync", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${idToken}`
        },
        body: JSON.stringify({
          displayName: user.displayName,
          email: user.email,
          photoURL: user.photoURL,
          role: role || "buyer",
          lastAuthMethod: "google"
        })
      });
      if (response.ok) {
        const data = await response.json();
        if (data?.success) {
          setUserProfile(data.profile);
        }
      }
    } catch (err: any) {
      if (err.code === "auth/popup-blocked") {
        toast.error("Veuillez autoriser les popups pour vous connecter avec Google");
      } else if (err.code === "auth/network-request-failed") {
        toast.error("Erreur réseau. Vérifiez votre connexion.");
      } else {
        toast.error("Erreur de connexion Google");
      }
      console.error("Google sign-in error:", err);
    }
  };

  const signInWithEmail = async (email: string, pass: string) => {
    const result = await signInWithEmailAndPassword(auth, email, pass);
    const user = result.user;

    if (user.emailVerified) {
      const idToken = await user.getIdToken();
      const pendingRole = localStorage.getItem("olmart_pending_registration_role") || "buyer";
      const response = await fetch("/api/v1/auth/sync", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${idToken}`
        },
        body: JSON.stringify({
          displayName: user.displayName || email.split("@")[0],
          email: user.email,
          role: pendingRole,
          lastAuthMethod: "email"
        })
      });
      localStorage.removeItem("olmart_pending_registration_role");
      if (response.ok) {
        const data = await response.json();
        if (data?.success) {
          setUserProfile(data.profile);
        }
      }
    }
  };

  const signUpWithEmail = async (email: string, pass: string, name: string, role: string) => {
    const result = await createUserWithEmailAndPassword(auth, email, pass);
    const user = result.user;
    const userRole = checkIsAdminEmail(email) ? "admin" : role || "buyer";

    await updateProfile(user, { displayName: name });

    const idToken = await user.getIdToken();
    await fetch("/api/v1/auth/sync", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${idToken}`
      },
      body: JSON.stringify({
        displayName: name,
        email: email,
        role: userRole,
        lastAuthMethod: "email"
      })
    });

    await sendEmailVerification(user);

    try {
      localStorage.setItem("olmart_pending_registration_role", userRole);
    } catch { /* ignore */ }
  };

  const logout = async () => {
    await signOut(auth);
  };

  const value = React.useMemo(
    () => ({
      currentUser,
      userProfile,
      loading,
      signInWithGoogle,
      signInWithEmail,
      signUpWithEmail,
      logout,
    }),
    [currentUser, userProfile, loading]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    console.warn("useAuth used outside AuthProvider");
    return { currentUser: null, userProfile: null, loading: false } as unknown as AuthContextType;
  }
  return context;
};

import React, { createContext, useContext, useState, useEffect, ReactNode, useRef } from "react";
import { Product, CartItem, ProductVariant } from "../domains/product/product.types";
import { useAuth } from "./AuthContext";
import { analyticsEngine } from "../utils/analyticsEngine";
import { apiGet, apiPost } from "../lib/api";
import toast from "react-hot-toast";

interface CartContextType {
  cart: CartItem[];
  wishlist: string[];
  addToCart: (productOrId: string | Product, sellerIdOrOptions?: string | Record<string, unknown>, options?: Record<string, unknown>) => void;
  removeFromCart: (index: number) => void;
  updateQuantity: (index: number, qty: number) => void;
  clearCart: (sellerId?: string) => void;
  toggleWishlist: (id: string) => void;
  isCartOpen: boolean;
  setIsCartOpen: (open: boolean) => void;
  revalidateCart: () => Promise<void>;
  getCartItemPrice: (item: CartItem) => number;
  totalPrice: number;
}

const CartContext = createContext<CartContextType | undefined>(undefined);

export const CartProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const auth = useAuth();
  const prevUserRef = useRef<Record<string, unknown> | null>(null);
  const getWishlistKey = () => (auth.currentUser ? `olma_wishlist_${auth.currentUser.uid}` : "olma_wishlist_guest");
  const getCartKey = () => (auth.currentUser ? `olma_cart_${auth.currentUser.uid}` : "olma_cart_guest");

  const [cart, setCart] = useState<CartItem[]>([]);
  const [wishlist, setWishlist] = useState<string[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isInitialized, setIsInitialized] = useState(false);

  // Refs to prevent background fetch race conditions (Deduplication + Cache maps)
  const productDetailsCache = useRef<Record<string, Product>>({});
  const activeProductFetches = useRef<Record<string, Promise<Product | null>>>({});

  // Hydrate cart from backend (prices/names) to avoid stale data
  const hydrateCart = async (cartItems: CartItem[]) => {
    if (!cartItems || cartItems.length === 0) return [];

    const uniqueIds = Array.from(new Set(cartItems.map((item) => item.id)));
    const productDataMap = new Map<string, Product>();

    try {
      const res = await apiPost("/api/v1/products/batch", { ids: uniqueIds });
      if (res && Array.isArray(res.products)) {
        res.products.forEach((p: Product) => {
          productDataMap.set(p.id, p);
        });
      }
    } catch (e) {
      console.error("Hydration batch API error:", e);
    }

    const hydrated = cartItems.map((item) => {
      const pData = productDataMap.get(item.id);
      if (pData) {
        return {
          ...item,
          addedAt: item.addedAt || Date.now(),
          name: pData.name,
          price: pData.price,
          promoPrice: pData.promoPrice,
          flashSaleActive: pData.flashSaleActive,
          flashPrice: pData.flashPrice,
          image: pData.image || pData.images?.[0] || item.image,
          variants: pData.variants || item.variants,
        };
      }
      return item; // fallback
    });
    return hydrated;
  };

  // Sync cart and merge from guest to user
  useEffect(() => {
    setIsInitialized(false);
    const handleAuthChange = async () => {
      let finalCart: CartItem[];
      let finalWishlist: string[];

      const safeParse = <T,>(data: string | null, fallback: T): T => {
        try {
          return data ? JSON.parse(data) : fallback;
        } catch (e) {
          return fallback;
        }
      };

      const guestCartJson = localStorage.getItem("olma_cart_guest");
      const guestCart = safeParse(guestCartJson, []);
      const guestWishlistJson = localStorage.getItem("olma_wishlist_guest");
      const guestWishlist = safeParse(guestWishlistJson, []);

      try {
        if (auth.currentUser) {
          // User is logged in
          const userCartKey = getCartKey();
          const userWishlistKey = getWishlistKey();

          // Fetch user data from Cloud via secure REST endpoints
          let cloudCart: CartItem[] = [];
          let cloudWishlist: string[] = [];

          try {
            const cartRes = await apiGet("/api/v1/auth/cart");
            if (cartRes && Array.isArray(cartRes.items)) {
              cloudCart = cartRes.items;
            }
          } catch (err) {
            console.warn("CartContext: Cloud cart fetch failed. Falling back to local storage.", err);
          }

          try {
            const wishRes = await apiGet("/api/v1/auth/wishlist");
            if (wishRes && Array.isArray(wishRes.items)) {
              cloudWishlist = wishRes.items;
            }
          } catch (err) {
            console.warn("CartContext: Cloud wishlist fetch failed. Falling back to local storage.", err);
          }

          // Fallback to localStorage if cloud is empty
          if (cloudCart.length === 0) {
            const localUserCart = localStorage.getItem(userCartKey);
            if (localUserCart) cloudCart = safeParse(localUserCart, []);
          }
          if (cloudWishlist.length === 0) {
            const localUserWish = localStorage.getItem(userWishlistKey);
            if (localUserWish) cloudWishlist = safeParse(localUserWish, []);
          }

          // MERGE Guest Cart into User Cart if transition just happened
          if (!prevUserRef.current && guestCart.length > 0) {
            guestCart.forEach((gItem: CartItem) => {
              const existingMerge = cloudCart.find(
                (c: CartItem) => c.id === gItem.id && c.selectedVariant === gItem.selectedVariant
              );
              if (existingMerge) {
                existingMerge.quantity += gItem.quantity || 1;
              } else {
                cloudCart.push(gItem);
              }
            });
            localStorage.removeItem("olma_cart_guest");
          }

          // Merge wishlist
          if (!prevUserRef.current && guestWishlist.length > 0) {
            guestWishlist.forEach((wId: string) => {
              if (!cloudWishlist.includes(wId)) cloudWishlist.push(wId);
            });
            localStorage.removeItem("olma_wishlist_guest");
          }

          finalCart = cloudCart;
          finalWishlist = cloudWishlist;
        } else {
          // User is guest
          finalCart = guestCart;
          finalWishlist = guestWishlist;
        }

        // Hydrate
        try {
          finalCart = await hydrateCart(finalCart);
        } catch (hydErr) {
          console.warn("CartContext: Hydration error, using raw cart:", hydErr);
        }
      } catch (globalErr) {
        console.error("CartContext: Error during auth change sync:", globalErr);
        finalCart = guestCart;
        finalWishlist = guestWishlist;
      }

      setCart(finalCart);
      setWishlist(finalWishlist);
      setIsInitialized(true);
      prevUserRef.current = auth.currentUser;
    };

    handleAuthChange();
  }, [auth.currentUser]);

  // Sync to Cloud and LocalStorage whenever cart/wishlist change
  useEffect(() => {
    if (!isInitialized) return;

    const userCartKey = getCartKey();
    const userWishlistKey = getWishlistKey();

    localStorage.setItem(userCartKey, JSON.stringify(cart));
    localStorage.setItem(userWishlistKey, JSON.stringify(wishlist));

    if (auth.currentUser) {
      // Persist to Cloud via secure REST endpoints
      const cartPointers = cart.map((item) => ({
        id: item.id,
        sellerId: item.sellerId,
        quantity: item.quantity,
        selectedVariant: item.selectedVariant || null,
        addedAt: item.addedAt || Date.now(),
      }));

      Promise.all([
        apiPost("/api/v1/auth/cart", { items: cartPointers }),
        apiPost("/api/v1/auth/wishlist", { items: wishlist }),
      ]).catch((err) => console.error("Error syncing cart/wishlist to cloud", err));
    }
  }, [cart, wishlist, isInitialized, auth.currentUser]);

  const addToCart = (productOrId: string | Product, sellerIdOrOptions?: string | Record<string, unknown>, options?: Record<string, unknown>) => {
    let productId: string;
    let sellerId: string;
    let actualOptions: Record<string, unknown> = {};
    let initialDetails: Partial<CartItem> = {};
    let productStock: number | undefined = undefined;

    if (productOrId && typeof productOrId === "object" && 'id' in productOrId) {
      productId = productOrId.id;
      sellerId = productOrId.sellerId || "";
      actualOptions = (sellerIdOrOptions as Record<string, unknown>) || {};
      productStock = (productOrId as Product).stock;
      initialDetails = {
        name: productOrId.name,
        price: productOrId.price,
        promoPrice: productOrId.promoPrice,
        flashSaleActive: productOrId.flashSaleActive,
        flashPrice: productOrId.flashPrice,
        image: productOrId.image || productOrId.images?.[0],
        variants: productOrId.variants,
      };
    } else {
      productId = productOrId as string;
      sellerId = (sellerIdOrOptions as string) || "";
      actualOptions = options || {};
    }

    const quantityToAdd = (actualOptions?.quantity as number) || 1;

    if (productStock !== undefined && productStock < quantityToAdd) {
      toast.error(`Stock insuffisant. Disponible : ${productStock}`);
      return;
    }
    setCart((prev) => {
      const quantityToAdd = (actualOptions?.quantity as number) || 1;
      const selectedVariant = (actualOptions?.selectedVariant as string) || null;

      const existingItemIndex = prev.findIndex((item) => {
        const v1 = item.selectedVariant || null;
        const v2 = selectedVariant || null;
        return item.id === productId && v1 === v2;
      });

      if (existingItemIndex !== -1) {
        const newCart = [...prev];
        newCart[existingItemIndex] = {
          ...newCart[existingItemIndex],
          quantity: newCart[existingItemIndex].quantity + quantityToAdd,
          addedAt: Date.now(),
        };
        return newCart;
      }

      return [
        ...prev,
        {
          id: productId,
          sellerId: sellerId,
          quantity: quantityToAdd,
          selectedVariant: selectedVariant,
          addedAt: Date.now(),
          ...initialDetails,
          ...actualOptions,
        },
      ];
    });

    const fetchLatestDetails = async () => {
      if (productDetailsCache.current[productId]) {
        const pData = productDetailsCache.current[productId];
        setCart((prev) =>
          prev.map((item) => {
            if (item.id === productId) {
              return {
                ...item,
                name: pData.name,
                price: pData.price,
                promoPrice: pData.promoPrice,
                image: pData.image || pData.images?.[0] || item.image,
                variants: pData.variants || item.variants,
              };
            }
            return item;
          })
        );
        return;
      }

      if (activeProductFetches.current[productId] !== undefined) {
        try {
          const pData = await activeProductFetches.current[productId];
          if (pData) {
            setCart((prev) =>
              prev.map((item) => {
                if (item.id === productId) {
                  return {
                    ...item,
                    name: pData.name,
                    price: pData.price,
                    promoPrice: pData.promoPrice,
                    image: pData.image || pData.images?.[0] || item.image,
                    variants: pData.variants || item.variants,
                  };
                }
                return item;
              })
            );
          }
        } catch (e) {
          console.warn("Deduplicated background fetch catch:", e);
        }
        return;
      }

      const fetchPromise = (async () => {
        try {
          const data = await apiGet(`/api/v1/products/${productId}`);
          if (data) {
            productDetailsCache.current[productId] = data;
            return data;
          }
        } catch (err) {
          console.error("Error fetching single product details", err);
        }
        return null;
      })();

      activeProductFetches.current[productId] = fetchPromise;

      try {
        const pData = await fetchPromise;
        if (pData) {
          setCart((prev) => {
            return prev.map((item) => {
              if (item.id === productId) {
                return {
                  ...item,
                  name: pData.name,
                  price: pData.price,
                  promoPrice: pData.promoPrice,
                  image: pData.image || pData.images?.[0] || item.image,
                  variants: pData.variants || item.variants,
                };
              }
              return item;
            });
          });
        }
      } catch (err) {
        console.warn("Background fetch of product details skipped:", err);
      } finally {
        delete activeProductFetches.current[productId];
      }
    };
    fetchLatestDetails();

    setIsCartOpen(true);
  };

  const removeFromCart = (index: number) => {
    const item = cart[index];
    if (item) {
      analyticsEngine.track("remove_from_cart", {
        productId: item.id,
        name: item.name,
        price: item.price,
      });
    }
    setCart((prev) => prev.filter((_, i) => i !== index));
  };

  const clearCart = (sellerId?: string) => {
    if (sellerId) {
      setCart((prev) => prev.filter((item) => item.sellerId !== sellerId));
    } else {
      setCart([]);
    }
  };

  const updateQuantity = (index: number, qty: number) => {
    const MAX_QTY = 99;
    if (qty <= 0) {
      removeFromCart(index);
      return;
    }
    if (qty > MAX_QTY) {
      toast.error(`Quantité maximum : ${MAX_QTY}`);
      return;
    }
    setCart((prev) => {
      const next = [...prev];
      if (next[index]) {
        next[index] = { ...next[index], quantity: qty };
      }
      return next;
    });
  };

  const revalidateCart = async () => {
    const updated = await hydrateCart(cart);
    setCart(updated);
  };

  const getCartItemPrice = (item: CartItem) => {
    const isFlashActive = !!(
      item.flashSaleActive &&
      item.flashPrice &&
      (!item.flashEndDate || new Date(item.flashEndDate).getTime() > Date.now())
    );
    const rawPrice: number | string | undefined = isFlashActive
      ? item.flashPrice
      : item.promoPrice !== undefined && item.promoPrice !== null && (item.promoPrice as number | string) !== ""
        ? item.promoPrice
        : item.price;
    let targetPrice = 0;

    if (rawPrice !== undefined && rawPrice !== null) {
      if (typeof rawPrice === "number") {
        targetPrice = rawPrice;
      } else if (typeof rawPrice === "string" && rawPrice.trim() !== "") {
        const cleanStr = rawPrice.replace(/[^\d.]/g, "");
        targetPrice = parseFloat(cleanStr) || 0;
      }
    }

    if (item.selectedVariant && item.variants && Array.isArray(item.variants)) {
      const variant = item.variants.find((v: ProductVariant) => v.name === item.selectedVariant);
      if (variant) {
        if (variant.priceOverride !== undefined && variant.priceOverride !== null && variant.priceOverride !== "") {
          targetPrice = Number(variant.priceOverride) || 0;
        } else if (variant.priceDiff) {
          targetPrice += Number(variant.priceDiff) || 0;
        }
      }
    }
    return isNaN(targetPrice) ? 0 : targetPrice;
  };

  const totalPrice = cart.reduce((sum, item) => sum + getCartItemPrice(item) * (item.quantity || 1), 0);

  const toggleWishlist = (id: string) => {
    const isAdding = !wishlist.includes(id);
    analyticsEngine.track("wishlist_toggle", {
      productId: id,
      action: isAdding ? "add" : "remove",
    });
    setWishlist((prev) => (prev.includes(id) ? prev.filter((wishId) => wishId !== id) : [...prev, id]));
  };

  return (
    <CartContext.Provider
      value={{
        cart,
        wishlist,
        addToCart,
        removeFromCart,
        clearCart,
        updateQuantity,
        revalidateCart,
        toggleWishlist,
        isCartOpen,
        setIsCartOpen,
        getCartItemPrice,
        totalPrice,
      }}
    >
      {children}
    </CartContext.Provider>
  );
};

export const useCart = () => {
  const context = useContext(CartContext);
  if (context === undefined) {
    throw new Error("useCart must be used within a CartProvider");
  }
  return context;
};

import React, { createContext, useContext, useState, useEffect } from "react";
import { defaultCategoriesData } from "../data/megaMenuData";
import { useShop } from "./ShopContext";
import { apiGet, apiPost } from "../lib/api";
import toast from "react-hot-toast";

export interface MegaMenuLink {
  name: string;
  featuredProduct?: FeaturedProduct;
}

export interface MegaMenuSubcategory {
  name: string;
  image?: string;
  links: MegaMenuLink[];
}

export interface FeaturedProduct {
  productId: string;
}

export interface MegaMenuCategory {
  id: string;
  name: string;
  featuredProduct?: FeaturedProduct;
  sections: MegaMenuSubcategory[];
  iconUrl?: string; // custom uploaded icon
}

interface MegaMenuContextType {
  categoriesData: MegaMenuCategory[];
  isLoading: boolean;
  setCategoriesData: React.Dispatch<React.SetStateAction<MegaMenuCategory[]>>;
  updateFeaturedProduct: (categoryId: string, product: FeaturedProduct) => void;
  updateLinkFeaturedProduct: (
    categoryId: string,
    sectionName: string,
    linkName: string,
    product: FeaturedProduct | undefined
  ) => void;
  saveMegaMenuToFirestore: (customData?: MegaMenuCategory[]) => Promise<void>;
}

const MegaMenuContext = createContext<MegaMenuContextType | undefined>(undefined);

export const MegaMenuProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { categoryHierarchy, refreshHierarchy } = useShop();
  const [categoriesData, setCategoriesData] = useState<MegaMenuCategory[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    let isCancelled = false;
    const loadMegaMenu = async () => {
      setIsLoading(true);
      try {
        const data = await apiGet("/api/v1/settings/megamenu");

        if (data && data.categoriesData) {
          if (!isCancelled) {
            setCategoriesData(data.categoriesData);
          }
          setIsLoading(false);
          return;
        }
      } catch (err) {
        console.error("Error fetching megamenu from settings, using local fallback:", err);
      }

      const saved = localStorage.getItem("olma_megamenu_data_v6");
      let existingData: MegaMenuCategory[] = [];
      if (saved) {
        try {
          existingData = JSON.parse(saved);
        } catch (e) {
          console.warn("Failed to parse saved megamenu:", e);
        }
      }

      const catIdMap: Record<string, string> = {
        "Maison & Déco": "maison",
        Électronique: "electronique",
        Électroménager: "electromenager",
        Mode: "mode",
        "Beauté & Santé": "beaute",
        "Auto & Moto": "auto",
        "Sport & Loisirs": "sport",
        "Bébé & Puériculture": "bebe",
        "Bricolage & Outillage": "bricolage",
        "Jeux & Jouets": "jouets",
        Supermarché: "supermarche",
      };

      const newData: MegaMenuCategory[] = Object.entries(categoryHierarchy).map(([catName, subcats]) => {
        const existingCat = existingData.find((c) => c.name === catName);
        return {
          id: existingCat?.id || catIdMap[catName] || catName.toLowerCase().replace(/[^a-z0-9]+/g, "-"),
          name: catName,
          iconUrl: existingCat?.iconUrl,
          featuredProduct: existingCat?.featuredProduct,
          sections: Object.entries(subcats).map(([subcatName, links]) => {
            const existingSection = existingCat?.sections?.find((s) => s.name === subcatName);
            return {
              name: subcatName,
              image: existingSection?.image,
              links: links.map((linkName) => {
                const existingLink = existingSection?.links?.find((l) => l.name === linkName);
                return {
                  name: linkName,
                  featuredProduct: existingLink?.featuredProduct,
                };
              }),
            };
          }),
        };
      });

      if (!isCancelled) {
        setCategoriesData(newData);
        setIsLoading(false);
      }
    };

    loadMegaMenu();

    return () => {
      isCancelled = true;
    };
  }, [categoryHierarchy]);

  useEffect(() => {
    if (categoriesData.length > 0) {
      localStorage.setItem("olma_megamenu_data_v6", JSON.stringify(categoriesData));
    }
  }, [categoriesData]);

  const saveMegaMenuToFirestore = async (customData?: MegaMenuCategory[]) => {
    const dataToSave = customData || categoriesData;
    try {
      toast.loading("Enregistrement du Mega Menu...", { id: "save-megamenu" });
      await apiPost("/api/v1/settings/megamenu", {
        categoriesData: dataToSave,
        updatedAt: new Date().toISOString(),
      });

      const newHierarchy: Record<string, Record<string, string[]>> = {};
      const sortOrder: string[] = [];

      dataToSave.forEach((cat) => {
        sortOrder.push(cat.name);
        const subMap: Record<string, string[]> = {};
        cat.sections.forEach((sec) => {
          subMap[sec.name] = sec.links.map((link) => link.name);
        });
        newHierarchy[cat.name] = subMap;
      });

      await apiPost("/api/v1/settings/categories", {
        hierarchy: newHierarchy,
        sortOrder: sortOrder,
        updatedAt: new Date().toISOString(),
      });

      await refreshHierarchy();

      toast.success("Mega Menu enregistré avec succès ! ✨🚀", { id: "save-megamenu" });
    } catch (err) {
      console.error("Error saving megamenu to backend:", err);
      toast.error("Erreur lors de la sauvegarde du Mega Menu", { id: "save-megamenu" });
    }
  };

  const updateFeaturedProduct = (categoryId: string, product: FeaturedProduct) => {
    setCategoriesData((current) =>
      current.map((cat) => (cat.id === categoryId ? { ...cat, featuredProduct: product } : cat))
    );
  };

  const updateLinkFeaturedProduct = (
    categoryId: string,
    sectionName: string,
    linkName: string,
    product: FeaturedProduct | undefined
  ) => {
    setCategoriesData((current) =>
      current.map((cat) => {
        if (cat.id !== categoryId) return cat;
        return {
          ...cat,
          sections: cat.sections.map((sec) => {
            if (sec.name !== sectionName) return sec;
            return {
              ...sec,
              links: sec.links.map((link) => {
                if (link.name !== linkName) return link;
                return { ...link, featuredProduct: product };
              }),
            };
          }),
        };
      })
    );
  };

  return (
    <MegaMenuContext.Provider
      value={{
        categoriesData,
        isLoading,
        setCategoriesData,
        updateFeaturedProduct,
        updateLinkFeaturedProduct,
        saveMegaMenuToFirestore,
      }}
    >
      {children}
    </MegaMenuContext.Provider>
  );
};

export const useMegaMenu = () => {
  const context = useContext(MegaMenuContext);
  if (context === undefined) {
    throw new Error("useMegaMenu must be used within a MegaMenuProvider");
  }
  return context;
};

import React, { createContext, useContext, useState, ReactNode } from "react";
import { Product } from "../domains/product/product.types";
import { PRODUCT_HIERARCHY } from "../constants";
import { apiGet, apiPost } from "../lib/api";

class LocalMemoryCache {
  private cache: Record<string, { data: any; expiry: number }> = {};
  set(key: string, data: any, durationMs = 300000) {
    this.cache[key] = { data, expiry: Date.now() + durationMs };
  }
  get(key: string): any | null {
    const item = this.cache[key];
    if (item && Date.now() < item.expiry) {
      return item.data;
    }
    if (item) delete this.cache[key];
    return null;
  }
  clear() {
    this.cache = {};
  }
}
const cacheEngine = new LocalMemoryCache();

function handleDevQuotaLogger(context: string, isFromCache: boolean) {
  if (import.meta.env.DEV) {
    if (process.env.NODE_ENV === 'development') {
      console.log(
        `%c[Olma Dev-Safe Layer] %c${context} %c${isFromCache ? "⚡ SWR CACHED" : "📦 LIVE (REST)"}`,
        "color: #C95D3B; font-weight: bold;",
        "color: inherit;",
        isFromCache ? "color: #38bdf8; font-weight: bold;" : "color: #34d399; font-weight: bold;"
      );
    }
  }
}

interface ShopContextType {
  fetchFeaturedProducts: (nbLimit?: number) => Promise<Product[]>;
  fetchProductsByCategory: (category: string, nbLimit?: number) => Promise<Product[]>;
  fetchProductsByIds: (ids: string[]) => Promise<Product[]>;
  fetchRecommendedProducts: (nbLimit?: number) => Promise<Product[]>;
  fetchCrossSellProducts: (product: Product, nbLimit?: number) => Promise<Product[]>;
  // Category Hierarchy
  categoryHierarchy: Record<string, Record<string, string[]>>;
  refreshHierarchy: () => Promise<void>;
  // keep remaining for UI state
  activeCategory: string;
  setActiveCategory: (cat: string) => void;
  searchQuery: string;
  setSearchQuery: (query: string) => void;
  isSaleFilterActive: boolean;
  setIsSaleFilterActive: (active: boolean) => void;
  activeTag: string | null;
  setActiveTag: (tag: string | null) => void;
  sortOption: string;
  setSortOption: (option: string) => void;
  activeWilaya: string;
  setActiveWilaya: (wilaya: string) => void;
}

const ShopContext = createContext<ShopContextType | undefined>(undefined);

export const ShopProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [activeCategory, setActiveCategory] = useState("Tous");
  const [searchQuery, setSearchQuery] = useState("");
  const [isSaleFilterActive, setIsSaleFilterActive] = useState(false);
  const [activeTag, setActiveTag] = useState<string | null>(null);
  const [sortOption, setSortOption] = useState("quality");
  const [activeWilaya, setActiveWilaya] = useState("Tous");
  const [categoryHierarchy, setCategoryHierarchy] =
    useState<Record<string, Record<string, string[]>>>(PRODUCT_HIERARCHY);

  const refreshHierarchy = async () => {
    try {
      const data = await apiGet("/api/v1/settings/categories");
      if (data && data.hierarchy) {
        const rawHierarchy = data.hierarchy;
        const sortOrder = data.sortOrder || [];

        const sortedHierarchy: Record<string, Record<string, string[]>> = {};

        sortOrder.forEach((key: string) => {
          if (rawHierarchy[key]) {
            sortedHierarchy[key] = rawHierarchy[key];
          }
        });

        Object.keys(rawHierarchy).forEach((key) => {
          if (!sortedHierarchy[key]) {
            sortedHierarchy[key] = rawHierarchy[key];
          }
        });

        setCategoryHierarchy(sortedHierarchy);
      }
    } catch (err) {
      console.error("Error refreshing hierarchy:", err);
    }
  };

  React.useEffect(() => {
    refreshHierarchy();
  }, []);

  const fetchFeaturedProducts = async (nbLimit = 20): Promise<Product[]> => {
    const cacheKey = `featured_products_${nbLimit}`;
    const cached = cacheEngine.get(cacheKey);
    if (cached) {
      handleDevQuotaLogger("fetchFeaturedProducts (CACHE)", true);
      return cached;
    }

    try {
      const data = await apiGet(`/api/v1/products?featured=true&limit=${nbLimit}`);
      if (data && Array.isArray(data.products)) {
        cacheEngine.set(cacheKey, data.products);
        return data.products;
      }
      return [];
    } catch (err) {
      console.error("fetchFeaturedProducts failed:", err);
      return [];
    }
  };

  const fetchProductsByCategory = async (category: string, nbLimit = 20): Promise<Product[]> => {
    const cacheKey = `products_category_${category}_${nbLimit}`;
    const cached = cacheEngine.get(cacheKey);
    if (cached) {
      handleDevQuotaLogger(`fetchProductsByCategory [${category}] (CACHE)`, true);
      return cached;
    }

    try {
      const url = category === "Tous" 
        ? `/api/v1/products?limit=${nbLimit}`
        : `/api/v1/products?category=${encodeURIComponent(category)}&limit=${nbLimit}`;
      const data = await apiGet(url);
      if (data && Array.isArray(data.products)) {
        cacheEngine.set(cacheKey, data.products);
        return data.products;
      }
      return [];
    } catch (err) {
      console.error("fetchProductsByCategory failed:", err);
      return [];
    }
  };

  const fetchProductsByIds = async (ids: string[]): Promise<Product[]> => {
    if (!ids || ids.length === 0) return [];

    const cacheKey = `products_ids_${ids.sort().join("_")}`;
    const cached = cacheEngine.get(cacheKey);
    if (cached) {
      handleDevQuotaLogger("fetchProductsByIds (CACHE)", true);
      return cached;
    }

    try {
      const res = await apiPost("/api/v1/products/batch", { ids });
      if (res && Array.isArray(res.products)) {
        cacheEngine.set(cacheKey, res.products);
        return res.products;
      }
      return [];
    } catch (err) {
      console.error("fetchProductsByIds failed:", err);
      return [];
    }
  };

  const fetchCrossSellProducts = React.useCallback(async (currentProduct: Product, nbLimit = 4): Promise<Product[]> => {
    let targetCategory = "Accessoires";
    const catLower = (currentProduct.category || "").toLowerCase();

    if (catLower.includes("mode") || catLower.includes("vêtement")) targetCategory = "Accessoires";
    else if (catLower.includes("téléphone") || catLower.includes("smartphone"))
      targetCategory = "Accessoires Téléphonie";
    else if (catLower.includes("pc") || catLower.includes("ordinateur")) targetCategory = "Périphériques";

    try {
      const data = await apiGet(`/api/v1/products/cross-sell?sellerId=${encodeURIComponent(currentProduct.sellerId)}&category=${encodeURIComponent(targetCategory)}&currentProductId=${encodeURIComponent(currentProduct.id)}&limit=${nbLimit}`);
      if (data && Array.isArray(data.products)) {
        return data.products;
      }
      return [];
    } catch (err) {
      console.error("fetchCrossSellProducts failed:", err);
      return [];
    }
  }, []);

  const fetchRecommendedProducts = async (nbLimit = 8): Promise<Product[]> => {
    const cacheKey = `recommended_products_${nbLimit}`;
    const cached = cacheEngine.get(cacheKey);
    if (cached) {
      handleDevQuotaLogger("fetchRecommendedProducts (CACHE)", true);
      return cached;
    }

    try {
      const data = await apiGet("/api/v1/metadata/recommendations");
      let recommendedIds: string[] = [];
      if (data && Array.isArray(data.productIds)) {
        recommendedIds = data.productIds;
      }

      if (recommendedIds.length > 0) {
        const slicedIds = recommendedIds.slice(0, nbLimit);
        const resolved = await fetchProductsByIds(slicedIds);
        if (resolved.length > 0) {
          cacheEngine.set(cacheKey, resolved);
          return resolved;
        }
      }

      const fallback = await fetchFeaturedProducts(nbLimit);
      cacheEngine.set(cacheKey, fallback);
      return fallback;
    } catch (err) {
      console.error("Error fetching recommended products:", err);
      return fetchFeaturedProducts(nbLimit);
    }
  };

  return (
    <ShopContext.Provider
      value={{
        fetchFeaturedProducts,
        fetchProductsByCategory,
        fetchProductsByIds,
        fetchRecommendedProducts,
        fetchCrossSellProducts,
        activeCategory,
        setActiveCategory,
        searchQuery,
        setSearchQuery,
        isSaleFilterActive,
        setIsSaleFilterActive,
        activeTag,
        setActiveTag,
        sortOption,
        setSortOption,
        activeWilaya,
        setActiveWilaya,
        categoryHierarchy,
        refreshHierarchy,
      }}
    >
      {children}
    </ShopContext.Provider>
  );
};

export const useShop = () => {
  const context = useContext(ShopContext);
  if (context === undefined) {
    throw new Error("useShop must be used within a ShopProvider");
  }
  return context;
};

import { Request, Response } from 'express';
export interface AuthenticatedRequest extends Request { user?: any; file?: any; files?: any; }

import { Router } from "express";
import { authenticateToken } from "../../middlewares/auth";
import { admin, db } from "../../config/firebase-admin";
import { ALGERIA_WILAYAS, ALGERIA_SHIPPING_DATA } from "../../constants";

const router = Router();

router.post("/onboard", authenticateToken, async (req: AuthenticatedRequest, res: Response) => {
  const uid = req.user.uid;
  try {
    const { name, phone, wilaya, address, role, interests } = req.body;

    if (!name || !phone || !wilaya || !address || !role) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const userRef = db.collection("users").doc(uid);
    const userSnap = await userRef.get();
    const existingUserData = userSnap.exists ? userSnap.data() : {};

    const updateObj: any = {
      uid,
      email: req.user.email || "",
      displayName: name,
      phone,
      wilaya,
      address,
      preferences: {
        interests: interests || [],
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      },
      isVerified: existingUserData?.isVerified ?? false,
      onboardingCompleted: true,
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    };

    if (!existingUserData?.createdAt) {
      updateObj.createdAt = admin.firestore.FieldValue.serverTimestamp();
    }

    // Ensure we don't accidentally downgrade an admin
    if (existingUserData?.role !== 'admin') {
      updateObj.role = role;
      if (role === 'seller') {
        updateObj.trustScore = 50;
        updateObj.status = 'pending_verification';

        // Hydrate default regulated shipping tariffs
        const defaultTariffs: Record<string, number> = {};
        ALGERIA_WILAYAS.forEach((w: string) => {
          const cleanName = w.replace(/^\d+\s+/, "").trim();
          const known = ALGERIA_SHIPPING_DATA[cleanName] || ALGERIA_SHIPPING_DATA.Default;
          defaultTariffs[w] = known.price;
        });
        updateObj.shippingTariffs = defaultTariffs;
      }
    }

    await userRef.set(updateObj, { merge: true });

    // Sync roles to custom claims
    const customClaims = {
      role: updateObj.role || 'customer'
    };
    await admin.auth().setCustomUserClaims(uid, customClaims);

    return res.json({ success: true, message: "Onboarding completed successfully" });
  } catch (error: any) {
    console.error("Onboarding error:", error);
    return res.status(500).json({ error: error.message });
  }
});

router.post("/seller-onboard", authenticateToken, async (req: AuthenticatedRequest, res: Response) => {
  const uid = req.user.uid;
  try {
    const { storeName, storeDescription, documentId, rib } = req.body;
    if (!storeName || !storeDescription) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const userRef = db.collection('users').doc(uid);
    await userRef.update({
      storeName,
      storeDescription,
      documentId: documentId || "",
      rib: rib || "",
      onboardingCompleted: true,
      sellerOnboardingCompleted: true,
      updatedAt: admin.firestore.FieldValue.serverTimestamp()
    });

    return res.json({ success: true, message: "Seller onboarding completed successfully" });
  } catch (error: any) {
    console.error("Seller onboarding error:", error);
    return res.status(500).json({ error: error.message });
  }
});

router.post("/sync-user-claims", authenticateToken, async (req: AuthenticatedRequest, res: Response) => {
  const uid = req.user.uid;
  try {
    const userDoc = await db.collection('users').doc(uid).get();
    if (userDoc.exists) {
      const userData = userDoc.data();
      const customClaims = {
        role: userData?.role || 'customer'
      };

      await admin.auth().setCustomUserClaims(uid, customClaims);
      return res.json({ success: true, message: "Claims synced successfully" });
    } else {
      return res.status(404).json({ error: "User not found in Firestore" });
    }
  } catch (error: any) {
    console.error("Error syncing claims:", error);
    res.status(500).json({ error: error.message });
  }
});

const checkIsAdminEmail = (email: string | null | undefined): boolean => {
  if (!email) return false;
  const cleanEmail = email.toLowerCase().trim();
  const adminEmails = [
    "laifa.ait@gmail.com",
    "admin@olmart.dz",
    "admin@olmart.com",
    "admin@olmart.store"
  ];
  return adminEmails.includes(cleanEmail) || cleanEmail.startsWith("admin@");
};

router.post("/sync", authenticateToken, async (req: AuthenticatedRequest, res: Response) => {
  const uid = req.user.uid;
  const { displayName, email, photoURL, role, lastAuthMethod } = req.body;
  try {
    const userRef = db.collection('users').doc(uid);
    const userDoc = await userRef.get();

    if (!userDoc.exists) {
      const userRole = checkIsAdminEmail(email) ? "admin" : role || "buyer";
      const userStatus = userRole === "seller" ? "pending_verification" : "active";

      const defaultTariffs: Record<string, number> = {};
      if (userRole === "seller") {
        ALGERIA_WILAYAS.forEach((w: string) => {
          const cleanName = w.replace(/^\d+\s+/, "").trim();
          const known = ALGERIA_SHIPPING_DATA[cleanName] || ALGERIA_SHIPPING_DATA.Default;
          defaultTariffs[w] = known.price;
        });
      }

      const initialProfile = {
        uid,
        displayName: displayName || "Utilisateur",
        email: email || "",
        photoURL: photoURL || "",
        role: userRole,
        onboardingCompleted: false,
        status: userStatus,
        createdAt: admin.firestore.FieldValue.serverTimestamp(),
        lastAuthMethod: lastAuthMethod || "google",
        ...(userRole === "seller" ? { isVerified: false, trustScore: 50, shippingTariffs: defaultTariffs } : {}),
      };

      await userRef.set(initialProfile);

      if (userRole === "seller") {
        try {
          await db.collection("internal_notifications").add({
            type: "NEW_SELLER_REGISTRATION",
            title: "Nouvelle Inscription Vendeur",
            message: `Le vendeur "${displayName || 'Inconnu'}" vient de s'inscrire sur la plateforme et attend la vérification de compte.`,
            sellerId: uid,
            createdAt: admin.firestore.FieldValue.serverTimestamp(),
            read: false,
          });
        } catch (err) {
          console.warn("Failed sending seller registration internal notification", err);
        }
      }

      return res.json({ success: true, profile: initialProfile });
    } else {
      return res.json({ success: true, profile: { uid: userDoc.id, ...userDoc.data() } });
    }
  } catch (error: any) {
    console.error("Error syncing user profile:", error);
    res.status(500).json({ error: error.message });
  }
});

