import { db, admin } from "../../config/firebase-admin";

export interface IProductRepository {
  findById(id: string): Promise<any | null>;
  create(data: any): Promise<string>;
  update(id: string, data: any): Promise<void>;
  delete(id: string): Promise<void>;
  findAllActive(limit?: number): Promise<any[]>;
}

export class FirebaseProductRepository implements IProductRepository {
  async findById(id: string): Promise<any | null> {
    const doc = await db.collection("products").doc(id).get();
    return doc.exists ? { id: doc.id, ...doc.data() } : null;
  }

  async create(data: any): Promise<string> {
    const safeData = { ...data, createdAt: admin.firestore.FieldValue.serverTimestamp() };
    const docRef = await db.collection("products").add(safeData);
    return docRef.id;
  }

  async update(id: string, data: any): Promise<void> {
    const safeData = { ...data, updatedAt: admin.firestore.FieldValue.serverTimestamp() };
    await db.collection("products").doc(id).update(safeData);
  }

  async delete(id: string): Promise<void> {
    await db.collection("products").doc(id).update({ 
      deletedAt: admin.firestore.FieldValue.serverTimestamp(),
      status: "deleted"
    }); // Soft delete
  }

  async findAllActive(limitVal = 50): Promise<any[]> {
    const snap = await db.collection("products")
      .where("status", "==", "active")
      .limit(limitVal)
      .get();
    return snap.docs.map(doc => ({ id: doc.id, ...doc.data() }));
  }
}

