      return { id: doc.id, ...data };
    });

    loadedReviews.sort((a, b) => {
      const ta = a.createdAt && typeof a.createdAt.toDate === "function" ? a.createdAt.toDate().getTime() : new Date(a.createdAt || 0).getTime();
      const tb = b.createdAt && typeof b.createdAt.toDate === "function" ? b.createdAt.toDate().getTime() : new Date(b.createdAt || 0).getTime();
      return tb - ta;
    });

    return res.json({ reviews: loadedReviews });
  } catch (error: any) {
    return res.status(500).json({ error: error.message });
  }
});

