import { db, admin } from "../../config/firebase-admin";

export interface IReviewRepository {
  getReview(id: string): Promise<any | null>;
  addReview(data: any): Promise<void>;
  updateReview(id: string, data: any): Promise<void>;
  reportReview(id: string, reason: string): Promise<void>;
  addReply(id: string, reply: any): Promise<void>;
  approveReview(id: string): Promise<void>;
}

export class FirebaseReviewRepository implements IReviewRepository {
  async getReview(id: string): Promise<any | null> {
    const snap = await db.collection("reviews").doc(id).get();
    return snap.exists ? { id: snap.id, ...snap.data() } : null;
  }

  async addReview(data: any): Promise<void> {
    const reviewId = data.productId + "_" + data.userId;
    await db.collection("reviews").doc(reviewId).set({
      ...data,
      createdAt: admin.firestore.FieldValue.serverTimestamp(),
      status: "pending",
      flags: 0,
      replies: []
    });

    const statsRef = db.collection("products").doc(data.productId);
    await db.runTransaction(async (t) => {
      const doc = await t.get(statsRef);
      if (doc.exists) {
        const currentStats = doc.data()?.stats || { totalReviews: 0, averageRating: 0 };
        const newTotal = currentStats.totalReviews + 1;
        const newAverage = ((currentStats.averageRating * currentStats.totalReviews) + data.rating) / newTotal;
        t.update(statsRef, {
          stats: {
            totalReviews: newTotal,
            averageRating: newAverage,
            lastReviewAt: admin.firestore.FieldValue.serverTimestamp()
          }
        });
      }
    });
  }

  async updateReview(id: string, data: any): Promise<void> {
    await db.collection("reviews").doc(id).update(data);
  }

  async reportReview(id: string, reason: string): Promise<void> {
    await db.collection("reviews").doc(id).update({
      flags: admin.firestore.FieldValue.increment(1),
      status: "flagged",
      lastReportedReason: reason,
      lastReportedAt: admin.firestore.FieldValue.serverTimestamp()
    });
  }

  async addReply(id: string, reply: any): Promise<void> {
    await db.collection("reviews").doc(id).update({
      replies: admin.firestore.FieldValue.arrayUnion({
        ...reply,
        createdAt: new Date().toISOString()
      }),
      status: "replied"
    });
  }

  async approveReview(id: string): Promise<void> {
    await db.collection("reviews").doc(id).update({
      status: "published",
      flags: 0
    });
  }
}

