import { IReviewRepository } from "./review.repository";

export class ReviewService {
  constructor(private readonly repo: IReviewRepository) {}

  async submitReview(userId: string, data: any): Promise<{ success: boolean }> {
    const { productId, rating, comment, images } = data;
    if (!productId || !rating) throw new Error("Produit et note requis");

    await this.repo.addReview({
      productId,
      userId,
      rating,
      comment: comment || "",
      images: images || [],
    });

    return { success: true };
  }

  async reportReview(reviewId: string, reason: string): Promise<{ success: boolean }> {
    if (!reviewId || !reason) throw new Error("ID de l'avis et raison requis");
    await this.repo.reportReview(reviewId, reason);
    return { success: true };
  }

  async approveReview(reviewId: string): Promise<{ success: boolean }> {
    if (!reviewId) throw new Error("ID de l'avis requis");
    await this.repo.approveReview(reviewId);
    return { success: true };
  }

  async replyToReview(reviewId: string, sellerId: string, replyText: string): Promise<{ success: boolean }> {
    if (!reviewId || !replyText) throw new Error("ID de l'avis et texte de réponse requis");

    const review = await this.repo.getReview(reviewId);
    if (!review) throw new Error("Avis introuvable");

    await this.repo.addReply(reviewId, {
      sellerId,
      text: replyText
    });

    return { success: true };
  }
}

import { db, admin } from "../../config/firebase-admin";
import { UserProfile, userProfileSchema } from "./user.schema";

export interface IUserRepository {
  findById(uid: string): Promise<UserProfile | null>;
  create(uid: string, data: Partial<UserProfile>): Promise<void>;
  update(uid: string, data: Partial<UserProfile>): Promise<void>;
  delete(uid: string): Promise<void>;
  findAll(limit?: number, offset?: string): Promise<UserProfile[]>;
}

export class FirebaseUserRepository implements IUserRepository {
  async findById(uid: string): Promise<UserProfile | null> {
    const doc = await db.collection("users").doc(uid).get();
    if (!doc.exists) return null;
    try {
      return userProfileSchema.parse({ uid, ...doc.data() });
    } catch (e) {
      console.error("Zod Validation Error on DB read", e);
      return { uid, ...doc.data() } as any; // Fallback
    }
  }

  async create(uid: string, data: Partial<UserProfile>): Promise<void> {
    const safeData = { ...data, uid, createdAt: admin.firestore.FieldValue.serverTimestamp() };
    await db.collection("users").doc(uid).set(safeData);
  }

  async update(uid: string, data: Partial<UserProfile>): Promise<void> {
    const safeData = { ...data, updatedAt: admin.firestore.FieldValue.serverTimestamp() };
    await db.collection("users").doc(uid).update(safeData);
  }

  async delete(uid: string): Promise<void> {
    await db.collection("users").doc(uid).update({ deletedAt: admin.firestore.FieldValue.serverTimestamp() }); // Soft delete
  }

  async findAll(limitVal = 50, startAfterId?: string): Promise<UserProfile[]> {
    let q = db.collection("users").limit(limitVal);
    if (startAfterId) {
      const startDoc = await db.collection("users").doc(startAfterId).get();
      if (startDoc.exists) q = q.startAfter(startDoc);
    }
    const snap = await q.get();
    return snap.docs.map(doc => ({ uid: doc.id, ...doc.data() } as any));
  }
}

